INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p99-23', 'doc-04-nist-sp-800-86', '', 99, 'Each way of shutting down a particular OS can cause different types of data to be preserved or corrupted; analysts should be aware of the typical shutdown behavior of each OS.', 'kb-doc-04-nist-sp-800-86-p99-23', 0, 31, '04-nist-sp-800-86', 'retrieved', '2136E47D7642BA5EC2C2CE56CED3ED89809A578B6AEAA36521B966CE05A6D11E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
