INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p100-1', 'doc-04-nist-sp-800-86', '', 100, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE A.2.2 A.2.3 Examination and Analysis ! Analysts should use a methodical approach to studying the data.', 'kb-doc-04-nist-sp-800-86-p100-1', 0, 24, '04-nist-sp-800-86', 'retrieved', 'C8911DB222697D991A92F101F4ACCD383E0CB26ECA2BB0B11D0469D100876E1F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p100-2', 'doc-04-nist-sp-800-86', '', 100, 'The foundation of forensics is using a methodical approach in analyzing the available data so that analysts can either draw appropriate conclusions based on the available data, or determine that no conclusion can yet be drawn.', 'kb-doc-04-nist-sp-800-86-p100-2', 0, 36, '04-nist-sp-800-86', 'retrieved', '9B40A0CADE8B4815A02DEB413888A4CF8B30CEBC08C0AB067F1248815DC4F49B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p100-3', 'doc-04-nist-sp-800-86', '', 100, 'If evidence might be needed for legal or internal disciplinary actions, analysts should carefully document the findings and the steps that were taken.', 'kb-doc-04-nist-sp-800-86-p100-3', 0, 23, '04-nist-sp-800-86', 'retrieved', '51A8542B774C037F2ECCD988BC88F82064A15EC3EB380493E934413E299D975F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p100-10', 'doc-04-nist-sp-800-86', '', 100, 'Analysts should validate any unusual or unexpected data that is based on interpreting data, such as IDS and SEM alerts.', 'kb-doc-04-nist-sp-800-86-p100-10', 0, 20, '04-nist-sp-800-86', 'retrieved', '544C5DDDEBD2301A068B5168FC4E2D021C7E94DD697A2D8FC19F4A522FE1A632', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
