INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p100-13', 'doc-04-nist-sp-800-86', '', 100, 'Analysts can identify the type of data stored in many files by examining their file headers.', 'kb-doc-04-nist-sp-800-86-p100-13', 0, 16, '04-nist-sp-800-86', 'retrieved', '2DF5D76C9BD1ED44D92D5F153159D909F809CC18FD5CB84D1AFAEDE070BE09B0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
