INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p100-17', 'doc-04-nist-sp-800-86', '', 100, 'Establishing the identity and intent of an attacker may be important, especially if a criminal investigation will ensue, but it should be weighed against other important goals.', 'kb-doc-04-nist-sp-800-86-p100-17', 0, 27, '04-nist-sp-800-86', 'retrieved', '1943CB42D357C50BC8E8E9AE71EA387042C30564C04B8A8CA605074CCFC8283C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
