INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p100-22', 'doc-04-nist-sp-800-86', '', 100, 'The analyst should review the results of the examination and analysis of individual data sources, such as data files, OSs, and network traffic, and determine how the information fits together, to perform a detailed analysis of application-related events and event reconstruction.', 'kb-doc-04-nist-sp-800-86-p100-22', 0, 41, '04-nist-sp-800-86', 'retrieved', '544FFF9A2EDBAB1F4A4DC997FCA166FE416640D97AFB86AB2FCD3D28EBAC8C04', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p101-1', 'doc-04-nist-sp-800-86', '', 101, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE Appendix BScenarios Tabletop exercises that focus on how forensic tools and techniques can be used in various scenarios provide an inexpensive and effective way of building and maintaining skills and identifying problems with guidelines, procedures, and policies.', 'kb-doc-04-nist-sp-800-86-p101-1', 0, 45, '04-nist-sp-800-86', 'retrieved', '530B57F71BB5A55A8ED2CFB7B4FD37D6A19F5FB73C0C05257166C12FA7A6B61E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p101-2', 'doc-04-nist-sp-800-86', '', 101, 'The exercise participants review a brief scenario and are then asked several questions related to the scenario.', 'kb-doc-04-nist-sp-800-86-p101-2', 0, 17, '04-nist-sp-800-86', 'retrieved', '8854894FBD9A44AE8E8B9E88EE335F5333F7A74E8FB694C7E57CD407927CFAB6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p101-3', 'doc-04-nist-sp-800-86', '', 101, 'The participants discuss each question and formulate an answer based on what they would really do in the situation.', 'kb-doc-04-nist-sp-800-86-p101-3', 0, 19, '04-nist-sp-800-86', 'retrieved', '2B9C3850ABE1D0D399594FD7A30528BF2C3EBAE4F5ADBA695ECE07361B574B3D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p101-4', 'doc-04-nist-sp-800-86', '', 101, 'The response is then compared with the organizations policies, procedures, and guidelines to identify any discrepancies or deficiencies.', 'kb-doc-04-nist-sp-800-86-p101-4', 0, 18, '04-nist-sp-800-86', 'retrieved', '870E065CF20918B35ADF3B394FBEC22C3E37FE27BBBC309D6EA0F3A71312DD15', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p101-5', 'doc-04-nist-sp-800-86', '', 101, 'For example, the answer to one question might indicate that forensic actions would be delayed because a participant lacked a particular piece of software and a particular team within the organization did not provide off-hours support.', 'kb-doc-04-nist-sp-800-86-p101-5', 0, 36, '04-nist-sp-800-86', 'retrieved', '1B4838E225B03B8C9AAB79267AAD5F76BB9F4B75669A3E5580EB76563BF50D2B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p101-6', 'doc-04-nist-sp-800-86', '', 101, 'Section B.1 contains a list of general questions that could be applied to almost any scenario.', 'kb-doc-04-nist-sp-800-86-p101-6', 0, 16, '04-nist-sp-800-86', 'retrieved', 'B3434B9FF89106F1F534E959D7C06F520CB24781E0C0D1C89D348735D2220928', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p101-7', 'doc-04-nist-sp-800-86', '', 101, 'Section B.2 contains several sample scenarios, some of which are followed by additional scenario-specific questions.', 'kb-doc-04-nist-sp-800-86-p101-7', 0, 15, '04-nist-sp-800-86', 'retrieved', 'B2BA7AECE90E43A9BBBEA96D17BC10142C8D4D0F71AB52234F5F6168EB36A933', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p101-8', 'doc-04-nist-sp-800-86', '', 101, 'Organizations are encouraged to adapt these questions and scenarios for use in their own exercises.', 'kb-doc-04-nist-sp-800-86-p101-8', 0, 15, '04-nist-sp-800-86', 'retrieved', '69607042C6F218ACE2CE3BF47B8D25FBE5D871DEDB929407A1EC8A0BA58C35B3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p101-9', 'doc-04-nist-sp-800-86', '', 101, 'B.1 B.2 Scenario Questions 1. What are the potential sources of data? 2. Of the potential sources of data, which are the most likely to contain helpful information and why? 3. Which data source would be checked first and why? 4. Which forensic tools and techniques would most likely be used? Which other tools and techniques might also be used? 5. Which groups and individuals within the organization would probably be involved in the forensic activities? 6. What communications with external parties might occur, if any? 7. From a forensic standpoint, what would be done differently if the scenario had occurred on a different day or at a different time (regular hours versus off-hours)? 8. From a forensic standpoint, what would be done differently if the scenario had occurred at a different physical location (onsite versus offsite)? Scenarios Scenario 1: Possible DDoS Attack On a Saturday afternoon, external users start having problems accessing the organizations public Web sites.', 'kb-doc-04-nist-sp-800-86-p101-9', 0, 158, '04-nist-sp-800-86', 'retrieved', '1EA5BBE4C9C845486AF629CB757370F315CB4DAB7860B42D3990379B5048ED4F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p101-10', 'doc-04-nist-sp-800-86', '', 101, 'Over the next hour, the problem worsens to the point where nearly every attempt to access any of the organizations public Web sites fails.', 'kb-doc-04-nist-sp-800-86-p101-10', 0, 24, '04-nist-sp-800-86', 'retrieved', '21E4370A86CF923F2502CBF56D4F825D81FF00DB4F37BD3BE53E957FF9723E44', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p101-11', 'doc-04-nist-sp-800-86', '', 101, 'Meanwhile, a member of the organizations networking staff responds to automatically generated alerts from an Internet border router and determines that much of the organizations Internet bandwidth is being consumed by an unusually large volume of User Datagram Protocol (UDP) packets to and from both of the organizations public Domain Name System (DNS) servers.', 'kb-doc-04-nist-sp-800-86-p101-11', 0, 54, '04-nist-sp-800-86', 'retrieved', 'BDB440019771E68AAEF9593908C0652E7A32DCE086E409BBA3FEBEDF90D26C5E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p102-1', 'doc-04-nist-sp-800-86', '', 102, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE The following are additional questions for this scenario: 1. How would the forensic activity change if the DDoS attack appeared to be coming from a network in a different state? In a different country? 2. How would the forensic activity change if the DDoS attack appeared to be coming from a business partners network? Scenario 2: Online Payment Problems Over the course of a week, the number of phone calls coming into the organizations help line for online bill presentment and payment increases by 400 percent.', 'kb-doc-04-nist-sp-800-86-p102-1', 0, 94, '04-nist-sp-800-86', 'retrieved', '32A0FAABD8321A342110130268ABE6B33E3667A5187B06E29D0578B41DCD95E1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p102-2', 'doc-04-nist-sp-800-86', '', 102, 'Most callers complain of having to resubmit payment information multiple times, and many cannot complete their payment.', 'kb-doc-04-nist-sp-800-86-p102-2', 0, 17, '04-nist-sp-800-86', 'retrieved', 'E059929458121965D60650225C236705274050E5A73C8170284E8267E250DD41', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p102-3', 'doc-04-nist-sp-800-86', '', 102, 'The following are additional questions for this scenario: 1. The problems could have a non-technical cause, such as a lack of clear instructions for new users.', 'kb-doc-04-nist-sp-800-86-p102-3', 0, 26, '04-nist-sp-800-86', 'retrieved', 'A91D54FAAFBFDA59D4FD05565AD82BC2295E1DA4D0615DB52D884F84D8776983', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p102-4', 'doc-04-nist-sp-800-86', '', 102, 'How should the technical and non-technical aspects of the investigation be coordinated and balanced? 2. How might privacy considerations affect the use of forensic tools and techniques? 3. How would forensic tools and techniques be used if application developers were confident that an operational problem was causing the issues? Scenario 3: Unknown Wireless Access Point On a Monday morning, the organizations help desk receives calls from five users on the same floor of a building who state that they are having problems with their wireless access.', 'kb-doc-04-nist-sp-800-86-p102-4', 0, 86, '04-nist-sp-800-86', 'retrieved', 'F6EFFC07F5949487668211802D32A5E2EC0FAEE3AD3A86C30739046DFD84534C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p102-5', 'doc-04-nist-sp-800-86', '', 102, 'A network administrator who is asked to assist in resolving the problem brings a laptop with wireless capability to the users floor.', 'kb-doc-04-nist-sp-800-86-p102-5', 0, 22, '04-nist-sp-800-86', 'retrieved', 'C16815100B50DE10580CF9BC1B9ACEB962A0D27C751881434EFEC27DBDB2A2D2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
