INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p102-6', 'doc-04-nist-sp-800-86', '', 102, 'As he views his wireless networking configuration, he notices that there is a new wireless access point listed as available.', 'kb-doc-04-nist-sp-800-86-p102-6', 0, 20, '04-nist-sp-800-86', 'retrieved', 'D162CCEAEF1A93960AB116AFE83F197F861383AB1386BEA8FE61DA0EF71C6164', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
