INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p102-7', 'doc-04-nist-sp-800-86', '', 102, 'Based on the insecure configuration settings transmitted by the access point, the administrator does not believe that his team deployed it.', 'kb-doc-04-nist-sp-800-86-p102-7', 0, 21, '04-nist-sp-800-86', 'retrieved', '66FE3D40E60918323DF67B9EFE9B71BC487BBF892783A7560526000D3EDF1F7C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
