INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p102-8', 'doc-04-nist-sp-800-86', '', 102, 'The following are additional questions for this scenario: 1. What types of forensic tools might be used to locate the access point overtly? Covertly? 2. How would the forensic activities change if it was determined that the access point was deployed for a legitimate business purpose, such as temporary work at the office by a contractor? 3. How would the forensic activities change if it was determined that an unknown individual had been seen deploying the access point? Scenario 4: Reinfected Host During the past 2 weeks, a user has needed to have the same virus removed from a laptop computer twice, and the user is now reporting similar symptoms again.', 'kb-doc-04-nist-sp-800-86-p102-8', 0, 111, '04-nist-sp-800-86', 'retrieved', '95D7B908262C2717FCC60140822836EA03F59C7933FE0BB04D05A31EE183E435', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p102-9', 'doc-04-nist-sp-800-86', '', 102, 'The technical support staff who handled the previous infections confirmed that the antivirus software on the computer was enabled and up to date and were unable to determine how the virus was reinfecting the computer.', 'kb-doc-04-nist-sp-800-86-p102-9', 0, 35, '04-nist-sp-800-86', 'retrieved', '178AEC733989CC8B9EA7F718BD367FB4D7CB9E7AB1954846CE47B381BDC35655', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
