INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p103-1', 'doc-04-nist-sp-800-86', '', 103, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE 1. What other sources of data might be spotted by visually surveying the users office? 2. What are the most likely possible data sources outside of the users office? 3. What legal considerations should the analysts be aware of if they want to examine a data source that the organization does not own? Scenario 5: Mistaken Identity Within the past 24 hours, two employees in the organization have reported fraudulent purchases charged to their organization-issued credit cards.', 'kb-doc-04-nist-sp-800-86-p103-1', 0, 85, '04-nist-sp-800-86', 'retrieved', 'FEF88E2DCBFF73B4D80837ABA80DEB7890AFCF705E34C6D672115CCC08FBC8CA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p103-2', 'doc-04-nist-sp-800-86', '', 103, 'The organization frequently buys items from the companies that sold the items in the questioned transactions.', 'kb-doc-04-nist-sp-800-86-p103-2', 0, 16, '04-nist-sp-800-86', 'retrieved', '9AAB91B20B72B9BF8C4BA7E3F148B3CD9F48C50C9D7CEC4E4F2EC8A650250774', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
