INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p103-3', 'doc-04-nist-sp-800-86', '', 103, 'A follow-on assessment shows that charges to the organizations credit cards across the organization have increased by 30 percent in the past 3 days.', 'kb-doc-04-nist-sp-800-86-p103-3', 0, 24, '04-nist-sp-800-86', 'retrieved', '0E02FC54AF5E35648EE43E252A656391F105B00E8BF7A5109AB7C08A5179992E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
