INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p103-4', 'doc-04-nist-sp-800-86', '', 103, 'The following are additional questions for this scenario: 1. How could forensic tools and techniques help analysts determine what has happened (e.g., that individual employees in the organization are victims of identity theft, that financial resources have been corrupted)? 2. What privacy concerns should be considered in investigating employees financial transactions? Scenario 6: Unwanted Screen Saver The organizations help desk has just received several calls from users who complain that a screen saver depicting pastoral scenery is activating while they are working at their computers.', 'kb-doc-04-nist-sp-800-86-p103-4', 0, 85, '04-nist-sp-800-86', 'retrieved', '28F4221706B6B7C521B61D654EE45E61D49E2DB818DE07799F8727352D43E65B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p103-5', 'doc-04-nist-sp-800-86', '', 103, 'The screen saver requires each user to submit his or her password to unlock the screen saver and continue work.', 'kb-doc-04-nist-sp-800-86-p103-5', 0, 20, '04-nist-sp-800-86', 'retrieved', '944A7FA1A02D64F58BCDC570E5A111E79DED59B4ED3B6A0AF6A8CAFA2726CA7E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
