INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p103-6', 'doc-04-nist-sp-800-86', '', 103, 'At the same time, the organizations network intrusion detection systems report several unusual alerts involving a Web server.', 'kb-doc-04-nist-sp-800-86-p103-6', 0, 18, '04-nist-sp-800-86', 'retrieved', '21A7C52831B4D4D18A4F8EA8F3A9F420D8B8D00C6D08A4E412140C3740A3388A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
