INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p103-7', 'doc-04-nist-sp-800-86', '', 103, 'The data in the alerts indicates that some suspicious activity was directed at the server, and the server is now generating similar activity directed at other systems.', 'kb-doc-04-nist-sp-800-86-p103-7', 0, 27, '04-nist-sp-800-86', 'retrieved', '1F2FD4E5E1FE9CBA42DB80B0E8F1F7BAB11C64DB4E3F26CAEA4F4EE18A103A6E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
