INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p103-8', 'doc-04-nist-sp-800-86', '', 103, 'The intrusion detection analysts initial hypothesis is that a worm may have attacked a vulnerable network service on the Web server.', 'kb-doc-04-nist-sp-800-86-p103-8', 0, 21, '04-nist-sp-800-86', 'retrieved', 'CB6DF04A18B950BD031B5591EEFF4B2EE18915FEB1EC1D89C5BFC364D934E884', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
