INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p103-10', 'doc-04-nist-sp-800-86', '', 103, 'The e-mails cite a possible security breach in the financial institutions records and ask recipients to follow a link to the institutions Web site and create a new password, after identifying themselves by providing their existing passwords and account information.', 'kb-doc-04-nist-sp-800-86-p103-10', 0, 40, '04-nist-sp-800-86', 'retrieved', '79E7D98E1705BF3C580B9AE97E99FE7911013C3B65E88A77FAB7EA702EA6804A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
