VALUES ('doc-04-nist-sp-800-86-p104-2', 'doc-04-nist-sp-800-86', '', 104, 'The manager finds some filenames that appear to be related to the project, but the manager cannot access the contents of the files.', 'kb-doc-04-nist-sp-800-86-p104-2', 0, 23, '04-nist-sp-800-86', 'retrieved', 'B5A04DA293A194A4A903761C7FDE793875D322410466249F84929C306C566173', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
