VALUES ('doc-04-nist-sp-800-86-p104-3', 'doc-04-nist-sp-800-86', '', 104, 'A system administrator looks at the system and concludes that the former employee probably encrypted the files.', 'kb-doc-04-nist-sp-800-86-p104-3', 0, 17, '04-nist-sp-800-86', 'retrieved', 'D2092DBC51F847401782ABE535706BF5FA79D90F88C0B5F255702D479B44C15F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
