INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p3-2', 'doc-05-nist-sp-800-61r3', '', 3, 'Certain equipment, instruments, software, or materials, commercial or non-commercial, are identified in this paper in order to specify the experimental procedure adequately. Such identification does not imply recommendation or endorsement of any product or service by NIST, nor does it imply that t he materials or equipment identified are necessarily the best available for the purpose .', 'kb-doc-05-nist-sp-800-61r3-p3-2', 0, 57, '05-nist-sp-800-61r3', 'retrieved', '7F57FB76D87CE053034881336EDAAFE4A5D063D5264A6934043AEDFD637C03A8', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
