VALUES ('doc-05-nist-sp-800-61r3-p5-3', 'doc-05-nist-sp-800-61r3', '', 5, 'Keywords cyber threat information sharing; Cybersecurity Framework; cybersecurity incident; cybersecurity risk management; incident handling; incident management; incident response.', 'kb-doc-05-nist-sp-800-61r3-p5-3', 0, 18, '05-nist-sp-800-61r3', 'retrieved', '4D9C70B82E9517E64B2CD475ACCD5FBBB7B5740E1E4CD27171428D346094DF30', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
