VALUES ('doc-05-nist-sp-800-61r3-p6-4', 'doc-05-nist-sp-800-61r3', '', 6, 'Audience The target audience for this publication includes cybersecurity program leadership, cybersecurity personnel, and others who are responsible for preparing for, detecting, responding to, or recovering from cybersecurity incidents. This publication is intended for use by most organizations, regardless of sector, size, or other factors.', 'kb-doc-05-nist-sp-800-61r3-p6-4', 0, 45, '05-nist-sp-800-61r3', 'retrieved', 'DB227EB8B2578BDBAF465F6A199BF95E278AA1C5F3DA01178A9D2315A2DA0AA3', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
