VALUES ('doc-05-nist-sp-800-61r3-p9-7', 'doc-05-nist-sp-800-61r3', '', 9, 'This also enables organizations to access a range of online resources mapped to each Function, Category, and Subcategory through the NIST Cybersecurity and Privacy Reference Tool (CPRT) .', 'kb-doc-05-nist-sp-800-61r3-p9-7', 0, 28, '05-nist-sp-800-61r3', 'retrieved', '545486AD7C45493FBCAE4FABEF8C04FEA2D773C85AA17BF7840B613DF5D8C47D', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
