INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p9-8', 'doc-05-nist-sp-800-61r3', '', 9, 'These resources include mappings to other incident response and cybersecurity risk management standards and guidance, as well as sources of implementation guidance that organizations can choose to utilize as needed.', 'kb-doc-05-nist-sp-800-61r3-p9-8', 0, 30, '05-nist-sp-800-61r3', 'retrieved', '9895F9A4E2C9AF7CA771AE9F54A31F200A9258DF27ACF22F4BB6B52F529D3910', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
