INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p11-7', 'doc-05-nist-sp-800-61r3', '', 11, '1.2. Document Structure The remainder of this document is organized into the following sections and appendices: • Section 2 discusses how incident response has evolved to become a critical part of cybersecurity risk management, as well as how the concept of the incident response life cycle has changed to reflect that.', 'kb-doc-05-nist-sp-800-61r3-p11-7', 0, 51, '05-nist-sp-800-61r3', 'retrieved', 'E622D8515B212459CD6C25A26AE89B27715439F3D41B892366CF30FAE3382D6B', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
