INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p11-8', 'doc-05-nist-sp-800-61r3', '', 11, '• Section 3 presents incident response recommendations and considerations for an organization’s cybersecurity risk management practices. They are organized and documented as a CSF 2.0 Community Profile.', 'kb-doc-05-nist-sp-800-61r3-p11-8', 0, 27, '05-nist-sp-800-61r3', 'retrieved', '149EABB5946CA7E4BC06E391E51045A37E3BCC9407D93A3BBE5F76A44F3F5C6A', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
