VALUES ('doc-05-nist-sp-800-61r3-p11-10', 'doc-05-nist-sp-800-61r3', '', 11, '• Appendix A and Appendix B provide an acronyms list and a glossary, respectively.', 'kb-doc-05-nist-sp-800-61r3-p11-10', 0, 14, '05-nist-sp-800-61r3', 'retrieved', '483E6FDA8B42ABD820BA84B9DCA9C97FE8EE9272810C96301AD550AB6586A007', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
