INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p11-11', 'doc-05-nist-sp-800-61r3', '', 11, '• Appendix C contains a change log of the major changes made since the previous revision.', 'kb-doc-05-nist-sp-800-61r3-p11-11', 0, 16, '05-nist-sp-800-61r3', 'retrieved', '08BC0A70F352284CF885FC51CDB86E7DF15420BEAEBE6F4B197E68BF07DC622B', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
