INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p13-5', 'doc-05-nist-sp-800-61r3', '', 13, '• Detect (DE): Possible cybersecurity attacks and compromises are found and analyzed.', 'kb-doc-05-nist-sp-800-61r3-p13-5', 0, 12, '05-nist-sp-800-61r3', 'retrieved', '7316234844FD7A3F816D5984B85DA1908B01C225481A963A462CD1AF2CEEA2FD', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
