INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p18-8', 'doc-05-nist-sp-800-61r3', '', 18, 'The recommendations, considerations, and notes supplement what the CSF 2.0 already provides through its documents and online resources. The recommendations, considerations, and notes are not comprehensive, and not all of them will be applicable to every organization.', 'kb-doc-05-nist-sp-800-61r3-p18-8', 0, 37, '05-nist-sp-800-61r3', 'retrieved', '462793EB9E02961C07E897009BA32123520FCBCC1D38F15039B52B2E86BD2B75', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
