INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p18-9', 'doc-05-nist-sp-800-61r3', '', 18, 'Technologies mentioned in recommendations, considerations, and notes are examples as of this writing and may become outdated.', 'kb-doc-05-nist-sp-800-61r3-p18-9', 0, 17, '05-nist-sp-800-61r3', 'retrieved', 'D3CBEFC2520B5C9E0CFE602FEC6D490E90DB9FF691C2F99646AA3536CBB23A3F', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
