INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p19-2', 'doc-05-nist-sp-800-61r3', '', 19, '11 Some recommendations, considerations, and notes use terms that are not defined in this publication (e.g., “data breach”). Organizations that adopt the Community Profile should define these terms in the context of their own environments, use cases, and applicable laws and regulations. Readers may also choose to consult NIST’s glossary, which contains an aggregation of terms and definitions from numerous NIST standards, guidelines, and other publications.', 'kb-doc-05-nist-sp-800-61r3-p19-2', 0, 66, '05-nist-sp-800-61r3', 'retrieved', '47D4CDB916A425B9990AAF52CB2FCB2C3AF1F79CB762C142DA7B97E041224D49', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p19-3', 'doc-05-nist-sp-800-61r3', '', 19, 'The Community Profile is intended for use by most organizations, re gardless of sector, size, or other factors. Additional versions of this Community Profile could be developed for narrower audiences, such as federal agencies, small businesses, or educational institutions. For more information on CSF 2.0 Community Profiles, see the Framework Resource Center.', 'kb-doc-05-nist-sp-800-61r3-p19-3', 0, 52, '05-nist-sp-800-61r3', 'retrieved', 'CA42D06F6C58C750B85351332AD7DC8D1A6B03194BF934FA069AA22A6428A2E4', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p19-4', 'doc-05-nist-sp-800-61r3', '', 19, '3.1. Preparation and Lessons Learned Table 2 contains the first part of the Community Profile: Preparation and Lessons Learned, which both support the Incident Response part of the Community Profile defined in Table 3.', 'kb-doc-05-nist-sp-800-61r3-p19-4', 0, 34, '05-nist-sp-800-61r3', 'retrieved', '58DDCE3E84E740CCEA0101DBE902F8838DAEB8CA7AB0EADBDAED7B7AA51498E1', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p19-5', 'doc-05-nist-sp-800-61r3', '', 19, 'Note: Most of the CSF elements in this part of the Profile are not specific to executing incident response activities, so they have lower priorities with respect to incident response and do not contain recommendations or considerations. This does not imply that they are unnecessary for organizations to achieve, but rather that they are outside of the direct scope of responding to incidents.', 'kb-doc-05-nist-sp-800-61r3-p19-5', 0, 63, '05-nist-sp-800-61r3', 'retrieved', 'B1F6D4D4678218CCFE44352A224A9E27CCE351F4374B4FA5A57C924183193E5F', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p19-6', 'doc-05-nist-sp-800-61r3', '', 19, 'Table 2. CSF 2.0 Community Profile part 1: Preparation and Lessons Learned CSF Element CSF Element Description Priority Recommendations, Considerations, Notes GV (Govern) The organization’s cybersecurity risk management strategy, expectations, and policy are established, communicated, and monitored Low GV.OC (Organizational Context) The circumstances — mission, stakeholder expectations, dependencies, and legal, regulatory, and contractual requirements — surrounding the organization’s cybersecurity risk management decisions are understood Low GV.OC-01 The organizational mission is understood and informs cybersecurity risk management Low GV.OC-02 Internal and external stakeholders are understood, and their needs and expectations regarding cybersecurity risk management are understood and considered Low GV.OC-03 Legal, regulatory, and contractual requirements Medium R1: Cybersecurity requirements should include all requirements related to incident', 'kb-doc-05-nist-sp-800-61r3-p19-6', 0, 115, '05-nist-sp-800-61r3', 'retrieved', 'D7409A740CD48D8BBAAA272ECDAE996586D167005888F62D653700CACD506EF5', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p20-2', 'doc-05-nist-sp-800-61r3', '', 20, '12 CSF Element CSF Element Description Priority Recommendations, Considerations, Notes regarding cybersecurity — including privacy and civil liberties obligations — are understood and managed notifications, data breach reporting, and other aspects of incident response.', 'kb-doc-05-nist-sp-800-61r3-p20-2', 0, 34, '05-nist-sp-800-61r3', 'retrieved', '0A5147946F48A0DAF41F67D5BCD0B7096CA21958F9E231E4D26557592C79F42C', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
