INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p20-3', 'doc-05-nist-sp-800-61r3', '', 20, 'GV.OC-04 Critical objectives, capabilities, and services that external stakeholders depend on or expect from the organization are understood and communicated Medium N1: Understanding critical external dependencies on the organization’s operations can aid in prioritizing response and recovery efforts.', 'kb-doc-05-nist-sp-800-61r3-p20-3', 0, 38, '05-nist-sp-800-61r3', 'retrieved', '84D0062705F755B673ACD13AFE67FD9314CC84C1231D7886606CB75D4A885193', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
