INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p20-4', 'doc-05-nist-sp-800-61r3', '', 20, 'GV.OC-05 Outcomes, capabilities, and services that the organization depends on are understood and communicated Medium N1: Understanding critical dependencies on external resources (e.g., cloud-based hosting providers and managed service providers) can aid in prioritizing response and recovery efforts.', 'kb-doc-05-nist-sp-800-61r3-p20-4', 0, 38, '05-nist-sp-800-61r3', 'retrieved', 'A1A18F1AEA0301AE74C58DD573D24564351B4474C9C8A8BAA73E6AD355C9B00D', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
