INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p20-5', 'doc-05-nist-sp-800-61r3', '', 20, 'GV.RM (Risk Management Strategy) The organization’s priorities, constraints, risk tolerance and appetite statements, and assumptions are established, communicated, and used to support operational risk decisions Low GV.RM-01 Risk management objectives are established and agreed to by organizational stakeholders Low GV.RM-02 Risk appetite and risk tolerance statements are established, communicated, and maintained Low GV.RM-03 Cybersecurity risk management activities and outcomes are included in enterprise risk management processes Medium R1: Have processes in place so that incident-related decision-making will be informed by other types of risks that the organization faces (e.g., privacy, operational, safety, reputational, AI) and not just cybersecurity risks in isolation.', 'kb-doc-05-nist-sp-800-61r3-p20-5', 0, 101, '05-nist-sp-800-61r3', 'retrieved', 'E44D221229A3F0B51285526C06837D98725F21989CDBFF1B3957AB2837C6115D', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p20-6', 'doc-05-nist-sp-800-61r3', '', 20, 'GV.RM-04 Strategic direction that describes appropriate risk response options is established and communicated Low GV.RM-05 Lines of communication across the organization are established for cybersecurity risks, including risks from suppliers and other third parties Low GV.RM-06 A standardized method for calculating, documenting, categorizing, and prioritizing cybersecurity risks is established and communicated Medium N1: Having a standardized method for calculating cybersecurity risks can aid in prioritizing response and recovery efforts and in comparing the estimated and actual impacts of incidents.', 'kb-doc-05-nist-sp-800-61r3-p20-6', 0, 79, '05-nist-sp-800-61r3', 'retrieved', 'A03B4D0079F690C52C3C4CD569B89DC0A5A83766161244F9EE4F646BFB84E7DE', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
