INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p24-7', 'doc-05-nist-sp-800-61r3', '', 24, 'ID.AM-05 Assets are prioritized based on classification, criticality, resources, and impact on the mission Medium R1: Prioritizing the organization’s assets — including hardware, software, services, systems, and data — and being aware of the dependencies between those and other assets should help indicate where the organization should focus its resources in terms of protection, detection, response, and recovery.', 'kb-doc-05-nist-sp-800-61r3-p24-7', 0, 58, '05-nist-sp-800-61r3', 'retrieved', '3E3895809BCBF1F2A8D350A4A3AC59E5D0E01575D6BDD17AFC189BA609E3AF42', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
