INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p24-8', 'doc-05-nist-sp-800-61r3', '', 24, 'ID.AM-07 Inventories of data and corresponding metadata for designated data types are maintained Medium R1: Having data inventories that include data classifications, owners, and logical and physical locations should provide valuable information on what data may have been involved in an incident.', 'kb-doc-05-nist-sp-800-61r3-p24-8', 0, 42, '05-nist-sp-800-61r3', 'retrieved', 'F07D784E561DAB038F73436F2D4FE59E153CB2C99322991D8D13F9B26F3D8EB8', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
