INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p24-9', 'doc-05-nist-sp-800-61r3', '', 24, 'ID.AM-08 Systems, hardware, software, services, and data are managed throughout their life cycles Medium R1: Managing hardware, software, services, and systems throughout their life cycles should take cybersecurity into consideration, such as configuring them securely, reducing attack surfaces, and updating inventory information as assets are transferred or relocated.', 'kb-doc-05-nist-sp-800-61r3-p24-9', 0, 48, '05-nist-sp-800-61r3', 'retrieved', 'C3A7183F4C4DFBE1A37ACA572B8349E0E70056E63004712EBACB06E8E93DBAEE', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
