INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p24-10', 'doc-05-nist-sp-800-61r3', '', 24, 'ID.RA (Risk Assessment) The cybersecurity risk to the organization, assets, and individuals is understood by the organization Medium N1: Risk assessment practices are critical for reducing the number of incidents that occur and the impacts they cause. Risk assessment is a vast topic that is outside of', 'kb-doc-05-nist-sp-800-61r3-p24-10', 0, 47, '05-nist-sp-800-61r3', 'retrieved', '02AD6F2FD996AB3CFCDCB0E9D4AC4D261A1CC677801992E9DF5E6058E5AF5D78', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
