VALUES ('doc-05-nist-sp-800-61r3-p25-2', 'doc-05-nist-sp-800-61r3', '', 25, '17 CSF Element CSF Element Description Priority Recommendations, Considerations, Notes the scope of this Profile other than to summarize its importance for incident response.', 'kb-doc-05-nist-sp-800-61r3-p25-2', 0, 24, '05-nist-sp-800-61r3', 'retrieved', 'E2575A95E3F7762E02B347FEF8D90D3DA42FC965F1090BB0DBE0BB4781D7D42F', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
