INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p25-5', 'doc-05-nist-sp-800-61r3', '', 25, 'ID.RA-01 Vulnerabilities in assets are identified, validated, and recorded Medium R1: Understand current known cybersecurity vulnerabilities to make informed decisions when assessing risks.', 'kb-doc-05-nist-sp-800-61r3-p25-5', 0, 23, '05-nist-sp-800-61r3', 'retrieved', '139DC2D4E2E1F2F329CA3B1C1AF5A2AE39FDE7D4DD1C2A8B9E5A50BDFFDEA858', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p25-6', 'doc-05-nist-sp-800-61r3', '', 25, 'This should include all types of known cybersecurity vulnerabilities, such as flaws in software (including firmware and software-based services) developed by the organization and third parties, software misconfigurations, network and system design and implementation weaknesses, physical vulnerabilities and resilience issues in facilities that house computing assets, and integrity violations in hardware and software (e.g., counterfeit, evidence of tampering).', 'kb-doc-05-nist-sp-800-61r3-p25-6', 0, 58, '05-nist-sp-800-61r3', 'retrieved', '2FA84087412E911BD7137A36D99FE5231C8A354E80FD706D9491ACB0C5213EF9', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
