INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p25-8', 'doc-05-nist-sp-800-61r3', '', 25, 'ID.RA-02 Cyber threat intelligence is received from information sharing forums and sources High N1: Cyber threat intelligence (CTI) is threat information that has been aggregated, transformed, analyzed, interpreted, or enriched to provide the necessary context for decision-making processes.', 'kb-doc-05-nist-sp-800-61r3-p25-8', 0, 38, '05-nist-sp-800-61r3', 'retrieved', '99A86F3C254FE4399C64319CF05CFDFE37BAF56F3EB8996029C15A9FA8CA8254', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p25-9', 'doc-05-nist-sp-800-61r3', '', 25, 'Organizations can receive CTI from automated CTI feeds, information sharing forums, and other sources.', 'kb-doc-05-nist-sp-800-61r3-p25-9', 0, 14, '05-nist-sp-800-61r3', 'retrieved', '3A12569262B9EAA1D119B01BF56ED75E2D40D96CB9BF86F8E3522E6C771BF562', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p25-10', 'doc-05-nist-sp-800-61r3', '', 25, 'N2: CTI is useful for incident response and recovery in several ways, including obtaining information on new threats, improving the accuracy of cybersecurity technologies with incident detection or response capabilities, and understanding the tactics, techniques, and procedures (TTPs) used by attackers. TTPs describe the behavior of an actor. Information on threats and their TTPs is widely available through repositories and knowledge bases.', 'kb-doc-05-nist-sp-800-61r3-p25-10', 0, 62, '05-nist-sp-800-61r3', 'retrieved', 'D50D5A122B6604BD5BB6DA8D6D34E998B4553CB99DA91FAD1FD4CA0A88BF08A0', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p25-11', 'doc-05-nist-sp-800-61r3', '', 25, 'N3: [SP800-150] provides guidelines on consuming, using, and storing CTIs, as well as establishing CTI relationships.', 'kb-doc-05-nist-sp-800-61r3-p25-11', 0, 16, '05-nist-sp-800-61r3', 'retrieved', 'CF77EB276E4938C53B7979F8ADE608642BB0ECB6256AF3A8AAD78F5B9612545A', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
