INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p25-13', 'doc-05-nist-sp-800-61r3', '', 25, 'ID.RA-03 Internal and external threats to the organization are identified and recorded Medium R1: Identify internal and external threats during routine operations and from CTI.', 'kb-doc-05-nist-sp-800-61r3-p25-13', 0, 25, '05-nist-sp-800-61r3', 'retrieved', '1BCC5AF5EE7C94D87E1610C7C67C9AC954FD1D3B894998203EED59E5550F4F87', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
