VALUES ('doc-05-nist-sp-800-61r3-p26-2', 'doc-05-nist-sp-800-61r3', '', 26, '18 CSF Element CSF Element Description Priority Recommendations, Considerations, Notes threats include threat hunting and the use of deception technologies.', 'kb-doc-05-nist-sp-800-61r3-p26-2', 0, 20, '05-nist-sp-800-61r3', 'retrieved', '69234532712973AE7F7CA2B20E01D0A0B1621B7B8DE16BC8F6FD1DA487C7C397', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
