INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p26-6', 'doc-05-nist-sp-800-61r3', '', 26, 'ID.RA-05 Threats, vulnerabilities, likelihoods, and impacts are used to understand inherent risk and inform risk response prioritization High R1: Organizations with mechanisms in place for estimating cybersecurity risk as part of their cybersecurity risk management programs should use those mechanisms for incident response purposes.', 'kb-doc-05-nist-sp-800-61r3-p26-6', 0, 44, '05-nist-sp-800-61r3', 'retrieved', 'D54CE070FCBE22785B63E59C0E9FF0C1F7F67B9DF40F89D75B96371A21E45776', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
