INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p26-7', 'doc-05-nist-sp-800-61r3', '', 26, 'C1: Consider using threat modeling and other methods to inform the understanding of attack vectors, attack surfaces, and lateral paths through organizational assets, among other factors that contribute to risk.', 'kb-doc-05-nist-sp-800-61r3-p26-7', 0, 30, '05-nist-sp-800-61r3', 'retrieved', '38D53F5389F206AA01E16103F0DDE07DFC7816DE29AAD2118BF0EF7F42BDBD5F', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
