INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p26-9', 'doc-05-nist-sp-800-61r3', '', 26, 'ID.RA-06 Risk responses are chosen, prioritized, planned, tracked, and communicated High N1: Risk responses are needed to prevent future incidents from occurring and existing incidents from reoccurring.', 'kb-doc-05-nist-sp-800-61r3-p26-9', 0, 27, '05-nist-sp-800-61r3', 'retrieved', 'B59F9E783DDBAE134FC7D86BDBA4BF089801A679B1877EE1443101A0515375D0', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
