VALUES ('doc-05-nist-sp-800-61r3-p26-14', 'doc-05-nist-sp-800-61r3', '', 26, 'ID.RA-07 Changes and exceptions are managed, assessed for risk impact, recorded, and tracked Medium N1: See the notes for ID.RA.', 'kb-doc-05-nist-sp-800-61r3-p26-14', 0, 20, '05-nist-sp-800-61r3', 'retrieved', '6BC74D736C3D7AAD94950CF21A882512803463C14F062312CFE2D3D53457DE22', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
