VALUES ('doc-05-nist-sp-800-61r3-p27-8', 'doc-05-nist-sp-800-61r3', '', 27, 'N1: Possible evaluation forms include self- assessments, third-party assessments, and independent audits.', 'kb-doc-05-nist-sp-800-61r3-p27-8', 0, 12, '05-nist-sp-800-61r3', 'retrieved', 'CA0CF5CBFD9B88E640A906920B20ADB51482BAD8B6AA1BB71961B7A719B74982', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
