INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p27-13', 'doc-05-nist-sp-800-61r3', '', 27, 'N3: Improvements are often identified when creating follow-up reports for incidents or holding “lessons learned” meetings when an incident’s recovery efforts are concluding, especially if the incident was major. This provides an opportunity to review what happened, what actions were taken, and how effective those actions were, as well as hear from all', 'kb-doc-05-nist-sp-800-61r3-p27-13', 0, 53, '05-nist-sp-800-61r3', 'retrieved', 'E343F4C34ACB096F1186D64D2190EFC54535548C3D348326CAF65244C3424F96', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
