INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p28-3', 'doc-05-nist-sp-800-61r3', '', 28, 'ID.IM-04 Incident response plans and other cybersecurity plans that affect operations are established, communicated, maintained, and improved High N1: Several types of cybersecurity plans are relevant to incident response, including 1) incident response plans, which provide the roadmap for implementing the incident response capability; 2) vulnerability management plans, which help identify and assess all types of vulnerabilities and prioritize, test, and implement risk responses; and 3) business continuity plans.', 'kb-doc-05-nist-sp-800-61r3-p28-3', 0, 69, '05-nist-sp-800-61r3', 'retrieved', '9C9183264ABF60F51FAF0AE57350528195AE8C3D2CEE8F087E63158C7EA05DA7', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
