VALUES ('doc-05-nist-sp-800-61r3-p28-5', 'doc-05-nist-sp-800-61r3', '', 28, 'R2: Review and update all cybersecurity plans periodically or when a need for significant improvements is identified.', 'kb-doc-05-nist-sp-800-61r3-p28-5', 0, 17, '05-nist-sp-800-61r3', 'retrieved', '296E90A74238DF1F598D5D477C3A80214D1E7C5DF86112D608B939CB1B4AB7A0', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
