VALUES ('doc-05-nist-sp-800-61r3-p28-7', 'doc-05-nist-sp-800-61r3', '', 28, 'R4: Each cybersecurity plan should identify the resources and management support needed to carry it out successfully.', 'kb-doc-05-nist-sp-800-61r3-p28-7', 0, 17, '05-nist-sp-800-61r3', 'retrieved', 'AD3611773E8FAB6727EAC5AF405AAACB317061420A3AD608F42D031E9F7AF2E1', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
