INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p28-8', 'doc-05-nist-sp-800-61r3', '', 28, 'N2: Business continuity planning professionals who are made aware of cybersecurity incidents and their impacts can fine-tune business impact assessments, risk assessments, and continuity of operations plans. Further, because business continuity planners have extensive expertise in minimizing operational disruption during severe circumstances, they may be valuable in planning responses to specific incident types, such as denial-of- service (DoS) conditions.', 'kb-doc-05-nist-sp-800-61r3-p28-8', 0, 59, '05-nist-sp-800-61r3', 'retrieved', '8A391957D065C3F46D56656940C084F0DF39ADCA8C2856094D991085A5FD07B0', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p28-9', 'doc-05-nist-sp-800-61r3', '', 28, 'PR (Protect) Safeguards to manage the organization’s cybersecurity risks are used Medium N1: Lowering the number of incidents shortens operational disruptions, allows response teams to focus on high-impact situations, and reduces the impact of incidents that do occur (e.g., by making it harder for attackers to move laterally throughout an environment and, thus, slowing them down).', 'kb-doc-05-nist-sp-800-61r3-p28-9', 0, 56, '05-nist-sp-800-61r3', 'retrieved', 'FFD71DCBE3917C5EA294FF16C741CDEE7FA4AF34FE64B33D66EA506FF15A390F', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
