VALUES ('doc-05-nist-sp-800-61r3-p28-10', 'doc-05-nist-sp-800-61r3', '', 28, 'N2: Understanding the protection mechanisms in place can help personnel deploy methods to detect protection failures and bypasses.', 'kb-doc-05-nist-sp-800-61r3-p28-10', 0, 18, '05-nist-sp-800-61r3', 'retrieved', 'A26AAAB3BD29F1752DDA6C6CCE57E612871E941B4E864164B6B4EE7495335AFD', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
