VALUES ('doc-05-nist-sp-800-61r3-p31-7', 'doc-05-nist-sp-800-61r3', '', 31, '3.2. Incident Response Table 3 contains the second part of the Community Profile: Incident Response.', 'kb-doc-05-nist-sp-800-61r3-p31-7', 0, 15, '05-nist-sp-800-61r3', 'retrieved', '0BF1A16AB7A30E80318492107E42924ABED5C9612AEF6D91F52D05DAEBE35D17', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
