INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p31-8', 'doc-05-nist-sp-800-61r3', '', 31, 'Note: All of the CSF elements in this part of the Profile are specific to responding to incidents, so they have higher priorities with respect to incident response than those in the first part. Accordingly, all CSF elements in this part have recommendations or considerations.', 'kb-doc-05-nist-sp-800-61r3-p31-8', 0, 45, '05-nist-sp-800-61r3', 'retrieved', '2833529422543C53DCAA6A1F3DE2BB3BACA941204DD8D037A66949BC17D0390D', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
