INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p31-9', 'doc-05-nist-sp-800-61r3', '', 31, 'Table 3. CSF 2.0 Community Profile part 2: Incident Response CSF Element CSF Element Description Priority Recommendations, Considerations, Notes DE (Detect) Possible cybersecurity attacks and compromises are found and analyzed High N1: The Detect Function encompasses all of the monitoring and analysis activities performed to find and characterize potentially adverse events and, in turn, find cybersecurity incidents.', 'kb-doc-05-nist-sp-800-61r3-p31-9', 0, 57, '05-nist-sp-800-61r3', 'retrieved', '4E51C9506E0947E6A29C368E83C2A972450A008038FF070FC33011606A91877C', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p31-10', 'doc-05-nist-sp-800-61r3', '', 31, 'DE.CM (Continuous Monitoring) Assets are monitored to find anomalies, indicators of compromise, and other potentially adverse events High R1: Continuous monitoring for unauthorized activity, deviations from expected activity, and changes in security posture should involve the following types of assets at all times: networks and network services; computing hardware and software, runtime environments, and their data; the physical environment; personnel activity and technology usage; and external service provider activities.', 'kb-doc-05-nist-sp-800-61r3-p31-10', 0, 69, '05-nist-sp-800-61r3', 'retrieved', 'E1FA9457FCA082959B8A14C985EE5BF66CFCFE9E80DCFFB302C643CBDBDF96F0', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p31-11', 'doc-05-nist-sp-800-61r3', '', 31, 'C1: Consider using cyber threat information with continuous monitoring to help identify potentially malicious activities that may have otherwise been considered benign.', 'kb-doc-05-nist-sp-800-61r3-p31-11', 0, 22, '05-nist-sp-800-61r3', 'retrieved', '59FFD620EBEE7B6939C8C8A6AE0E95990630F81D9A9EDC9DBA8B8FCEFD6C2F65', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
