INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p32-2', 'doc-05-nist-sp-800-61r3', '', 32, '24 CSF Element CSF Element Description Priority Recommendations, Considerations, Notes R2: Tune the continuous monitoring technologies to reduce false positives and false negatives to acceptable levels.', 'kb-doc-05-nist-sp-800-61r3-p32-2', 0, 26, '05-nist-sp-800-61r3', 'retrieved', '74D1550E331E89335ED193CE807A1A63843A386845555DEE7B3FA752D457F446', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
