INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p32-3', 'doc-05-nist-sp-800-61r3', '', 32, 'DE.CM-01 Networks and network services are monitored to find potentially adverse events High R1: Monitoring should include wired and wireless networks, network communications and flows, network services (e.g., DNS and BGP), and the presence of unauthorized or rogue networks within facilities.', 'kb-doc-05-nist-sp-800-61r3-p32-3', 0, 41, '05-nist-sp-800-61r3', 'retrieved', 'EC1BA77179CD7AB8DCF836B77C4B48517E669200452BC8558C704DDB4A2D1A2B', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p32-4', 'doc-05-nist-sp-800-61r3', '', 32, 'DE.CM-02 The physical environment is monitored to find potentially adverse events High R1: Monitoring the physical environment should include all successful and failed access attempts into all controlled areas, the movement of people and equipment into and out of secure areas of facilities, and signs of tampering with physical access controls.', 'kb-doc-05-nist-sp-800-61r3-p32-4', 0, 51, '05-nist-sp-800-61r3', 'retrieved', '678EB2E89C7841C48870C8A9F28AD97849E1F17483F7471CAF05AA1D74C4C282', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
