INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p32-5', 'doc-05-nist-sp-800-61r3', '', 32, 'DE.CM-03 Personnel activity and technology usage are monitored to find potentially adverse events High R1: Monitoring personnel activity and technology usage should include anomalous user activity or unusual patterns of activity, authentication and logical access attempts, and the use of deception technology.', 'kb-doc-05-nist-sp-800-61r3-p32-5', 0, 42, '05-nist-sp-800-61r3', 'retrieved', 'AD68154C63F8326921097EBC19B747225A68F63BDC53ABEC838DE43061565CED', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
