INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p32-6', 'doc-05-nist-sp-800-61r3', '', 32, 'DE.CM-06 External service provider activities and services are monitored to find potentially adverse events High R1: Monitoring external service provider activities and services should include remote and on-site administration and maintenance activities that providers perform on organizational systems and deviations from expected behavior by cloud-based services, internet service providers, and other service providers.', 'kb-doc-05-nist-sp-800-61r3-p32-6', 0, 53, '05-nist-sp-800-61r3', 'retrieved', 'BEAF9FB41C42ACBA13B17D65BC7AAC5840DA5BE466DE023E3F4C4076B90B5396', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
