INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p32-7', 'doc-05-nist-sp-800-61r3', '', 32, 'DE.CM-09 Computing hardware and software, runtime environments, and their data are monitored to find potentially adverse events High R1: Monitor email, web, file sharing, collaboration services, and other common attack vectors to detect malware, phishing, data leaks, exfiltration, and other adverse events.', 'kb-doc-05-nist-sp-800-61r3-p32-7', 0, 42, '05-nist-sp-800-61r3', 'retrieved', '990AB94415AD10A56469A812B7A64E606A0BAE8A85205A04A37298408C62C5ED', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
