VALUES ('doc-05-nist-sp-800-61r3-p32-8', 'doc-05-nist-sp-800-61r3', '', 32, 'R2: Monitor authentication attempts to identify attacks against credentials and unauthorized credential use.', 'kb-doc-05-nist-sp-800-61r3-p32-8', 0, 13, '05-nist-sp-800-61r3', 'retrieved', '99AE3E00001F249C6D6D8ACEF36BA48CDC2A739667C34FFB423A085B57FA2766', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
