VALUES ('doc-05-nist-sp-800-61r3-p32-9', 'doc-05-nist-sp-800-61r3', '', 32, 'R3: Monitor software and hardware configurations for deviations from security baselines.', 'kb-doc-05-nist-sp-800-61r3-p32-9', 0, 11, '05-nist-sp-800-61r3', 'retrieved', 'AA15C46483BCCF6B38E9BF72940498263E01FF795D1B19EA70BAC56C2D66525A', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
