VALUES ('doc-05-nist-sp-800-61r3-p32-10', 'doc-05-nist-sp-800-61r3', '', 32, 'R4: Monitor hardware and software, including cybersecurity protection mechanisms, for signs of tampering, failure, or compromise.', 'kb-doc-05-nist-sp-800-61r3-p32-10', 0, 16, '05-nist-sp-800-61r3', 'retrieved', '4B084B6E728D5B513C64154E6C2FA5B1F6AE8B3E4A6A3F067B39FB12CAE1B3C7', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
