INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p32-11', 'doc-05-nist-sp-800-61r3', '', 32, 'R5: Monitor endpoints for cyber health issues (e.g., missing patches, malware infections, or unauthorized software), and redirect endpoints with issues to a remediation environment before access is authorized.', 'kb-doc-05-nist-sp-800-61r3-p32-11', 0, 28, '05-nist-sp-800-61r3', 'retrieved', '70599EEF7DBB221BB5DABAD8CC3F4A516A770080A061B43C6EACCD47EA6D84CF', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
