INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p35-12', 'doc-05-nist-sp-800-61r3', '', 35, 'RS.MA-03 Incidents are categorized and prioritized High R1: Perform a more detailed review of incidents to help categorize them by incident type (e.g., data breach, ransomware, account takeover, denial of service).', 'kb-doc-05-nist-sp-800-61r3-p35-12', 0, 31, '05-nist-sp-800-61r3', 'retrieved', 'D514514057C7B209CDB15F31D5BEFB869A8815C29008F6D589AC2082BE0F8471', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p36-2', 'doc-05-nist-sp-800-61r3', '', 36, '28 CSF Element CSF Element Description Priority Recommendations, Considerations, Notes R2: Prioritize how quickly incident response should be performed for each incident based on its scope, likely impact, time- critical nature, and resource availability.', 'kb-doc-05-nist-sp-800-61r3-p36-2', 0, 34, '05-nist-sp-800-61r3', 'retrieved', 'FDD189542FD340FE799285B7C2EDE7FA47B6B80A5B2FBF82281024D306EC0AF2', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p36-3', 'doc-05-nist-sp-800-61r3', '', 36, 'R3: Select incident response strategies for active incidents by balancing the need to quickly recover from an incident with the need to observe the attacker or conduct a more thorough investigation.', 'kb-doc-05-nist-sp-800-61r3-p36-3', 0, 31, '05-nist-sp-800-61r3', 'retrieved', '6234B2F366889BEF55CCBFB125A8E42F8421E1B7736C83E99A7CB656B2A8AAB4', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p36-4', 'doc-05-nist-sp-800-61r3', '', 36, 'N1: Every response strategy decision has trade-offs. For example, a strategy that supports observing the attacker’s behavior or conducting a more thorough investigation may be at odds with the need to quickly return to normal operations.', 'kb-doc-05-nist-sp-800-61r3-p36-4', 0, 36, '05-nist-sp-800-61r3', 'retrieved', '3B92089F002E8BB6158A5D1EB9C9A2F7BCDED4921909FDAB3C895A6D5FFF7937', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p36-5', 'doc-05-nist-sp-800-61r3', '', 36, 'RS.MA-04 Incidents are escalated or elevated as needed High N1: Escalation generally refers to increasing resources or time frames, while elevation usually indicates involving a higher level of management in the response efforts.', 'kb-doc-05-nist-sp-800-61r3-p36-5', 0, 33, '05-nist-sp-800-61r3', 'retrieved', '6257AD313ED71BE2DB9998EA8004B6A481F954C4DF70F5559C527E8ACEAEF003', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p36-6', 'doc-05-nist-sp-800-61r3', '', 36, 'R1: Track and validate the status of all ongoing incidents so that incidents in need of more response resources or a change in response strategy can be identified and the necessary changes initiated rapidly.', 'kb-doc-05-nist-sp-800-61r3-p36-6', 0, 34, '05-nist-sp-800-61r3', 'retrieved', 'DB06C58BF957330949D3315AE70C254B0722A03D0E3E3EC4D4BC31AE9FDDD90F', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p36-7', 'doc-05-nist-sp-800-61r3', '', 36, 'RS.MA-05 The criteria for initiating incident recovery are applied High R1: Apply incident recovery criteria to known and assumed characteristics of the incident to determine when an incident’s recovery processes should be initiated.', 'kb-doc-05-nist-sp-800-61r3-p36-7', 0, 33, '05-nist-sp-800-61r3', 'retrieved', '667C3D05DE27737996B7B4519331E4ACFABDD244655C45E61A190A65B6E336A5', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p36-8', 'doc-05-nist-sp-800-61r3', '', 36, 'R2: Take the possible operational disruption of incident recovery activities into account to determine when recovery should be initiated.', 'kb-doc-05-nist-sp-800-61r3-p36-8', 0, 19, '05-nist-sp-800-61r3', 'retrieved', 'B7FD8CF54276BA10F10627174AFA9F458EC0F04C1C27E198EA44D9A9AAB32898', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
