INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p36-9', 'doc-05-nist-sp-800-61r3', '', 36, 'RS.AN (Incident Analysis) Investigations are conducted to ensure effective response and support forensics and recovery activities High N1: The Incident Analysis Category focuses on investigating, determining, and documenting what has happened during an incident, as well as how and why it happened.', 'kb-doc-05-nist-sp-800-61r3-p36-9', 0, 42, '05-nist-sp-800-61r3', 'retrieved', '657B1A15350489DA6BF3826FFB31D66D9DA5434ED0CC504C9A4DC14F85B6EA3E', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p36-10', 'doc-05-nist-sp-800-61r3', '', 36, 'RS.AN-03 Analysis is performed to establish what has taken place during an incident and the root cause of the incident High R1: Determine the sequence of events that have occurred during the incident and which assets and resources were involved in each of those events.', 'kb-doc-05-nist-sp-800-61r3-p36-10', 0, 45, '05-nist-sp-800-61r3', 'retrieved', '058F5C5433680B99B3F66BFAC18688C8EDAA48A853822D23021860B86F377DC6', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
