INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p36-11', 'doc-05-nist-sp-800-61r3', '', 36, 'R2: Attempt to determine what vulnerabilities, threats, and threat actors were directly or indirectly involved in the incident.', 'kb-doc-05-nist-sp-800-61r3-p36-11', 0, 18, '05-nist-sp-800-61r3', 'retrieved', '31A0F6060F8504A15708494D9E8ABB0D4D157A99C8C5F58226B72237AFB649C6', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
