VALUES ('doc-05-nist-sp-800-61r3-p36-13', 'doc-05-nist-sp-800-61r3', '', 36, 'R4: Check any deployed cyber deception technology for additional information on attacker behavior.', 'kb-doc-05-nist-sp-800-61r3-p36-13', 0, 13, '05-nist-sp-800-61r3', 'retrieved', 'CD9A267E2604F789A88AE5F5BB147AF6F231EBFD183F06F09884DD67D048B13A', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
