INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p37-3', 'doc-05-nist-sp-800-61r3', '', 37, 'RS.AN-06 Actions performed during an investigation are recorded, and the records’ integrity and provenance are preserved High N1: Facts discovered and actions taken during incident response tasks can be recorded by many means, including a paper logbook, audio/video recordings, or automatic session monitoring and logging, as permitted by the organization’s incident response plan and policy.', 'kb-doc-05-nist-sp-800-61r3-p37-3', 0, 55, '05-nist-sp-800-61r3', 'retrieved', 'F429EA25A9BACACC606732F20F9AA72677E26FAF0AD99B5A2A73CD71481FF2B2', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
