INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p37-4', 'doc-05-nist-sp-800-61r3', '', 37, 'R1: Safeguard the confidentiality and integrity of incident response records, and ensure that only authorized personnel have access.', 'kb-doc-05-nist-sp-800-61r3-p37-4', 0, 18, '05-nist-sp-800-61r3', 'retrieved', '7D18C0AE26CCB952B55B1C2318EB292F54E333D1777CD31BEF05AD9C8A66AC29', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p37-5', 'doc-05-nist-sp-800-61r3', '', 37, 'N2: Incident response records can contain sensitive information, such as data on exploited vulnerabilities, recent data breaches, and users who may have performed inappropriate actions. The incident lead is often responsible for ensuring that incident response records are properly safeguarded.', 'kb-doc-05-nist-sp-800-61r3-p37-5', 0, 40, '05-nist-sp-800-61r3', 'retrieved', 'FBD74C801C1B2E633EBC5E136C379B6B72641730EA8F44852CC3E152B031BDCE', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
