INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p37-6', 'doc-05-nist-sp-800-61r3', '', 37, 'RS.AN-07 Incident data and metadata are collected, and their integrity and provenance are preserved High N1: Many incident responses involve the collection of incident data and metadata.', 'kb-doc-05-nist-sp-800-61r3-p37-6', 0, 27, '05-nist-sp-800-61r3', 'retrieved', '23413DC02801F90D5F07706EC743102DC991095D7BCB51DDF4121864139C25DF', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
