INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p37-7', 'doc-05-nist-sp-800-61r3', '', 37, 'Formal evidence gathering and handling using chain-of-custody procedures might not be performed for every incident that occurs (e.g., most malware incidents will not result in prosecution). However, collected incident data is still considered evidence, which is defined as “grounds for belief or disbelief; data on which to base proof or to establish truth or falsehood” [SP800-160v1].', 'kb-doc-05-nist-sp-800-61r3-p37-7', 0, 56, '05-nist-sp-800-61r3', 'retrieved', '182A9EA5F829DCD404A7D2B5596D3A27DC0F7C7ED4CBDB43316CCB49C301465F', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p37-8', 'doc-05-nist-sp-800-61r3', '', 37, 'R1: Collect and retain evidence from an incident in accordance with the organization’s evidence preservation procedures and data retention policies, and consider factors such as the possibility of prosecution, and the cost of retaining the data and the hardware and software needed to access the data in the future.', 'kb-doc-05-nist-sp-800-61r3-p37-8', 0, 49, '05-nist-sp-800-61r3', 'retrieved', 'FDFC7884ECA860743DE93C684AE31940C7D2E10F8120EA561716F28EE62E7F4A', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p37-9', 'doc-05-nist-sp-800-61r3', '', 37, 'RS.AN-08 An incident’s magnitude is estimated and validated High N1: Determining the incident’s magnitude is often one of the most challenging aspects of incident response.', 'kb-doc-05-nist-sp-800-61r3-p37-9', 0, 25, '05-nist-sp-800-61r3', 'retrieved', 'CE949CDD4043D3A6EC9B46E661DD59ECF857DC6B54091F74DF07110F6BAABCA7', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p37-10', 'doc-05-nist-sp-800-61r3', '', 37, 'R1: Look for indicators of compromise, evidence of persistence, and other signs of an incident on both the assets known to be targeted and other potential targets.', 'kb-doc-05-nist-sp-800-61r3-p37-10', 0, 27, '05-nist-sp-800-61r3', 'retrieved', '73925A48CAA4AA1AD9052A2C6D558784D46D5B1F4247157CB8F13055566EE3BA', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
