INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p38-2', 'doc-05-nist-sp-800-61r3', '', 38, '30 CSF Element CSF Element Description Priority Recommendations, Considerations, Notes Skipping this activity or performing it in a superficial way may cause underestimation of the incident’s magnitude, thus allowing the incident to continue indefinitely on other targets without the organization’s knowledge or monitoring.', 'kb-doc-05-nist-sp-800-61r3-p38-2', 0, 43, '05-nist-sp-800-61r3', 'retrieved', 'D05C9F4C8FA15D7F03E17E8E530E07AF62456179A0BAA96613B6F36039E6C401', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
