INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p39-4', 'doc-05-nist-sp-800-61r3', '', 39, 'RS.CO-03 Information is shared with designated internal and external stakeholders High N1: Voluntary incident information sharing is often mutually beneficial because the same threats and attacks simultaneously affect multiple organizations. An example is sharing information about observed TTPs with a sector-specific Information Sharing and Analysis Center (ISAC).', 'kb-doc-05-nist-sp-800-61r3-p39-4', 0, 47, '05-nist-sp-800-61r3', 'retrieved', 'C5F508F955645E4B2AF88E16FA07C6E3A2FDE6D126BEBC9F7E093A032E590474', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p39-5', 'doc-05-nist-sp-800-61r3', '', 39, 'N2: Sharing defensive tactics between organizations can enhance overall situational awareness and increase the resiliency of all. There is a cost to threat actors to develop or purchase exploits and to deploy them. The effective identification and dissemination of detection techniques lowers the attackers’ return on investment and increases their costs.', 'kb-doc-05-nist-sp-800-61r3-p39-5', 0, 51, '05-nist-sp-800-61r3', 'retrieved', '0106BCFBD1740C8312B1AD7C069B43BA0C592D22B1D9172010351F1541150D73', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p39-6', 'doc-05-nist-sp-800-61r3', '', 39, 'N3: Incident handlers might coordinate their efforts with colleagues at partner organizations to share tactical, technical information on mitigating an attack that spans those organizations. The organizations participating in this type of relationship are usually peers without authority over each other. In addition to choosing to share information, they may also pool resources to solve common problems.', 'kb-doc-05-nist-sp-800-61r3-p39-6', 0, 57, '05-nist-sp-800-61r3', 'retrieved', '647097ADFCE49219C6BA5D919BD9C37873FB2BCF078395A5E2F830CD9616BA98', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p39-7', 'doc-05-nist-sp-800-61r3', '', 39, 'R1: Securely share information with stakeholders consistent with the organization’s response plans and information sharing agreements, including contracts with suppliers.', 'kb-doc-05-nist-sp-800-61r3-p39-7', 0, 20, '05-nist-sp-800-61r3', 'retrieved', 'EDC44F4962321273A342B8EDC50001A56A6C0C3CCD3207C2C9479454883D8172', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
