VALUES ('doc-05-nist-sp-800-61r3-p39-10', 'doc-05-nist-sp-800-61r3', '', 39, 'R4: Establish and follow media communications procedures for incident response that comply with the', 'kb-doc-05-nist-sp-800-61r3-p39-10', 0, 14, '05-nist-sp-800-61r3', 'retrieved', 'FAF235CAE110426B1D7DB6A4CE71D06A1140BBA584DBDF1F89B5711048634D90', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
