INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p40-2', 'doc-05-nist-sp-800-61r3', '', 40, '32 CSF Element CSF Element Description Priority Recommendations, Considerations, Notes organization’s policies on media interaction and information disclosure.', 'kb-doc-05-nist-sp-800-61r3-p40-2', 0, 18, '05-nist-sp-800-61r3', 'retrieved', 'CF36CF102F118BCE34F6BF09C1FA2C538A91587B00C25B3058C526D09968A73F', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
