VALUES ('doc-05-nist-sp-800-61r3-p41-2', 'doc-05-nist-sp-800-61r3', '', 41, '33 CSF Element CSF Element Description Priority Recommendations, Considerations, Notes of incidents (e.g., large-scale DDoS attacks) on behalf of the organization.', 'kb-doc-05-nist-sp-800-61r3-p41-2', 0, 21, '05-nist-sp-800-61r3', 'retrieved', '6FE66DE8B0F7C1F86A9D6839A45EA1B2103D37CF362E103768FA16C7CA34E0CB', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
