INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p41-3', 'doc-05-nist-sp-800-61r3', '', 41, 'R1: Allow incident handlers to manually select and perform containment actions instead of or in addition to automated containment measures.', 'kb-doc-05-nist-sp-800-61r3-p41-3', 0, 20, '05-nist-sp-800-61r3', 'retrieved', '2FCA339B8F1F4D18288109A2986CE7798FF11A62FE2272C19C3743AFE6097767', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
