INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p41-4', 'doc-05-nist-sp-800-61r3', '', 41, 'RS.MI-02 Incidents are eradicated High N1: Eradication refers to mitigating an incident’s effects. After containment, eradication may be necessary to eliminate persistence mechanisms and entry points, such as deleting malware, disabling breached user accounts, and identifying and mitigating all exploited vulnerabilities.', 'kb-doc-05-nist-sp-800-61r3-p41-4', 0, 41, '05-nist-sp-800-61r3', 'retrieved', '78704F17B8873E7EC5D45E26ADA0BC396C10FF0E81D791BDDF2A0774ADF59AD2', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p41-5', 'doc-05-nist-sp-800-61r3', '', 41, 'R1: Identify all affected hosts and services within the organization so that all flaws and weaknesses can be remediated.', 'kb-doc-05-nist-sp-800-61r3-p41-5', 0, 19, '05-nist-sp-800-61r3', 'retrieved', 'B9710C088111413AF1667D4E4B6569999316B298446458355260F27B3B67FCF5', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
