VALUES ('doc-05-nist-sp-800-61r3-p41-8', 'doc-05-nist-sp-800-61r3', '', 41, 'R2: Allow incident handlers to manually select and perform eradication actions instead of or in addition to automated eradication measures.', 'kb-doc-05-nist-sp-800-61r3-p41-8', 0, 20, '05-nist-sp-800-61r3', 'retrieved', 'BE421030B771DDFF3A1794410E23AB43ECA2921CDAC3451EC9646B52EC84FD4B', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
