INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p41-9', 'doc-05-nist-sp-800-61r3', '', 41, 'RC (Recover) Assets and operations affected by a cybersecurity incident are restored High N1: During incident recovery, personnel restore systems to normal operations, confirm that the systems are functioning normally, and (if applicable) remediate vulnerabilities to prevent similar incidents.', 'kb-doc-05-nist-sp-800-61r3-p41-9', 0, 39, '05-nist-sp-800-61r3', 'retrieved', '9169DE39B9D27453F23A8C04F6E75B16B5D5DFBDB449B902757451E87F64555F', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
