INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p41-10', 'doc-05-nist-sp-800-61r3', '', 41, 'N2: Recovery operations include restoring systems from clean backups, rebuilding systems, replacing compromised files with clean versions, installing patches, changing passwords, and tightening security controls. In intrusions where the threat actor is highly sophisticated and the full scope of their tactics is not revealed, it may be necessary to go as far as replacing the hardware (e.g., bare metal) of all of the compromised systems.', 'kb-doc-05-nist-sp-800-61r3-p41-10', 0, 65, '05-nist-sp-800-61r3', 'retrieved', 'E960D90D2DBBF0DC72E68A35C40CF60888017327FC22061039852059074862FD', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p42-2', 'doc-05-nist-sp-800-61r3', '', 42, '34 CSF Element CSF Element Description Priority Recommendations, Considerations, Notes RC.RP (Incident Recovery Plan Execution) Restoration activities are performed to ensure operational availability of systems and services affected by cybersecurity incidents High N1: Executing the incident recovery plan involves selecting, prioritizing, and performing recovery actions in a secure manner; verifying the integrity of recovered assets; declaring the end of incident recovery; and completing incident documentation.', 'kb-doc-05-nist-sp-800-61r3-p42-2', 0, 65, '05-nist-sp-800-61r3', 'retrieved', '27D1DE3651A26C3DE6DD8CDE4095A9A85A641D9B0D40F89101EF22A5D03F10AD', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
