VALUES ('doc-05-nist-sp-800-61r3-p42-5', 'doc-05-nist-sp-800-61r3', '', 42, 'R2: Inform all individuals with recovery responsibilities about the plans for recovery and the authorizations required to implement each aspect of the plans.', 'kb-doc-05-nist-sp-800-61r3-p42-5', 0, 23, '05-nist-sp-800-61r3', 'retrieved', 'AD194FEB467ADD2FF0B0D8E63EA135E9EABE1B5715E8B9F89DD59B4A32FD5884', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
