VALUES ('doc-05-nist-sp-800-61r3-p46-2', 'doc-05-nist-sp-800-61r3', '', 46, '38 Appendix A. List of Symbols, Abbreviations, and Acronyms CISA Cybersecurity and Infrastructure Security Agency CPRT Cybersecurity and Privacy Reference Tool CSF Cybersecurity Framework CSP Cloud Service Provider CTI Cyber Threat Intelligence ISAC Information Sharing and Analysis Center ISP Internet Service Provider MOU Memorandum of Understanding MSSP Managed Security Services Provider NDA Non-Disclosure Agreement SIEM Security Information and Event Management SOAR Security Orchestration, Automation, and Response SOC Security Operations Center SOP Standard Operating Procedures TTPs Tactics, Techniques, and Procedures', 'kb-doc-05-nist-sp-800-61r3-p46-2', 0, 79, '05-nist-sp-800-61r3', 'retrieved', '11DD630E093368BED2C75AB0774B6B194443AE716AD6C77D1772DC8818BF4D44', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
