VALUES ('doc-05-nist-sp-800-61r3-p47-2', 'doc-05-nist-sp-800-61r3', '', 47, '39 Appendix B. Glossary adverse cybersecurity event Any event with a potentially negative impact on cybersecurity.', 'kb-doc-05-nist-sp-800-61r3-p47-2', 0, 16, '05-nist-sp-800-61r3', 'retrieved', '21E357E91F95E896007C2D9B0BB4A011D48EA42E64766C67CFFC2D6A96EF3867', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
