INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-05-nist-sp-800-61r3-p47-4', 'doc-05-nist-sp-800-61r3', '', 47, 'cyber threat intelligence Cyber threat information that has been aggregated, transformed, analyzed, interpreted, or enriched to provide the necessary context for decision-making processes. [SP800-150, adapted] cybersecurity incident An occurrence that actually or imminently jeopardizes, without lawful authority, the integrity, confidentiality, or availability of information or an information system; or constitutes a violation or imminent threat of violation of law, security policies, security procedures, or acceptable use policies. [FISMA2014] event Any observable occurrence involving computing assets, including physical and virtual platforms, networks, services, and cloud environments.', 'kb-doc-05-nist-sp-800-61r3-p47-4', 0, 85, '05-nist-sp-800-61r3', 'retrieved', '6A8A7D89A0A015972EF2C2B60CC599A3E9FD13DC88C89CE24D967BB847A6D6AC', 'v1', '{"source_id": "05-nist-sp-800-61r3", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
