VALUES ('doc-06-nist-csf-2-p1-1', 'doc-06-nist-csf-2', '', 1, 'National Institute of Standards and Technology This publication is available free of charge from: https://doi.org/10.6028/NIST.CSWP.29 February 26, 2024 The NIST Cybersecurity Framework (CSF) 2.0', 'kb-doc-06-nist-csf-2-p1-1', 0, 24, '06-nist-csf-2', 'retrieved', '4F91AA1FD366626A003A6FD64B8C6CE7F1AA2341AB574966A1EE01581DC4A109', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
