VALUES ('doc-06-nist-csf-2-p2-5', 'doc-06-nist-csf-2', '', 2, 'Note to Readers Unless otherwise noted, documents cited, referenced, or excerpted in this publication are not wholly incorporated into this publication.', 'kb-doc-06-nist-csf-2-p2-5', 0, 21, '06-nist-csf-2', 'retrieved', 'DCA04410A32821619B52FBE0128576A2DE77CE0D6076502B35C71997AA28A2FB', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
