INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-06-nist-csf-2-p2-6', 'doc-06-nist-csf-2', '', 2, 'Before version 2.0, the Cybersecurity Framework was called the “Framework for Improving Critical Infrastructure Cybersecurity.” This title is not used for CSF 2.0.', 'kb-doc-06-nist-csf-2-p2-6', 0, 23, '06-nist-csf-2', 'retrieved', 'B6AE86AC3B9575A8D9FE6758889D0F79FC8720AC7581657868587F81B51CF7ED', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
