INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-06-nist-csf-2-p3-1', 'doc-06-nist-csf-2', '', 3, 'NIST CSWP 29 The NIST Cybersecurity Framework (CSF) 2.0 February 26, 2024 ii Acknowledgments The CSF is the result of a multi-year collaborative effort across industry, academia, and government in the United States and around the world. NIST acknowledges and thanks all of those who have contributed to this revised CSF. Information on the CSF development process can be found on the NIST CSF website. Lessons learned about th e use of the CSF can always be shared with NIST at cyberframework@nist.gov.', 'kb-doc-06-nist-csf-2-p3-1', 0, 82, '06-nist-csf-2', 'retrieved', '44DD976262054665E4DF82C1586A47E4166C57B14311F988D2C318F0E9B980A0', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-06-nist-csf-2-p4-1', 'doc-06-nist-csf-2', '', 4, 'NIST CSWP 29 The NIST Cybersecurity Framework (CSF) 2.0 February 26, 2024 iii Table of Contents 1. Cybersecurity Framework (CSF) Overview .......................................................................................1 2. Introduction to the CSF Core ...........................................................................................................3 3. Introduction to CSF Profiles and Tiers .............................................................................................6 4. Introduction to Online Resources That Supplement the CSF ............................................................9 5. Improving Cybersecurity Risk Communication and Integration ...................................................... 10 Appendix A. CSF Core ....................................................................................................................... 15 Appendix B. CSF Tiers ....................................................................................................................... 24 Appendix C. Glossary ....................................................................................................................... 26', 'kb-doc-06-nist-csf-2-p4-1', 0, 73, '06-nist-csf-2', 'retrieved', 'CAE47D7F1D09DB5814FC13C2707206131037D07A9D7C8B863B1EB7FB4CA21CE9', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
