INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-06-nist-csf-2-p4-2', 'doc-06-nist-csf-2', '', 4, 'List of Figures Fig. 1. CSF Core structure ....................................................................................................................3 Fig. 2. CSF Functions ...........................................................................................................................5 Fig. 3. Steps for creating and using a CSF Organizational Profile ...........................................................6 Fig. 4. CSF Tiers for cybersecurity risk governance and management ...................................................8 Fig. 5. Using the CSF to improve risk management communication .................................................... 10 Fig. 6. Cybersecurity and privacy risk relationship ............................................................................. 13', 'kb-doc-06-nist-csf-2-p4-2', 0, 58, '06-nist-csf-2', 'retrieved', 'F42E73107854D94B82C804A8E53ACF7A2145D3BA237F2597CA0D5E077DB6F18B', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
