INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-06-nist-csf-2-p6-7', 'doc-06-nist-csf-2', '', 6, '• Understand and Assess: Describe the current or target cybersecurity posture of part or all of an organization, determine gaps, and assess progress toward addressing those gaps.', 'kb-doc-06-nist-csf-2-p6-7', 0, 27, '06-nist-csf-2', 'retrieved', '287B1611F8DA4AFBBB43BCF2A0F3FC56E10CE953318C9B078A1CE3E8C748C2E1', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
