INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-06-nist-csf-2-p13-3', 'doc-06-nist-csf-2', '', 13, 'approach to managing cybersecurity risks. Progression to higher Tiers is encouraged when risks or mandates are greater or when a cost-benefit analysis indicates a feasible and cost-effective reduction of negative cybersecurity risks.', 'kb-doc-06-nist-csf-2-p13-3', 0, 32, '06-nist-csf-2', 'retrieved', '113F6C4B1454EE042940B3097C20A5196AEBC225E1A6595A3833B30491C9AA4F', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
