VALUES ('doc-06-nist-csf-2-p29-3', 'doc-06-nist-csf-2', '', 29, 'Table 2. Notional Illustration of the CSF Tiers Tier Cybersecurity Risk Governance Cybersecurity Risk Management Tier 1: Partial Application of the organizational cybersecurity risk strategy is managed in an ad hoc manner.', 'kb-doc-06-nist-csf-2-p29-3', 0, 32, '06-nist-csf-2', 'retrieved', 'D18D0C294BD89D0E63475468BED4DD2CC78C746519DFB7C5D0460829715ABCDA', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
