VALUES ('doc-06-nist-csf-2-p29-4', 'doc-06-nist-csf-2', '', 29, 'Prioritization is ad hoc and not formally based on objectives or threat environment.', 'kb-doc-06-nist-csf-2-p29-4', 0, 13, '06-nist-csf-2', 'retrieved', '0AC99400B33045C51CA8B6A065A7B47D81EF34B0948F1664D7F11C2ACEDB54CA', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
