VALUES ('doc-06-nist-csf-2-p29-6', 'doc-06-nist-csf-2', '', 29, 'The organization implements cybersecurity risk management on an irregular, case-by-case basis.', 'kb-doc-06-nist-csf-2-p29-6', 0, 11, '06-nist-csf-2', 'retrieved', 'C23C76F9CFC94F66AE515E309D045F9112803B4A51A5C717FD4CFE7FEA61EB11', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
