VALUES ('doc-06-nist-csf-2-p29-8', 'doc-06-nist-csf-2', '', 29, 'The organization is generally unaware of the cybersecurity risks associated with its suppliers and the products and services it acquires and uses.', 'kb-doc-06-nist-csf-2-p29-8', 0, 22, '06-nist-csf-2', 'retrieved', '33C3CDF067198AEB0651694E9CA205753177C6200E70F55EC5B304807B5ED576', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
