VALUES ('doc-06-nist-csf-2-p29-9', 'doc-06-nist-csf-2', '', 29, 'Tier 2: Risk Informed Risk management practices are approved by management but may not be established as organization- wide policy.', 'kb-doc-06-nist-csf-2-p29-9', 0, 20, '06-nist-csf-2', 'retrieved', '0A21058690F0C06C4066958DA7C9DD69502C6320A8301DAC34B23538FAD4BD3E', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
