VALUES ('doc-06-nist-csf-2-p29-10', 'doc-06-nist-csf-2', '', 29, 'The prioritization of cybersecurity activities and protection needs is directly informed by organizational risk objectives, the threat environment, or business/mission requirements.', 'kb-doc-06-nist-csf-2-p29-10', 0, 21, '06-nist-csf-2', 'retrieved', '093B1E11C88F6B201917E255889D1B7CD12E9DA29E0816D8D277202E698B7B6B', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
