INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-06-nist-csf-2-p29-11', 'doc-06-nist-csf-2', '', 29, 'There is an awareness of cybersecurity risks at the organizational level, but an organization-wide approach to managing cybersecurity risks has not been established.', 'kb-doc-06-nist-csf-2-p29-11', 0, 23, '06-nist-csf-2', 'retrieved', '43C3C4A232529EBF9855CB260F9859E8461F090048BD7DB2703F1905911AAC15', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
