INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-06-nist-csf-2-p29-12', 'doc-06-nist-csf-2', '', 29, 'Consideration of cybersecurity in organizational objectives and programs may occur at some but not all levels of the organization. Cyber risk assessment of organizational and external assets occurs but is not typically repeatable or reoccurring.', 'kb-doc-06-nist-csf-2-p29-12', 0, 35, '06-nist-csf-2', 'retrieved', '2ED319AA685DA50F309F61FEFCA0306EE67169276D9673540E9F0C64ED5F1F2D', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
