VALUES ('doc-06-nist-csf-2-p29-13', 'doc-06-nist-csf-2', '', 29, 'Cybersecurity information is shared within the organization on an informal basis.', 'kb-doc-06-nist-csf-2-p29-13', 0, 11, '06-nist-csf-2', 'retrieved', 'EA27B2EAE4114794E8A040236F04C3FC9D58DFEECACE978714CC6A7A5841D4BB', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
