VALUES ('doc-06-nist-csf-2-p29-15', 'doc-06-nist-csf-2', '', 29, 'Tier 3: Repeatable The organization’s risk management practices are formally approved and expressed as policy.', 'kb-doc-06-nist-csf-2-p29-15', 0, 15, '06-nist-csf-2', 'retrieved', '63D294102A1BA9F73F72E0ED89E4B5DE127AE5C2A713222A01A0955D032FCFE7', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
