VALUES ('doc-06-nist-csf-2-p29-16', 'doc-06-nist-csf-2', '', 29, 'Risk-informed policies, processes, and procedures are defined, implemented as intended, and reviewed.', 'kb-doc-06-nist-csf-2-p29-16', 0, 12, '06-nist-csf-2', 'retrieved', '3A878BAA495A9447C857DDC3A6518D38D079F7E8A86811016D6EC1A7633534CA', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
