VALUES ('doc-06-nist-csf-2-p29-17', 'doc-06-nist-csf-2', '', 29, 'Organizational cybersecurity practices are regularly updated based on the application of risk management processes to changes in business/mission requirements, threats, and technological landscape.', 'kb-doc-06-nist-csf-2-p29-17', 0, 23, '06-nist-csf-2', 'retrieved', '67CF75C3292D27A8521BB5D1960E190AB1B9BBBD8F6EBEC3F9113CC04466CE9B', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
