INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-06-nist-csf-2-p29-18', 'doc-06-nist-csf-2', '', 29, 'There is an organization-wide approach to managing cybersecurity risks. Cybersecurity information is routinely shared throughout the organization.', 'kb-doc-06-nist-csf-2-p29-18', 0, 17, '06-nist-csf-2', 'retrieved', '060B744F8832B3A55C5ECD1AC99027E81EDDA08CDEC25B61D8B5793DA7D50117', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
