INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-06-nist-csf-2-p29-19', 'doc-06-nist-csf-2', '', 29, 'Consistent methods are in place to respond effectively to changes in risk. Personnel possess the knowledge and skills to perform their appointed roles and responsibilities.', 'kb-doc-06-nist-csf-2-p29-19', 0, 25, '06-nist-csf-2', 'retrieved', 'B76F15FEA2F1AABC2AB772FB8B4A88737346666B9E219CF31E54520B88CAC9B7', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
