INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-06-nist-csf-2-p29-20', 'doc-06-nist-csf-2', '', 29, 'The organization consistently and accurately monitors the cybersecurity risks of assets. Senior cybersecurity and non-cybersecurity executives communicate regularly regarding cybersecurity risks. Executives ensure that cybersecurity is considered through all lines of operation in the organization.', 'kb-doc-06-nist-csf-2-p29-20', 0, 35, '06-nist-csf-2', 'retrieved', '0776622431BD04D4C8ABB1026B58320D6748A9DC3922F7F4C7BC09625EFC5028', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-06-nist-csf-2-p30-2', 'doc-06-nist-csf-2', '', 30, '25 Tier Cybersecurity Risk Governance Cybersecurity Risk Management The organization risk strategy is informed by the cybersecurity risks associated with its suppliers and the products and services it acquires and uses. Personnel formally act upon those risks through mechanisms such as written agreements to communicate baseline requirements, governance structures (e.g., risk councils), and policy implementation and monitoring. These actions are implemented consistently and as intended and are continuously monitored and reviewed.', 'kb-doc-06-nist-csf-2-p30-2', 0, 71, '06-nist-csf-2', 'retrieved', 'A5F2BA5A4B97F3CD174A12AA2EB4956B4125420E6ADD9DD7F461A4BBA20FD2AF', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-06-nist-csf-2-p30-3', 'doc-06-nist-csf-2', '', 30, 'Tier 4: Adaptive There is an organization-wide approach to managing cybersecurity risks that uses risk-informed policies, processes, and procedures to address potential cybersecurity events. The relationship between cybersecurity risks and organizational objectives is clearly understood and considered when making decisions. Executives monitor cybersecurity risks in the same context as financial and other organizational risks. The organizational budget is based on an understanding of the current and predicted risk environment and risk tolerance.', 'kb-doc-06-nist-csf-2-p30-3', 0, 72, '06-nist-csf-2', 'retrieved', '8C106DC48033B1DFE16D8B43FD4A69D02187633BD30EAD48CB6FF995B9A056FF', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-06-nist-csf-2-p30-4', 'doc-06-nist-csf-2', '', 30, 'Business units implement executive vision and analyze system-level risks in the context of the organizational risk tolerances.', 'kb-doc-06-nist-csf-2-p30-4', 0, 17, '06-nist-csf-2', 'retrieved', 'FDDEE4A637E6DFB899F1FD3C0B597264F21C999F834A7FCE069AECECB29F601B', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-06-nist-csf-2-p30-5', 'doc-06-nist-csf-2', '', 30, 'Cybersecurity risk management is part of the organizational culture. It evolves from an awareness of previous activities and continuous awareness of activities on organizational systems and networks. The organization can quickly and efficiently account for changes to business/mission objectives in how risk is approached and communicated.', 'kb-doc-06-nist-csf-2-p30-5', 0, 46, '06-nist-csf-2', 'retrieved', '0421BADF62F7BC43CF7A9A2287789D947B76FD848CC2FED7331975AFABD033BF', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-06-nist-csf-2-p30-6', 'doc-06-nist-csf-2', '', 30, 'The organization adapts its cybersecurity practices based on previous and current cybersecurity activities, including lessons learned and predictive indicators.', 'kb-doc-06-nist-csf-2-p30-6', 0, 19, '06-nist-csf-2', 'retrieved', 'C3D87C4D7A6029EE522643FBD2D299A38B016CB7BC2EC91AA960B57B558B386B', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-06-nist-csf-2-p30-7', 'doc-06-nist-csf-2', '', 30, 'Through a process of continuous improvement that incorporates advanced cybersecurity technologies and practices, the organization actively adapts to a changing technological landscape and responds in a timely and effective manner to evolving, sophisticated threats.', 'kb-doc-06-nist-csf-2-p30-7', 0, 34, '06-nist-csf-2', 'retrieved', 'CAB042152D25C68318D8BC7E4EFE8766094A9B54AE1A3B2E350AA2FA76747952', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
