INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-06-nist-csf-2-p30-8', 'doc-06-nist-csf-2', '', 30, 'The organization uses real-time or near real-time information to understand and consistently act upon the cybersecurity risks associated with its suppliers and the products and services it acquires and uses.', 'kb-doc-06-nist-csf-2-p30-8', 0, 30, '06-nist-csf-2', 'retrieved', '5EFE429D207036C165F0CAA68B02181AC8203397C79BDC4920EFB0260F11E613', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
