VALUES ('doc-06-nist-csf-2-p30-9', 'doc-06-nist-csf-2', '', 30, 'Cybersecurity information is constantly shared throughout the organization and with authorized third parties.', 'kb-doc-06-nist-csf-2-p30-9', 0, 13, '06-nist-csf-2', 'retrieved', '0400E7DC83FFAAD5DB103DFCD871B4A9187183FE2F155ED91AF734C347D26A68', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
