VALUES ('doc-06-nist-csf-2-p31-2', 'doc-06-nist-csf-2', '', 31, '26 Appendix C. Glossary CSF Category A group of related cybersecurity outcomes that collectively comprise a CSF Function.', 'kb-doc-06-nist-csf-2-p31-2', 0, 18, '06-nist-csf-2', 'retrieved', 'CAC4EB4CBC759FBF939E305D1EA51398757B5A4C2C340E411C54620BDFDC10A1', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
