INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-06-nist-csf-2-p31-3', 'doc-06-nist-csf-2', '', 31, 'CSF Community Profile A baseline of CSF outcomes that is created and published to address shared interests and goals among a number of organizations. A Community Profile is typically developed for a particular sector, subsector, technology, threat type, or other use case. An organization can use a Community Profile as the basis for its own Target Profile.', 'kb-doc-06-nist-csf-2-p31-3', 0, 57, '06-nist-csf-2', 'retrieved', '06E34D5C66978182EBA72A3C7AF26A00A0BAA1B09F9B166D07235C964A4DDE22', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
