INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-06-nist-csf-2-p31-4', 'doc-06-nist-csf-2', '', 31, 'CSF Core A taxonomy of high-level cybersecurity outcomes that can help any organization manage its cybersecurity risk s. Its components are a hierarchy of Functions, Categories, and Subcategories that detail each outcome.', 'kb-doc-06-nist-csf-2-p31-4', 0, 32, '06-nist-csf-2', 'retrieved', '92C2B6C6F1754799E701E61A9881B9AF90A2713B791FA87FFAA3A7364EE6F7F9', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
