INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-06-nist-csf-2-p31-5', 'doc-06-nist-csf-2', '', 31, 'CSF Current Profile A part of an Organizational Profile that specifies the Core outcomes that an organization is currently achieving (or attempting to achieve) and characterizes how or to what extent each outcome is being achieved.', 'kb-doc-06-nist-csf-2-p31-5', 0, 36, '06-nist-csf-2', 'retrieved', '4CF958232AB7EB89BA41AD8822E4B416FD9B617BDF6570643568CCF3450A1491', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
