VALUES ('doc-06-nist-csf-2-p31-7', 'doc-06-nist-csf-2', '', 31, 'CSF Implementation Example A concise, action-oriented, notional illustration of a way to help achieve a CSF Core outcome.', 'kb-doc-06-nist-csf-2-p31-7', 0, 18, '06-nist-csf-2', 'retrieved', '49818F72206F63F44DE1BAFF05A0F8C2E04D62FEBF4976C668D1F2B381A2D454', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
