VALUES ('doc-06-nist-csf-2-p31-9', 'doc-06-nist-csf-2', '', 31, 'CSF Organizational Profile A mechanism for describing an organization’s current and/or target cybersecurity posture in terms of the CSF Core’s outcomes.', 'kb-doc-06-nist-csf-2-p31-9', 0, 21, '06-nist-csf-2', 'retrieved', '0766902310DC0F905E8958589C112B1A697DDF4F061B95F1B05391AC6241B5B5', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
