VALUES ('doc-06-nist-csf-2-p31-11', 'doc-06-nist-csf-2', '', 31, 'CSF Subcategory A group of more specific outcomes of technical and management cybersecurity activities that comprise a CSF Category.', 'kb-doc-06-nist-csf-2-p31-11', 0, 19, '06-nist-csf-2', 'retrieved', '7BA109C11993D3413CE69FAB394E244867867B7CECC7902208C027F2EAE29B6E', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
