VALUES ('doc-06-nist-csf-2-p31-12', 'doc-06-nist-csf-2', '', 31, 'CSF Target Profile A part of an Organizational Profile that specifies the desired Core outcomes that an organization has selected and prioritized for achieving its cybersecurity risk management objectives.', 'kb-doc-06-nist-csf-2-p31-12', 0, 29, '06-nist-csf-2', 'retrieved', 'A1002CCB7B5020F872C6854D59E1F16C0B1660B06ED95A2A6FD15AC3DA7F6BD7', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
