VALUES ('doc-06-nist-csf-2-p31-13', 'doc-06-nist-csf-2', '', 31, 'CSF Tier A characterization of the rigor of an organization’s cybersecurity risk governance and management practices.', 'kb-doc-06-nist-csf-2-p31-13', 0, 16, '06-nist-csf-2', 'retrieved', '2AE8F98E15B14915F82ED643B3F131DC6C03F7AF2657BEF71C2039C90248D9FF', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
