INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-06-nist-csf-2-p31-14', 'doc-06-nist-csf-2', '', 31, 'There are four Tiers: Partial (Tier 1), Risk Informed (Tier 2), Repeatable (Tier 3), and Adaptive (Tier 4).', 'kb-doc-06-nist-csf-2-p31-14', 0, 18, '06-nist-csf-2', 'retrieved', 'F84716DC8942A17C9BACCCB5A7DE78166072DCA76FAB8D7F19A3B47140F0D61E', 'v1', '{"source_id": "06-nist-csf-2", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
