VALUES ('doc-09-mitre-attack-p0-1', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-17T12:56:55.080Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "ATT&CK for Enterprise provides a knowledge base of real-world adversary behavior targeting traditional enterprise networks. ATT&CK for Enterprise covers the following platforms: Windows, macOS, Linux, PRE, Office 365, Google Workspace, IaaS, Network, and Containers.", "id": "x-mitre-collection--1f5f1533-f617-4ca8-9ab4-6a02367fa019", "modified": "2026-08-05T21:33:58.496Z", "name": "Enterprise ATT&CK", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-collection", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contents": [{"object_modified": "2026-05-12T15:12:00.617Z", "object_ref": "attack-pattern--0042a9f5-f053-4769-b3ef-9ad018dfa298"}, {"object_modified": "2026-05-12T15:12:00.618Z", "object_ref": "attack-pattern--005a06c6-14bf-4118-afa0-ebcd8aebb0c9"}, {"object_modified": "2026-05-12T15:12:00.619Z", "object_ref": "attack-pattern--005cc321-08ce-4d17-b1ea-cb5275926520"}, {"object_modified": "2026-04-14T22:53:15.802Z", "object_ref": "attack-pattern--00d0b012-8a03-410e-95de-5826bf542de6"}, {"object_modified": "2026-05-12T15:12:00.619Z", "object_ref": "attack-pattern--00f90846-cbd1-4fc5-9233-df5c2bf2a662"}, {"object_modified": "2025-10-24T17:48:19.567Z", "object_ref": "attack-pattern--01327cde-66c4-4123-bf34-5f258d59457b"}, {"object_modified": "2026-05-12T15:12:00.619Z", "object_ref": "attack-pattern--01a5a209-b94c-450b-b7f9-946497d91055"}, {"object_modified": "2026-05-12T15:12:00.619Z", "object_ref": "attack-pattern--01c9b54f-c04e-41ba-b0c3-cfe784b3a463"}, {"object_modified": "2025-10-24T17:48:19.775Z", "object_ref": "attack-pattern--01df3350-ce05-4bdf-bdf8-0a919a66d4a8"}, {"object_modified": "2026-05-12T15:12:00.619Z", "object_ref": "attack-pattern--0259baeb-9f63-4c69-bf10-eb038c390688"}, {"