VALUES ('doc-09-mitre-attack-p0-4', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["FrostyGoop Incident"], "created": "2024-11-20T23:15:36.728Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FrostyGoop Incident](https://attack.mitre.org/campaigns/C0041) took place in January 2024 against a municipal district heating company in Ukraine. Following initial access via likely exploitation of external facing services, [FrostyGoop](https://attack.mitre.org/software/S1165) was used to manipulate ENCO control systems via legitimate Modbus commands to impact the delivery of heating services to Ukrainian civilians.(Citation: Dragos FROSTYGOOP 2024)(Citation: Nozomi BUSTLEBERM 2024)", "external_references": [{"external_id": "C0041", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0041"}, {"description": "Mark Graham, Carolyn Ahlers, Kyle O''Meara; Dragos. (2024, July). Impact of FrostyGoop ICS Malware on Connected OT Systems. Retrieved November 20, 2024.", "source_name": "Dragos FROSTYGOOP 2024", "url": "https://hub.dragos.com/hubfs/Reports/Dragos-FrostyGoop-ICS-Malware-Intel-Brief-0724_r2.pdf"}, {"description": "Nozomi Networks Labs. (2024, July 24). Cyberwarfare Targeting OT: Protecting Against FrostyGoop/BUSTLEBERM Malware. Retrieved November 20, 2024.", "source_name": "Nozomi BUSTLEBERM 2024", "url": "https://www.nozominetworks.com/blog/protecting-against-frostygoop-bustleberm-malware"}], "first_seen": "2024-01-01T07:00:00.000Z", "id": "campaign--1169ff24-b35f-4d8d-8cf3-643a2834227f", "last_seen": "2024-01-01T07:00:00.000Z", "modified": "2026-07-31T20:48:13.258Z", "name": "FrostyGoop Incident", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack", "ics-attack"], "x_mitre_first_seen_citation": "(Citation: Dragos FROSTYGOOP 2024)", "x_mitre_last_seen_citation": "(Citation: Dragos FROSTYGOOP 2024)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-4', 0, 161, '09-mitre-attack', 'retrieved', '05A88B0B22E8635F906F85D47BAFD0AE2BA025F9FD9D18F43C4C88BFD4210AB3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
