VALUES ('doc-09-mitre-attack-p0-7', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["RedDelta Modified PlugX Infection Chain Operations"], "created": "2025-01-14T22:38:27.986Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RedDelta Modified PlugX Infection Chain Operations](https://attack.mitre.org/campaigns/C0047) was executed by [Mustang Panda](https://attack.mitre.org/groups/G0129) from mid-2023 through the end of 2024 against multiple entities in East and Southeast Asia. [RedDelta Modified PlugX Infection Chain Operations](https://attack.mitre.org/campaigns/C0047) involved phishing to deliver malicious files or links to users prompting follow-on installer downloads to load [PlugX](https://attack.mitre.org/software/S0013) on victim machines in a persistent state.(Citation: Recorded Future RedDelta 2025)", "external_references": [{"external_id": "C0047", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0047"}, {"description": "Insikt Group. (2025, January 9). Chinese State-Sponsored RedDelta Targeted Taiwan, Mongolia, and Southeast Asia with Adapted PlugX Infection Chain. Retrieved January 14, 2025.", "source_name": "Recorded Future RedDelta 2025", "url": "https://go.recordedfuture.com/hubfs/reports/cta-cn-2025-0109.pdf"}], "first_seen": "2023-07-01T06:00:00.000Z", "id": "campaign--276671b5-5425-48db-ad65-c8c2564a969b", "last_seen": "2024-12-01T07:00:00.000Z", "modified": "2026-07-31T18:47:18.644Z", "name": "RedDelta Modified PlugX Infection Chain Operations", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: Recorded Future RedDelta 2025)", "x_mitre_last_seen_citation": "(Citation: Recorded Future RedDelta 2025)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-7', 0, 155, '09-mitre-attack', 'retrieved', 'E23DE412355AAADBA3094A511ECFDC5019025A71836467C7D393C0A8ED25A461', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
