VALUES ('doc-09-mitre-attack-p0-9', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Operation Sharpshooter"], "created": "2022-09-26T21:18:34.075Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Operation Sharpshooter](https://attack.mitre.org/campaigns/C0013) was a global cyber espionage campaign that targeted nuclear, defense, government, energy, and financial companies, with many located in Germany, Turkey, the United Kingdom, and the United States. Security researchers noted the campaign shared many similarities with previous [Lazarus Group](https://attack.mitre.org/groups/G0032) operations, including fake job recruitment lures and shared malware code.(Citation: McAfee Sharpshooter December 2018)(Citation: Bleeping Computer Op Sharpshooter March 2019)(Citation: Threatpost New Op Sharpshooter Data March 2019) ", "external_references": [{"external_id": "C0013", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0013"}, {"description": "I. Ilascu. (2019, March 3). Op ''Sharpshooter'' Connected to North Korea''s Lazarus Group. Retrieved September 26, 2022.", "source_name": "Bleeping Computer Op Sharpshooter March 2019", "url": "https://www.bleepingcomputer.com/news/security/op-sharpshooter-connected-to-north-koreas-lazarus-group/"}, {"description": "L. O''Donnell. (2019, March 3). RSAC 2019: New Operation Sharpshooter Data Reveals Higher Complexity, Scope. Retrieved September 26, 2022.", "source_name": "Threatpost New Op Sharpshooter Data March 2019", "url": "https://threatpost.com/sharpshooter-complexity-scope/142359/"}, {"description": "Sherstobitoff, R., Malhotra, A., et. al.. (2018, December 18). Operation Sharpshooter Campaign Targets Global Defense, Critical Infrastructure. Retrieved May 14, 2020.", "source_name": "McAfee Sharpshooter December 2018", "url": "https://www.mcafee.com/enterprise/en-us/assets/reports/rp-operation-sharpshooter.pdf"}], "first_seen": "2017-09-01T05:00:00.000Z", "id": "campaign--37764c78-2a99-46d1-a7ea-6454b9bf93a0", "last_seen": "2019-03-01T06:00:00.000Z", "modified": "2026-07-31T18:47:19.685Z", "name": "Operation Sharpshooter", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: Threatpost New Op Sharpshooter Data March 2019)", "x_mitre_last_seen_citation": "(Citation: Threatpost New Op Sharpshooter Data March 2019)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-9', 0, 218, '09-mitre-attack', 'retrieved', 'B2FCEE7ABFF76CE38A14497E8F015D46F22AD21FC9FD4A425A660F508BBA1B11', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
