VALUES ('doc-09-mitre-attack-p0-11', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Operation MidnightEclipse"], "created": "2025-01-15T19:56:55.070Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Operation MidnightEclipse](https://attack.mitre.org/campaigns/C0048) was a campaign conducted in March and April 2024 that involved initial exploit of zero-day vulnerability CVE-2024-3400, a critical command injection vulnerability in the GlobalProtect feature of Palo Alto Networks PAN-OS.(Citation: Volexity UPSTYLE 2024)(Citation: Palo Alto MidnightEclipse APR 2024)", "external_references": [{"external_id": "C0048", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0048"}, {"description": "Unit 42. (2024, April 12). Threat Brief: Operation MidnightEclipse, Post-Exploitation Activity Related to CVE-2024-3400 . Retrieved January 15, 2025.", "source_name": "Palo Alto MidnightEclipse APR 2024", "url": "https://unit42.paloaltonetworks.com/cve-2024-3400/"}, {"description": "Volexity Threat Research. (2024, April 12). Zero-Day Exploitation of Unauthenticated Remote Code Execution Vulnerability in GlobalProtect (CVE-2024-3400). Retrieved November 20, 2024.", "source_name": "Volexity UPSTYLE 2024", "url": "https://www.volexity.com/blog/2024/04/12/zero-day-exploitation-of-unauthenticated-remote-code-execution-vulnerability-in-globalprotect-cve-2024-3400/"}], "first_seen": "2024-03-01T05:00:00.000Z", "id": "campaign--455b011a-2510-49ab-a96f-2f84d6a80189", "last_seen": "2024-04-01T04:00:00.000Z", "modified": "2026-07-31T18:47:20.105Z", "name": "Operation MidnightEclipse", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: Volexity UPSTYLE 2024)", "x_mitre_last_seen_citation": "(Citation: Volexity UPSTYLE 2024)(Citation: Palo Alto MidnightEclipse APR 2024)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-11', 0, 156, '09-mitre-attack', 'retrieved', 'DB50FD4F6B31FD2B85E007163CBF34127BCBDBA82AEA15481B927D7AF5ECCFF3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
