VALUES ('doc-09-mitre-attack-p0-12', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Triton Safety Instrumented System Attack"], "created": "2024-03-25T17:47:37.619Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Triton Safety Instrumented System Attack](https://attack.mitre.org/campaigns/C0030) was a campaign employed by [TEMP.Veles](https://attack.mitre.org/groups/G0088) which leveraged the [Triton](https://attack.mitre.org/software/S1009) malware framework against a petrochemical organization.(Citation: Triton-EENews-2017) The malware and techniques used within this campaign targeted specific Triconex [Safety Controller](https://attack.mitre.org/assets/A0010)s within the environment.(Citation: FireEye TRITON 2018) The incident was eventually discovered due to a safety trip that occurred as a result of an issue in the malware.(Citation: FireEye TRITON 2017)\n", "external_references": [{"external_id": "C0030", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0030"}, {"description": "Blake Sobczak. (2019, March 7). The inside story of the world’s most dangerous malware. Retrieved March 25, 2024.", "source_name": "Triton-EENews-2017", "url": "https://www.eenews.net/articles/the-inside-story-of-the-worlds-most-dangerous-malware/"}, {"description": "Johnson, B, et. al. (2017, December 14). Attackers Deploy New ICS Attack Framework \"TRITON\" and Cause Operational Disruption to Critical Infrastructure. Retrieved January 6, 2021.", "source_name": "FireEye TRITON 2017", "url": "https://www.fireeye.com/blog/threat-research/2017/12/attackers-deploy-new-ics-attack-framework-triton.html"}, {"description": "Miller, S. Reese, E. (2018, June 7). A Totally Tubular Treatise on TRITON and TriStation. Retrieved November 17, 2024.", "source_name": "FireEye TRITON 2018", "url": "https://web.archive.org/web/20200618231942/https://www.fireeye.com/blog/threat-research/2018/06/totally-tubular-treatise-on-triton-and-tristation.html"}], "first_seen": "2017-06-01T04:00:00.000Z", "id": "campaign--45a98f02-852f-49b2-94c0-c63207bebbbf", "last_seen": "2017-08-01T04:00:00.000Z", "modified": "2026-07-31T20:48:13.868Z", "name": "Triton Safety Instrumented System Attack", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack", "ics-attack"], "x_mitre_first_seen_citation": "(Citation: Triton-EENews-2017)", "x_mitre_last_seen_citation": "(Citation: Triton-EENews-2017)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-12', 0, 203, '09-mitre-attack', 'retrieved', '71836DD36057550C007AD5B106EA068EE8CC58B16FF6E63316A101BF6AB847CB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
