VALUES ('doc-09-mitre-attack-p0-14', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["2015 Ukraine Electric Power Attack"], "created": "2023-09-27T13:11:52.340Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[2015 Ukraine Electric Power Attack](https://attack.mitre.org/campaigns/C0028) was a [Sandworm Team](https://attack.mitre.org/groups/G0034) campaign during which they used [BlackEnergy](https://attack.mitre.org/software/S0089) (specifically BlackEnergy3) and [KillDisk](https://attack.mitre.org/software/S0607) to target and disrupt transmission and distribution substations within the Ukrainian power grid. This campaign was the first major public attack conducted against the Ukrainian power grid by Sandworm Team.", "external_references": [{"external_id": "C0028", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0028"}, {"description": "Booz Allen Hamilton. (2016). When The Lights Went Out. Retrieved December 18, 2024.", "source_name": "Booz Allen Hamilton", "url": "https://www.boozallen.com/content/dam/boozallen/documents/2016/09/ukraine-report-when-the-lights-went-out.pdf"}], "first_seen": "2015-12-01T05:00:00.000Z", "id": "campaign--46421788-b6e1-4256-b351-f8beffd1afba", "last_seen": "2016-01-01T05:00:00.000Z", "modified": "2026-08-04T20:48:44.047Z", "name": "2015 Ukraine Electric Power Attack", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack", "ics-attack"], "x_mitre_first_seen_citation": "(Citation: Booz Allen Hamilton)", "x_mitre_last_seen_citation": "(Citation: Booz Allen Hamilton)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-14', 0, 130, '09-mitre-attack', 'retrieved', 'C67A5D85DA8DC4DCEBA4F4017C094200880FAC113941DD3B2A39AA19D4346215', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
