VALUES ('doc-09-mitre-attack-p0-15', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Indian Critical Infrastructure Intrusions"], "created": "2024-11-21T22:45:01.292Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Indian Critical Infrastructure Intrusions](https://attack.mitre.org/campaigns/C0043) is a sequence of intrusions from 2021 through early 2022 linked to People’s Republic of China (PRC) threat actors, particularly [RedEcho](https://attack.mitre.org/groups/G1042) and Threat Activity Group 38 (TAG38). The intrusions appear focused on IT system breach in Indian electric utility entities and logistics firms, as well as potentially managed service providers operating within India. Although focused on OT-operating entities, there is no evidence this campaign was able to progress beyond IT breach and information gathering to OT environment access.(Citation: RecordedFuture RedEcho 2021)(Citation: RecordedFuture RedEcho 2022)", "external_references": [{"external_id": "C0043", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0043"}, {"description": "Recorded Future Insikt Group. (2021, February). China-Linked Group RedEcho Targets the Indian Power Sector Amid Heightened Border Tensions. Retrieved November 21, 2024.", "source_name": "RecordedFuture RedEcho 2021", "url": "https://go.recordedfuture.com/hubfs/reports/cta-2021-0228.pdf"}, {"description": "Recorded Future Insikt Group. (2022, April 6). Continued Targeting of Indian Power Grid Assets by Chinese State-Sponsored Activity Group. Retrieved November 21, 2024.", "source_name": "RecordedFuture RedEcho 2022", "url": "https://go.recordedfuture.com/hubfs/reports/ta-2022-0406.pdf"}], "first_seen": "2021-01-01T07:00:00.000Z", "id": "campaign--4b7f9839-4822-4c19-8a1f-70bb61ba97e1", "last_seen": "2022-04-01T06:00:00.000Z", "modified": "2026-07-31T18:47:21.276Z", "name": "Indian Critical Infrastructure Intrusions", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: RecordedFuture RedEcho 2021)", "x_mitre_last_seen_citation": "(Citation: RecordedFuture RedEcho 2022)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-15', 0, 205, '09-mitre-attack', 'retrieved', 'FB66C15335354623C2EDE440EB381FA249C768D8E2E33C8ADFFDA8B9B7DDD75C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
