VALUES ('doc-09-mitre-attack-p0-16', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Operation Spalax"], "created": "2022-09-16T15:32:41.893Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Operation Spalax](https://attack.mitre.org/campaigns/C0005) was a campaign that primarily targeted Colombian government organizations and private companies, particularly those associated with the energy and metallurgical industries. The [Operation Spalax](https://attack.mitre.org/campaigns/C0005) threat actors distributed commodity malware and tools using generic phishing topics related to COVID-19, banking, and law enforcement action. Security researchers noted indicators of compromise and some infrastructure overlaps with other campaigns dating back to April 2018, including at least one separately attributed to [APT-C-36](https://attack.mitre.org/groups/G0099), however identified enough differences to report this as separate, unattributed activity.(Citation: ESET Operation Spalax Jan 2021) ", "external_references": [{"external_id": "C0005", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0005"}, {"description": "M. Porolli. (2021, January 21). Operation Spalax: Targeted malware attacks in Colombia. Retrieved September 16, 2022.", "source_name": "ESET Operation Spalax Jan 2021", "url": "https://www.welivesecurity.com/2021/01/12/operation-spalax-targeted-malware-attacks-colombia/"}], "first_seen": "2019-11-01T05:00:00.000Z", "id": "campaign--4c840263-bbda-440d-a22b-674679ddebf1", "last_seen": "2021-01-01T06:00:00.000Z", "modified": "2026-07-31T18:47:21.598Z", "name": "Operation Spalax", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: ESET Operation Spalax Jan 2021)", "x_mitre_last_seen_citation": "(Citation: ESET Operation Spalax Jan 2021)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-16', 0, 171, '09-mitre-attack', 'retrieved', '3292EC58C8DFEBD3371920AE8EEA1304BFCBC8919ABC68CFC7C6CF4133FEC63E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
