VALUES ('doc-09-mitre-attack-p0-19', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["C0018"], "created": "2023-01-17T21:42:34.998Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "\n[C0018](https://attack.mitre.org/campaigns/C0018) was a month-long ransomware intrusion that successfully deployed [AvosLocker](https://attack.mitre.org/software/S1053) onto a compromised network. The unidentified actors gained initial access to the victim network through an exposed server and used a variety of open-source tools prior to executing [AvosLocker](https://attack.mitre.org/software/S1053).(Citation: Costa AvosLocker May 2022)(Citation: Cisco Talos Avos Jun 2022)", "external_references": [{"external_id": "C0018", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0018"}, {"description": "Costa, F. (2022, May 1). RaaS AvosLocker Incident Response Analysis. Retrieved January 11, 2023.", "source_name": "Costa AvosLocker May 2022", "url": "https://www.linkedin.com/pulse/raas-avoslocker-incident-response-analysis-fl%C3%A1vio-costa?trk=articles_directory"}, {"description": "Venere, G. Neal, C. (2022, June 21). Avos ransomware group expands with new attack arsenal. Retrieved January 11, 2023.", "source_name": "Cisco Talos Avos Jun 2022", "url": "https://blog.talosintelligence.com/avoslocker-new-arsenal/"}], "first_seen": "2022-02-01T05:00:00.000Z", "id": "campaign--519ee082-8ab6-439b-988f-a8a3f02c8d30", "last_seen": "2022-03-01T05:00:00.000Z", "modified": "2026-07-31T18:47:22.530Z", "name": "C0018", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Flávio Costa, @Segurança Descomplicada"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: Cisco Talos Avos Jun 2022)", "x_mitre_last_seen_citation": "(Citation: Cisco Talos Avos Jun 2022)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-19', 0, 159, '09-mitre-attack', 'retrieved', 'A6DE7DD14043B252D6753C2E453D77AE8B1BB84CE83B7A6D1BB4C050196052F2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
