VALUES ('doc-09-mitre-attack-p0-20', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Water Curupira Pikabot Distribution"], "created": "2024-07-17T20:23:22.945Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Pikabot](https://attack.mitre.org/software/S1145) was distributed in [Water Curupira Pikabot Distribution](https://attack.mitre.org/campaigns/C0037) throughout 2023 by an entity linked to BlackBasta ransomware deployment via email attachments. This activity followed the take-down of [QakBot](https://attack.mitre.org/software/S0650), with several technical overlaps and similarities with [QakBot](https://attack.mitre.org/software/S0650), indicating a possible connection. The identified activity led to the deployment of tools such as [Cobalt Strike](https://attack.mitre.org/software/S0154), while coinciding with campaigns delivering [DarkGate](https://attack.mitre.org/software/S1111) and [IcedID](https://attack.mitre.org/software/S0483) en route to ransomware deployment.(Citation: TrendMicro Pikabot 2024)", "external_references": [{"external_id": "C0037", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0037"}, {"description": "Shinji Robert Arasawa, Joshua Aquino, Charles Steven Derion, Juhn Emmanuel Atanque, Francisrey Joshua Castillo, John Carlo Marquez, Henry Salcedo, John Rainier Navato, Arianne Dela Cruz, Raymart Yambot & Ian Kenefick. (2024, January 9). Black Basta-Affiliated Water Curupira’s Pikabot Spam Campaign. Retrieved July 17, 2024.", "source_name": "TrendMicro Pikabot 2024", "url": "https://www.trendmicro.com/en_us/research/24/a/a-look-into-pikabot-spam-wave-campaign.html"}], "first_seen": "2023-01-01T05:00:00.000Z", "id": "campaign--57541e3b-657e-463a-a4ab-ca08d7ea9965", "last_seen": "2023-12-01T05:00:00.000Z", "modified": "2026-07-31T18:47:22.789Z", "name": "Water Curupira Pikabot Distribution", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Inna Danilevich, U.S. Bank"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: TrendMicro Pikabot 2024)", "x_mitre_last_seen_citation": "(Citation: TrendMicro Pikabot 2024)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-20', 0, 183, '09-mitre-attack', 'retrieved', '7260F70594BB8571B2201BA1BC1389BC62C42B77EC89410887EFFFA8397FA3E1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
