VALUES ('doc-09-mitre-attack-p0-21', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["ShadowRay"], "created": "2024-12-02T19:35:14.473Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ShadowRay](https://attack.mitre.org/campaigns/C0045) was a campaign that began in late 2023 targeting the education, cryptocurrency, biopharma, and other sectors through a vulnerability (CVE-2023-48022) in the Ray AI framework named ShadowRay. According to security researchers [ShadowRay](https://attack.mitre.org/campaigns/C0045) was the first known instance of AI workloads being activley exploited in the wild through vulnerabilities in AI infrastructure. CVE-2023-48022, which allows access to compute resources and sensitive data for exposed instances, remains unpatched and has been disputed by the vendor as they maintain that Ray is not intended for use outside of a strictly controlled network environment.(Citation: Oligo ShadowRay Campaign MAR 2024)", "external_references": [{"external_id": "C0045", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0045"}, {"description": "Lumelsly, A. et al. (2024, March 26). ShadowRay: First Known Attack Campaign Targeting AI Workloads Actively Exploited In The Wild. Retrieved December 2, 2024.", "source_name": "Oligo ShadowRay Campaign MAR 2024", "url": "https://www.oligo.security/blog/shadowray-attack-ai-workloads-actively-exploited-in-the-wild"}], "first_seen": "2023-09-01T04:00:00.000Z", "id": "campaign--57899965-b171-48ed-bbb4-8faffa3d836a", "last_seen": "2024-03-01T05:00:00.000Z", "modified": "2026-07-31T18:47:22.958Z", "name": "ShadowRay", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Shun Miyazaki, NEC Corporation", "Sareena Karapoola, NEC Corporation India", "Pooja Natarajan, NEC Corporation India"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: Oligo ShadowRay Campaign MAR 2024)", "x_mitre_last_seen_citation": "(Citation: Oligo ShadowRay Campaign MAR 2024)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-21', 0, 200, '09-mitre-attack', 'retrieved', '19BB941ED79C3A354EA81F839E78D55948BC1E97146E9F76287ADD8A85D7BE34', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
