VALUES ('doc-09-mitre-attack-p0-22', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["J-magic Campaign"], "created": "2025-02-18T16:00:42.489Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The [J-magic Campaign](https://attack.mitre.org/campaigns/C0050) was active from mid-2023 to at least mid-2024 and featured the use of the [J-magic](https://attack.mitre.org/software/S1203) backdoor, a custom cd00r variant tailored for use against Juniper routers. The [J-magic Campaign](https://attack.mitre.org/campaigns/C0050) targeted Junos OS routers serving as VPN gateways primarily in the semiconductor, energy, manufacturing, and IT sectors. (Citation: Lumen J-Magic JAN 2025)", "external_references": [{"external_id": "C0050", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0050"}, {"description": "Black Lotus Labs. (2025, January 23). The J-Magic Show: Magic Packets and Where to find them. Retrieved February 17, 2025.", "source_name": "Lumen J-Magic JAN 2025", "url": "https://blog.lumen.com/the-j-magic-show-magic-packets-and-where-to-find-them/"}], "first_seen": "2023-06-01T04:00:00.000Z", "id": "campaign--58c4fd17-88f5-433a-8242-e9cac31f3c45", "last_seen": "2024-06-01T04:00:00.000Z", "modified": "2026-07-31T18:47:23.400Z", "name": "J-magic Campaign", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: Lumen J-Magic JAN 2025)", "x_mitre_last_seen_citation": "(Citation: Lumen J-Magic JAN 2025)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-22', 0, 138, '09-mitre-attack', 'retrieved', '878B671B0AF28382B2DA7837F079D9811FBA53A17ACF34C4E362D2F4110ED0CA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
