VALUES ('doc-09-mitre-attack-p0-25', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Operation Digital Eye"], "created": "2026-04-19T18:07:20.152Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Operation Digital Eye](https://attack.mitre.org/campaigns/C0061) was conducted in June and July of 2024 by suspected People''s Republic of China (PRC)-nexus threat actors targeting business-to-business IT service providers in Southern Europe. [Operation Digital Eye](https://attack.mitre.org/campaigns/C0061) activity included the use of Visual Studio Code tunnels for command and control (C2) and custom lateral movement capabilities. Overlaps in tooling between Digital Eye and previous China-nexus campaigns, Operation Soft Cell and Operation Tainted Love, indicate the potential use of shared vendors or digital quartermasters.(Citation: sentinelone operationDigitalEye Dec 2024)", "external_references": [{"external_id": "C0061", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0061"}, {"description": "Aleksandar Milenkoski, Luigi Martire. (2024, December 10). Operation Digital Eye | Chinese APT Compromises Critical Digital Infrastructure via Visual Studio Code Tunnels. Retrieved February 27, 2025.", "source_name": "sentinelone operationDigitalEye Dec 2024", "url": "https://www.sentinelone.com/labs/operation-digital-eye-chinese-apt-compromises-critical-digital-infrastructure-via-visual-studio-code-tunnels/"}], "first_seen": "2024-06-01T04:00:00.000Z", "id": "campaign--75ea699b-bff5-4541-b9b7-df4996c9db3c", "last_seen": "2024-07-01T04:00:00.000Z", "modified": "2026-07-31T18:47:23.901Z", "name": "Operation Digital Eye", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: sentinelone operationDigitalEye Dec 2024)", "x_mitre_last_seen_citation": "(Citation: sentinelone operationDigitalEye Dec 2024)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-25', 0, 173, '09-mitre-attack', 'retrieved', '7FE720439CC8915F09C70FB9476967BF7E8D3828127FACECAB1DCF1FEBC1A4A9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
