VALUES ('doc-09-mitre-attack-p0-26', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["C0015"], "created": "2022-09-29T16:42:29.364Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[C0015](https://attack.mitre.org/campaigns/C0015) was a ransomware intrusion during which the unidentified attackers used [Bazar](https://attack.mitre.org/software/S0534), [Cobalt Strike](https://attack.mitre.org/software/S0154), and [Conti](https://attack.mitre.org/software/S0575), along with other tools, over a 5 day period. Security researchers assessed the actors likely used the widely-circulated [Conti](https://attack.mitre.org/software/S0575) ransomware playbook based on the observed pattern of activity and operator errors.(Citation: DFIR Conti Bazar Nov 2021)", "external_references": [{"external_id": "C0015", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0015"}, {"description": "DFIR Report. (2021, November 29). CONTInuing the Bazar Ransomware Story. Retrieved September 29, 2022.", "source_name": "DFIR Conti Bazar Nov 2021", "url": "https://thedfirreport.com/2021/11/29/continuing-the-bazar-ransomware-story/"}], "first_seen": "2021-08-01T05:00:00.000Z", "id": "campaign--78068e68-4124-4243-b6f4-76e4e5be8a06", "last_seen": "2021-08-01T05:00:00.000Z", "modified": "2026-07-31T18:47:24.571Z", "name": "C0015", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Matt Brenton, Zurich Insurance Group"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: DFIR Conti Bazar Nov 2021)", "x_mitre_last_seen_citation": "(Citation: DFIR Conti Bazar Nov 2021)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-26', 0, 137, '09-mitre-attack', 'retrieved', 'BB2C781C9C9FA0F502CBBB761636FE47FF1C58806D0FC424E5BB839DD8C35072', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
