VALUES ('doc-09-mitre-attack-p0-27', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Operation Ghost"], "created": "2023-03-23T17:51:58.539Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Operation Ghost](https://attack.mitre.org/campaigns/C0023) was an [APT29](https://attack.mitre.org/groups/G0016) campaign starting in 2013 that included operations against ministries of foreign affairs in Europe and the Washington, D.C. embassy of a European Union country. During [Operation Ghost](https://attack.mitre.org/campaigns/C0023), [APT29](https://attack.mitre.org/groups/G0016) used new families of malware and leveraged web services, steganography, and unique C2 infrastructure for each victim.(Citation: ESET Dukes October 2019)\n", "external_references": [{"external_id": "C0023", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0023"}, {"description": "Faou, M., Tartare, M., Dupuy, T. (2019, October). OPERATION GHOST. Retrieved September 23, 2020.", "source_name": "ESET Dukes October 2019", "url": "https://www.welivesecurity.com/wp-content/uploads/2019/10/ESET_Operation_Ghost_Dukes.pdf"}], "first_seen": "2013-09-01T04:00:00.000Z", "id": "campaign--7854c1a0-f06c-4876-98a4-4bbd34751b05", "last_seen": "2019-10-01T04:00:00.000Z", "modified": "2026-07-31T18:47:24.650Z", "name": "Operation Ghost", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: ESET Dukes October 2019)", "x_mitre_last_seen_citation": "(Citation: ESET Dukes October 2019)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-27', 0, 132, '09-mitre-attack', 'retrieved', '8F08B147BAEFFD75298D1A6C9F0DA08D6F7C8BB801FEC38E4471ACB217886AB8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
