VALUES ('doc-09-mitre-attack-p0-28', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Juicy Mix"], "created": "2024-11-25T20:35:10.872Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Juicy Mix](https://attack.mitre.org/campaigns/C0044) was a campaign conducted by [OilRig](https://attack.mitre.org/groups/G0049) throughout 2022 that targeted Israeli organizations with the [Mango](https://attack.mitre.org/software/S1169) backdoor.(Citation: ESET OilRig Campaigns Sep 2023)", "external_references": [{"external_id": "C0044", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0044"}, {"description": "Hromcova, Z. and Burgher, A. (2023, September 21). OilRig’s Outer Space and Juicy Mix: Same ol’ rig, new drill pipes. Retrieved November 21, 2024.", "source_name": "ESET OilRig Campaigns Sep 2023", "url": "https://www.welivesecurity.com/en/eset-research/oilrigs-outer-space-juicy-mix-same-ol-rig-new-drill-pipes/"}], "first_seen": "2022-01-01T05:00:00.000Z", "id": "campaign--7ab2f1a1-26af-4204-ad84-d640fde391da", "last_seen": "2022-12-01T05:00:00.000Z", "modified": "2026-07-31T21:13:47.266Z", "name": "Juicy Mix", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: ESET OilRig Campaigns Sep 2023)", "x_mitre_last_seen_citation": "(Citation: ESET OilRig Campaigns Sep 2023)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-28', 0, 114, '09-mitre-attack', 'retrieved', '6D6DD1951C6517453AD64EC603B385E319B7F42EB43EE290D489F991A292B7FB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
