VALUES ('doc-09-mitre-attack-p0-30', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["C0032"], "created": "2024-03-28T15:22:19.075Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[C0032](https://attack.mitre.org/campaigns/C0032) was an extended campaign suspected to involve the [Triton](https://attack.mitre.org/software/S1009) adversaries with related capabilities and techniques focused on gaining a foothold within IT environments. This campaign occurred in 2019 and was distinctly different from the [Triton Safety Instrumented System Attack](https://attack.mitre.org/campaigns/C0030).(Citation: FireEye TRITON 2019)", "external_references": [{"external_id": "C0032", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0032"}, {"description": "Miller, S, et al. (2019, April 10). TRITON Actor TTP Profile, Custom Attack Tools, Detections, and ATT&CK Mapping. Retrieved April 16, 2019.", "source_name": "FireEye TRITON 2019", "url": "https://www.fireeye.com/blog/threat-research/2019/04/triton-actor-ttp-profile-custom-attack-tools-detections.html"}], "first_seen": "2014-10-01T04:00:00.000Z", "id": "campaign--7ec2826c-0bf0-4b47-acae-fd683431a4ca", "last_seen": "2017-01-01T05:00:00.000Z", "modified": "2026-07-31T18:47:25.472Z", "name": "C0032", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: FireEye TRITON 2019)", "x_mitre_last_seen_citation": "(Citation: FireEye TRITON 2019)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-30', 0, 124, '09-mitre-attack', 'retrieved', '4166CDD27716CEF684A01FC3BB6D1463FCCC5F57224314E5936051A9C754D1EC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
