VALUES ('doc-09-mitre-attack-p0-32', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Pikabot Distribution February 2024"], "created": "2024-07-17T19:42:07.269Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Pikabot](https://attack.mitre.org/software/S1145) was distributed in [Pikabot Distribution February 2024](https://attack.mitre.org/campaigns/C0036) using malicious emails with embedded links leading to malicious ZIP archives requiring user interaction for follow-on infection. The version of [Pikabot](https://attack.mitre.org/software/S1145) distributed featured significant changes over the 2023 variant, including reduced code complexity and simplified obfuscation mechanisms.(Citation: Elastic Pikabot 2024)(Citation: Zscaler Pikabot 2024)", "external_references": [{"external_id": "C0036", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0036"}, {"description": "Daniel Stepanic & Salim Bitam. (2024, February 23). PIKABOT, I choose you!. Retrieved July 12, 2024.", "source_name": "Elastic Pikabot 2024", "url": "https://www.elastic.co/security-labs/pikabot-i-choose-you"}, {"description": "Nikolaos Pantazopoulos. (2024, February 12). The (D)Evolution of Pikabot. Retrieved July 17, 2024.", "source_name": "Zscaler Pikabot 2024", "url": "https://www.zscaler.com/blogs/security-research/d-evolution-pikabot"}], "first_seen": "2024-02-01T05:00:00.000Z", "id": "campaign--81e89fb4-8d07-4d8a-82f4-bf084f9d5d53", "last_seen": "2024-02-01T05:00:00.000Z", "modified": "2026-07-31T18:47:25.913Z", "name": "Pikabot Distribution February 2024", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Inna Danilevich, U.S. Bank"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: Elastic Pikabot 2024)", "x_mitre_last_seen_citation": "(Citation: Elastic Pikabot 2024)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-32', 0, 157, '09-mitre-attack', 'retrieved', '3152343FE446254F8979BB64FAF6EDF762B6547CC94A4670D51E5E26D877FF02', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
