VALUES ('doc-09-mitre-attack-p0-33', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["SPACEHOP Activity"], "created": "2025-03-25T22:32:28.946Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SPACEHOP Activity](https://attack.mitre.org/campaigns/C0052) is conducted through commercially leased Virtual Private Servers (VPS), otherwise known as provisioned Operational Relay Box (ORB) networks. The network leveraged for SPACEHOP Activity enabled China-nexus cyber threat actors – such as [APT5](https://attack.mitre.org/groups/G1023) and [Ke3chang](https://attack.mitre.org/groups/G0004) – to perform network reconnaissance scanning and vulnerability exploitation. SPACEHOP Activity has historically targeted entities in North America, Europe, and the Middle East.(Citation: ORB Mandiant) ", "external_references": [{"external_id": "C0052", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0052"}, {"description": "Raggi, Michael. (2024, May 22). IOC Extinction? China-Nexus Cyber Espionage Actors Use ORB Networks to Raise Cost on Defenders. Retrieved July 8, 2024.", "source_name": "ORB Mandiant", "url": "https://cloud.google.com/blog/topics/threat-intelligence/china-nexus-espionage-orb-networks"}], "first_seen": "2019-01-01T05:00:00.000Z", "id": "campaign--83e1f587-34da-44cc-b65b-a72479cb1616", "last_seen": "2024-05-01T04:00:00.000Z", "modified": "2026-07-31T18:47:26.080Z", "name": "SPACEHOP Activity", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: ORB Mandiant)", "x_mitre_last_seen_citation": "(Citation: ORB Mandiant)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-33', 0, 144, '09-mitre-attack', 'retrieved', '70A4038B7D7085937EDAC9BC984B0173F7A7380062D2C295EDB98FA1B6A64511', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
