VALUES ('doc-09-mitre-attack-p0-35', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["FunnyDream"], "created": "2022-09-20T17:29:09.547Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FunnyDream](https://attack.mitre.org/campaigns/C0007) was a suspected Chinese cyber espionage campaign that targeted government and foreign organizations in Malaysia, the Philippines, Taiwan, Vietnam, and other parts of Southeast Asia. Security researchers linked the [FunnyDream](https://attack.mitre.org/campaigns/C0007) campaign to possible Chinese-speaking threat actors through the use of the [Chinoxy](https://attack.mitre.org/software/S1041) backdoor and noted infrastructure overlap with the TAG-16 threat group.(Citation: Bitdefender FunnyDream Campaign November 2020)(Citation: Kaspersky APT Trends Q1 2020)(Citation: Recorded Future Chinese Activity in Southeast Asia December 2021)", "external_references": [{"external_id": "C0007", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0007"}, {"description": "Global Research and Analysis Team. (2020, April 30). APT trends report Q1 2020. Retrieved September 19, 2022.", "source_name": "Kaspersky APT Trends Q1 2020", "url": "https://securelist.com/apt-trends-report-q1-2020/96826/"}, {"description": "Insikt Group. (2021, December 8). Chinese State-Sponsored Cyber Espionage Activity Supports Expansion of Regional Power and Influence in Southeast Asia. Retrieved September 19, 2022.", "source_name": "Recorded Future Chinese Activity in Southeast Asia December 2021", "url": "https://go.recordedfuture.com/hubfs/reports/cta-2021-1208.pdf"}, {"description": "Vrabie, V. (2020, November). Dissecting a Chinese APT Targeting South Eastern Asian Government Institutions. Retrieved September 19, 2022.", "source_name": "Bitdefender FunnyDream Campaign November 2020", "url": "https://www.bitdefender.com/files/News/CaseStudies/study/379/Bitdefender-Whitepaper-Chinese-APT.pdf"}], "first_seen": "2018-07-01T05:00:00.000Z", "id": "campaign--8d2bc130-89fe-466e-a4f9-6bce6129c2b8", "last_seen": "2020-11-01T04:00:00.000Z", "modified": "2026-07-31T18:47:26.674Z", "name": "FunnyDream", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: Kaspersky APT Trends Q1 2020)", "x_mitre_last_seen_citation": "(Citation: Bitdefender FunnyDream Campaign November 2020)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-35', 0, 218, '09-mitre-attack', 'retrieved', '8C9520596D0C74886B7ACE6D635329A39153E5C147DD906B3229EBA27E1D897C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
