VALUES ('doc-09-mitre-attack-p0-37', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Salesforce Data Exfiltration"], "created": "2025-10-22T14:02:44.965Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The [Salesforce Data Exfiltration](https://attack.mitre.org/campaigns/C0059) campaign began in October 2024 with financially-motivated threat actor UNC6040 using [Spearphishing Voice](https://attack.mitre.org/techniques/T1598/004) (vishing) to compromise corporate Salesforce instances for large-scale data theft and extortion. Following the initial data theft, victim organizations received extortion demands from a separate threat actor, UNC6240, who claimed to be the “ShinyHunters” group. The observed infrastructure and TTPs used during the [Salesforce Data Exfiltration](https://attack.mitre.org/campaigns/C0059) campaign overlap with those used by threat groups with suspected ties to the broader collective known as \"The Com.” These overlaps could plausibly be the result of associated actors operating within the same communities and are not necessarily an indication of a direct operational relationship.(Citation: FBI Salesforce Data Theft SEP 2025)(Citation: Google Salesforce JUN 2025)", "external_references": [{"external_id": "C0059", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0059"}, {"description": "FBI Cyber Division. (2025, September 12). Cyber Criminal Groups UNC6040 and UNC6395 Compromising Salesforce Instances for Data Theft and Extortion. Retrieved October 22, 2025.", "source_name": "FBI Salesforce Data Theft SEP 2025", "url": "https://www.ic3.gov/CSA/2025/250912.pdf"}, {"description": "Google Threat Intelligence Group. (2025, June 4). The Cost of a Call: From Voice Phishing to Data Extortion. Retrieved October 22, 2025.", "source_name": "Google Salesforce JUN 2025", "url": "https://cloud.google.com/blog/topics/threat-intelligence/voice-phishing-data-extortion"}], "first_seen": "2004-10-01T04:00:00.000Z", "id": "campaign--9cea8bec-07c5-422b-84b8-99d3128ce570", "last_seen": "2025-09-01T04:00:00.000Z", "modified": "2026-07-31T20:48:17.935Z", "name": "Salesforce Data Exfiltration", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: FBI Salesforce Data Theft SEP 2025)", "x_mitre_last_seen_citation": "(Citation: FBI Salesforce Data Theft SEP 2025)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-37', 0, 244, '09-mitre-attack', 'retrieved', '8A7005034385BD1A216BD1063288B7CC46BAC232558547BC43A4615367D10B0D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
