VALUES ('doc-09-mitre-attack-p0-38', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["APT28 Nearest Neighbor Campaign"], "created": "2025-02-25T17:11:53.066Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT28 Nearest Neighbor Campaign](https://attack.mitre.org/campaigns/C0051) was conducted by [APT28](https://attack.mitre.org/groups/G0007) from early February 2022 to November 2024 against organizations and individuals with expertise on Ukraine. APT28 primarily leveraged living-off-the-land techniques, while leveraging the zero-day exploitation of CVE-2022-38028. Notably, APT28 leveraged Wi-Fi networks in close proximity to the intended target to gain initial access to the victim environment. By daisy-chaining multiple compromised organizations nearby the intended target, APT28 discovered dual-homed systems (with both a wired and wireless network connection) to enable Wi-Fi and use compromised credentials to connect to the victim network.(Citation: Nearest Neighbor Volexity)", "external_references": [{"external_id": "C0051", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0051"}, {"description": "Koessel, Sean. Adair, Steven. Lancaster, Tom. (2024, November 22). The Nearest Neighbor Attack: How A Russian APT Weaponized Nearby Wi-Fi Networks for Covert Access. Retrieved February 25, 2025.", "source_name": "Nearest Neighbor Volexity", "url": "https://www.volexity.com/blog/2024/11/22/the-nearest-neighbor-attack-how-a-russian-apt-weaponized-nearby-wi-fi-networks-for-covert-access/"}], "first_seen": "2022-02-01T05:00:00.000Z", "id": "campaign--a010610e-22cb-437e-bfde-b78861bdca7a", "last_seen": "2024-11-01T04:00:00.000Z", "modified": "2026-07-31T21:11:45.365Z", "name": "APT28 Nearest Neighbor Campaign", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: Nearest Neighbor Volexity)", "x_mitre_last_seen_citation": "(Citation: Nearest Neighbor Volexity)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-38', 0, 185, '09-mitre-attack', 'retrieved', '30D20FFCF93DDD80AFD04C31C0405F6770B9600667C0E7DC3AEA8625C46E7965', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
