VALUES ('doc-09-mitre-attack-p0-39', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Outer Space"], "created": "2024-11-21T21:08:27.153Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Outer Space](https://attack.mitre.org/campaigns/C0042) was a campaign conducted by [OilRig](https://attack.mitre.org/groups/G0049) throughout 2021 that used the [SampleCheck5000](https://attack.mitre.org/software/S1168) downloader and [Solar](https://attack.mitre.org/software/S1166) backdoor to target Israeli organizations.(Citation: ESET OilRig Campaigns Sep 2023)", "external_references": [{"external_id": "C0042", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0042"}, {"description": "Hromcova, Z. and Burgher, A. (2023, September 21). OilRig’s Outer Space and Juicy Mix: Same ol’ rig, new drill pipes. Retrieved November 21, 2024.", "source_name": "ESET OilRig Campaigns Sep 2023", "url": "https://www.welivesecurity.com/en/eset-research/oilrigs-outer-space-juicy-mix-same-ol-rig-new-drill-pipes/"}], "first_seen": "2021-01-01T05:00:00.000Z", "id": "campaign--a1f5df89-ec82-45ef-b229-4ca6a407dc4f", "last_seen": "2021-12-01T05:00:00.000Z", "modified": "2026-07-31T21:15:08.800Z", "name": "Outer Space", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: ESET OilRig Campaigns Sep 2023)", "x_mitre_last_seen_citation": "(Citation: ESET OilRig Campaigns Sep 2023)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-39', 0, 118, '09-mitre-attack', 'retrieved', '99C1B6593C6C123F31CC22795C48BB6CF91947DF3BD7979EFF006B1580B3B1F5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
