VALUES ('doc-09-mitre-attack-p0-41', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["2025 Poland Wiper Attacks", "2025 Poland Wiper Campaign"], "created": "2026-04-22T19:33:22.532Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[2025 Poland Wiper Attacks](https://attack.mitre.org/campaigns/C0063) is a Russian state-sponsored campaign that conducted destructive cyberattacks against Polish energy infrastructure in December 2025. Targets included more than 30 wind and photovoltaic farms, a combined heat and power (CHP) plant, and a manufacturing sector company. The attacks on the distributed energy resources (DER) disrupted communications between affected facilities and the distribution system operator, but did not impact electricity generation or heat supply. Across the campaign, threat actors deployed two previously undocumented wiper tools, [DynoWiper](https://attack.mitre.org/software/S9038), a Windows-based wiper and [LazyWiper](https://attack.mitre.org/software/S9039), a PowerShell wiper, distributed via malicious Group Policy Objects. At the CHP plant, threat actors had maintained access since at least March 2025, using that foothold to obtain credentials and move laterally before attempting wiper deployment. Some reporting has assessed the activity to be consistent with Russian Federal Security Service (FSB) threat activity group [Dragonfly](https://attack.mitre.org/groups/G0035), also tracked as STATIC TUNDRA, while other reporting attributes the destructive wiper activities to the Russian General Staff Main Intelligence Directorate (GRU) threat activity group ELECTRUM, also tracked as [Sandworm Team](https://attack.mitre.org/groups/G0034).(Citation: CERT Polska)(Citation: Dragos ELECTRUM JAN 2026)(Citation: ESET DynoWiper JAN 2026)(Citation: ESET DynoWiper Update JAN 2026)", "external_references": [{"external_id": "C0063", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0063"}, {"description": "CERT Polska. (2026, January 30). Energy Sector Incident Report – 29 December. Retrieved April 22, 2026.", "source_name": "CERT Polska", "url": "https://cert.pl/uploads/docs/CERT_Polska_Energy_Sector_Incident_Report_2025.pdf"}, {"description": "ESET. (2026, January 30). DynoWiper update: Technical analysis and attribution. Retrieved April 22, 2026.", "source_name": "ESET DynoWiper Update JAN 2026", "url": "https://www.welivesecurity.com/en/eset-research/dynowiper-update-technical-analysis-attribution/"}, {"description": "ESET. (2026, January 30). Russian Sandworm group attacks energy company in Poland with DynoWiper, ESET Research discovers. Retrieved April 22, 2026.", "source_name": "ESET DynoWiper JAN 2026", "url": "https://www.eset.com/us/about/newsroom/research/eset-research-russian-sandwormapt-attacks-energy-company-poland-with-dynowiper/"}, {"description": "https://5943619.hs-sites.com/hubfs/Reports/dragos-2025-poland-attack-report.pdf. (2026, January). ELECTRUM: CYBER ATTACK ON POLAND’S ELECTRIC SYSTEM 2025. Retrieved April 22, 2026.", "source_name": "Dragos ELECTRUM JAN 2026", "url": "https://5943619.hs-sites.com/hubfs/Reports/dragos-2025-poland-attack-report.pdf"}], "first_seen": "2025-03-01T05:00:00.000Z", "id": "campaign--a6aba167-5ada-4812-9da1-912c0e73335d", "last_seen": "2025-12-01T05:00:00.000Z", "modified": "2026-07-31T20:48:19.151Z", "name": "2025 Poland Wiper Attacks", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Dragos Threat Intelligence"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack", "ics-attack"], "x_mitre_first_seen_citation": "(Citation: CERT Polska)(Citation: Dragos ELECTRUM JAN 2026)", "x_mitre_last_seen_citation": "(Citation: CERT Polska)(Citation: Dragos ELECTRUM JAN 2026)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-41', 0, 356, '09-mitre-attack', 'retrieved', '84BCBF45CF2E01411136A3E24A7948CBABD812C27EC8B01ACDB342A481A8865D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
