VALUES ('doc-09-mitre-attack-p0-42', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["C0033"], "created": "2024-03-28T18:00:04.123Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[C0033](https://attack.mitre.org/campaigns/C0033) was a [PROMETHIUM](https://attack.mitre.org/groups/G0056) campaign during which they used [StrongPity](https://attack.mitre.org/software/S0491) to target Android users. [C0033](https://attack.mitre.org/campaigns/C0033) was the first publicly documented mobile campaign for [PROMETHIUM](https://attack.mitre.org/groups/G0056), who previously used Windows-based techniques.(Citation: welivesec_strongpity)", "external_references": [{"external_id": "C0033", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0033"}, {"description": "Baumgartner, K. (2016, October 3). On the StrongPity Waterhole Attacks Targeting Italian and Belgian Encryption Users. Retrieved March 28, 2024.", "source_name": "securelist_strongpity", "url": "https://securelist.com/on-the-strongpity-waterhole-attacks-targeting-italian-and-belgian-encryption-users/76147/"}, {"description": "Stefanko, L. (2023, January 10). StrongPity espionage campaign targeting Android users. Retrieved January 31, 2023.", "source_name": "welivesec_strongpity", "url": "https://www.welivesecurity.com/2023/01/10/strongpity-espionage-campaign-targeting-android-users/"}], "first_seen": "2016-05-01T07:00:00.000Z", "id": "campaign--a82bc5ad-5f95-4c6a-9f25-aaf6f476a3c4", "last_seen": "2023-01-01T08:00:00.000Z", "modified": "2026-07-31T20:48:20.147Z", "name": "C0033", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Hiroki Nagahama, NEC Corporation", "Manikantan Srinivasan, NEC Corporation India", "Pooja Natarajan, NEC Corporation India"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack", "mobile-attack"], "x_mitre_first_seen_citation": "(Citation: securelist_strongpity)", "x_mitre_last_seen_citation": "(Citation: welivesec_strongpity)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-42', 0, 139, '09-mitre-attack', 'retrieved', 'CA611D9DF72A5C3806BC7E79CC2B437A0B0BA412532EBB75D281A15ABFD04F39', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
