VALUES ('doc-09-mitre-attack-p0-44', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["C0010"], "created": "2022-09-21T22:16:42.003Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[C0010](https://attack.mitre.org/campaigns/C0010) was a cyber espionage campaign conducted by UNC3890 that targeted Israeli shipping, government, aviation, energy, and healthcare organizations. Security researcher assess UNC3890 conducts operations in support of Iranian interests, and noted several limited technical connections to Iran, including PDB strings and Farsi language artifacts. [C0010](https://attack.mitre.org/campaigns/C0010) began by at least late 2020, and was still ongoing as of mid-2022.(Citation: Mandiant UNC3890 Aug 2022)", "external_references": [{"external_id": "C0010", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0010"}, {"description": "Mandiant Israel Research Team. (2022, August 17). Suspected Iranian Actor Targeting Israeli Shipping, Healthcare, Government and Energy Sectors. Retrieved September 21, 2022.", "source_name": "Mandiant UNC3890 Aug 2022", "url": "https://www.mandiant.com/resources/blog/suspected-iranian-actor-targeting-israeli-shipping"}], "first_seen": "2020-12-01T07:00:00.000Z", "id": "campaign--ab747e62-1bcb-479f-a26b-1cd39d413d81", "last_seen": "2022-08-01T06:00:00.000Z", "modified": "2026-07-31T18:47:29.344Z", "name": "C0010", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: Mandiant UNC3890 Aug 2022)", "x_mitre_last_seen_citation": "(Citation: Mandiant UNC3890 Aug 2022)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-44', 0, 147, '09-mitre-attack', 'retrieved', 'FD9D32137BEA282ACF0654F18BCB0A225FE1C0BE4648870062BE103E3E11B82C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
