VALUES ('doc-09-mitre-attack-p0-45', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["APT41 DUST"], "created": "2024-09-16T09:05:01.249Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT41 DUST](https://attack.mitre.org/campaigns/C0040) was conducted by [APT41](https://attack.mitre.org/groups/G0096) from 2023 to July 2024 against entities in Europe, Asia, and the Middle East. [APT41 DUST](https://attack.mitre.org/campaigns/C0040) targeted sectors such as shipping, logistics, and media for information gathering purposes. [APT41](https://attack.mitre.org/groups/G0096) used previously-observed malware such as [DUSTPAN](https://attack.mitre.org/software/S1158) as well as newly observed tools such as [DUSTTRAP](https://attack.mitre.org/software/S1159) in [APT41 DUST](https://attack.mitre.org/campaigns/C0040).(Citation: Google Cloud APT41 2024)", "external_references": [{"external_id": "C0040", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0040"}, {"description": "Mike Stokkel et al. (2024, July 18). APT41 Has Arisen From the DUST. Retrieved September 16, 2024.", "source_name": "Google Cloud APT41 2024", "url": "https://cloud.google.com/blog/topics/threat-intelligence/apt41-arisen-from-dust"}], "first_seen": "2023-01-31T23:00:00.000Z", "id": "campaign--add4d9de-1256-4166-83b8-57087288dced", "last_seen": "2024-06-30T22:00:00.000Z", "modified": "2026-07-31T18:47:29.732Z", "name": "APT41 DUST", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: Google Cloud APT41 2024)", "x_mitre_last_seen_citation": "(Citation: Google Cloud APT41 2024)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-45', 0, 138, '09-mitre-attack', 'retrieved', 'E162C17D8BE95836DC2907773BA49603600AB0E0BC2486E6A297488E43E661B2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
