VALUES ('doc-09-mitre-attack-p0-46', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Night Dragon"], "created": "2022-09-08T13:31:37.391Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Night Dragon](https://attack.mitre.org/campaigns/C0002) was a cyber espionage campaign that targeted oil, energy, and petrochemical companies, along with individuals and executives in Kazakhstan, Taiwan, Greece, and the United States. The unidentified threat actors searched for information related to oil and gas field production systems, financials, and collected data from SCADA systems. Based on the observed techniques, tools, and network activities, security researchers assessed the campaign involved a threat group based in China.(Citation: McAfee Night Dragon)", "external_references": [{"external_id": "C0002", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0002"}, {"description": "McAfee® Foundstone® Professional Services and McAfee Labs™. (2011, February 10). Global Energy Cyberattacks: “Night Dragon”. Retrieved February 19, 2018.", "source_name": "McAfee Night Dragon", "url": "https://scadahacker.com/library/Documents/Cyber_Events/McAfee%20-%20Night%20Dragon%20-%20Global%20Energy%20Cyberattacks.pdf"}], "first_seen": "2009-11-01T04:00:00.000Z", "id": "campaign--ae407e32-87e0-4d92-8705-3ae25d504d8a", "last_seen": "2011-02-01T05:00:00.000Z", "modified": "2026-07-31T18:47:29.891Z", "name": "Night Dragon", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: McAfee Night Dragon)", "x_mitre_last_seen_citation": "(Citation: McAfee Night Dragon)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-46', 0, 153, '09-mitre-attack', 'retrieved', '24391408ED46200F10CA37B5E0C6165E493791AB46794C93D17796062675895B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
