VALUES ('doc-09-mitre-attack-p0-47', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Versa Director Zero Day Exploitation"], "created": "2024-08-27T18:34:35.056Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Versa Director Zero Day Exploitation](https://attack.mitre.org/campaigns/C0039) was conducted by [Volt Typhoon](https://attack.mitre.org/groups/G1017) from early June through August 2024 as zero-day exploitation of Versa Director servers controlling software-defined wide area network (SD-WAN) applications. Since tracked as CVE-2024-39717, exploitation focused on credential capture from compromised Versa Director servers at managed service providers (MSPs) and internet service providers (ISPs) to enable follow-on access to service provider clients. [Versa Director Zero Day Exploitation](https://attack.mitre.org/campaigns/C0039) was followed by the delivery of the [VersaMem](https://attack.mitre.org/software/S1154) web shell for both credential theft and follow-on code execution.(Citation: Lumen Versa 2024)", "external_references": [{"external_id": "C0039", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0039"}, {"description": "Black Lotus Labs. (2024, August 27). Taking The Crossroads: The Versa Director Zero-Day Exploitaiton. Retrieved August 27, 2024.", "source_name": "Lumen Versa 2024", "url": "https://blog.lumen.com/taking-the-crossroads-the-versa-director-zero-day-exploitation/"}], "first_seen": "2024-06-01T06:00:00.000Z", "id": "campaign--af0ec65a-caa9-40ef-b1c7-21b71fbf3a10", "last_seen": "2024-08-01T06:00:00.000Z", "modified": "2026-07-31T18:47:29.960Z", "name": "Versa Director Zero Day Exploitation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: Lumen Versa 2024)", "x_mitre_last_seen_citation": "(Citation: Lumen Versa 2024)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-47', 0, 173, '09-mitre-attack', 'retrieved', '5A19072D8C8D835C87060AF304477E5ADE7B22E0534B102CC529C5F564AC18BE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
