VALUES ('doc-09-mitre-attack-p0-48', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Operation Wocao"], "created": "2022-09-27T14:15:23.984Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Operation Wocao](https://attack.mitre.org/campaigns/C0014) was a cyber espionage campaign that targeted organizations around the world, including in Brazil, China, France, Germany, Italy, Mexico, Portugal, Spain, the United Kingdom, and the United States. The suspected China-based actors compromised government organizations and managed service providers, as well as aviation, construction, energy, finance, health care, insurance, offshore engineering, software development, and transportation companies.(Citation: FoxIT Wocao December 2019)\n\nSecurity researchers assessed the [Operation Wocao](https://attack.mitre.org/campaigns/C0014) actors used similar TTPs and tools as APT20, suggesting a possible overlap. [Operation Wocao](https://attack.mitre.org/campaigns/C0014) was named after an observed command line entry by one of the threat actors, possibly out of frustration from losing webshell access.(Citation: FoxIT Wocao December 2019)", "external_references": [{"external_id": "C0014", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0014"}, {"description": "Dantzig, M. v., Schamper, E. (2019, December 19). Operation Wocao: Shining a light on one of China’s hidden hacking groups. Retrieved October 8, 2020.", "source_name": "FoxIT Wocao December 2019", "url": "https://www.fox-it.com/media/kadlze5c/201912_report_operation_wocao.pdf"}], "first_seen": "2017-12-01T05:00:00.000Z", "id": "campaign--b03d5112-e23a-4ac8-add0-be7502d24eff", "last_seen": "2019-12-01T05:00:00.000Z", "modified": "2026-07-31T18:47:30.910Z", "name": "Operation Wocao", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Erik Schamper, @Schamperr, Fox-IT", "Maarten van Dantzig, @MaartenVDantzig, Fox-IT"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: FoxIT Wocao December 2019)", "x_mitre_last_seen_citation": "(Citation: FoxIT Wocao December 2019)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-48', 0, 205, '09-mitre-attack', 'retrieved', '1BADB15B26D55F10EE6972E9C15BC07A92EBC195FC5042591C1EE7453054C6C1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
