VALUES ('doc-09-mitre-attack-p0-49', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["C0011"], "created": "2022-09-22T17:12:02.893Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[C0011](https://attack.mitre.org/campaigns/C0011) was a suspected cyber espionage campaign conducted by [Transparent Tribe](https://attack.mitre.org/groups/G0134) that targeted students at universities and colleges in India. Security researchers noted this campaign against students was a significant shift from [Transparent Tribe](https://attack.mitre.org/groups/G0134)''s historic targeting Indian government, military, and think tank personnel, and assessed it was still ongoing as of July 2022.(Citation: Cisco Talos Transparent Tribe Education Campaign July 2022) ", "external_references": [{"external_id": "C0011", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0011"}, {"description": "N. Baisini. (2022, July 13). Transparent Tribe begins targeting education sector in latest campaign. Retrieved September 22, 2022.", "source_name": "Cisco Talos Transparent Tribe Education Campaign July 2022", "url": "https://blog.talosintelligence.com/2022/07/transparent-tribe-targets-education.html"}], "first_seen": "2021-12-01T06:00:00.000Z", "id": "campaign--b4e5a4a9-f3be-4631-ba8f-da6ebb067fac", "last_seen": "2022-07-01T05:00:00.000Z", "modified": "2026-07-31T18:47:30.973Z", "name": "C0011", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: Cisco Talos Transparent Tribe Education Campaign July 2022)", "x_mitre_last_seen_citation": "(Citation: Cisco Talos Transparent Tribe Education Campaign July 2022)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-49', 0, 154, '09-mitre-attack', 'retrieved', 'F13BBE46E98C762A5288FED43D5291A736331AB9FE2CE6BD05A28D4030A7D776', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
