VALUES ('doc-09-mitre-attack-p0-50', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Leviathan Australian Intrusions"], "created": "2025-02-03T19:41:59.392Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Leviathan Australian Intrusions](https://attack.mitre.org/campaigns/C0049) consisted of at least two long-term intrusions against victims in Australia by [Leviathan](https://attack.mitre.org/groups/G0065), relying on similar tradecraft such as external service exploitation followed by extensive credential capture and re-use to enable privilege escalation and lateral movement. [Leviathan Australian Intrusions](https://attack.mitre.org/campaigns/C0049) were focused on exfiltrating sensitive data including valid credentials for the victim organizations.(Citation: CISA Leviathan 2024)", "external_references": [{"external_id": "C0049", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0049"}, {"description": "CISA et al. (2024, July 8). People’s Republic of China (PRC) Ministry of State Security APT40 Tradecraft in Action. Retrieved February 3, 2025.", "source_name": "CISA Leviathan 2024", "url": "https://www.cisa.gov/news-events/cybersecurity-advisories/aa24-190a"}], "first_seen": "2022-04-01T06:00:00.000Z", "id": "campaign--b66bc597-399c-4e4d-828a-1ed4a7f1fb15", "last_seen": "2022-09-01T06:00:00.000Z", "modified": "2026-07-31T18:47:32.005Z", "name": "Leviathan Australian Intrusions", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: CISA Leviathan 2024)", "x_mitre_last_seen_citation": "(Citation: CISA Leviathan 2024)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-50', 0, 144, '09-mitre-attack', 'retrieved', 'AA7DDBF8EA674677F8617C9737A1036653DDAB723188ACBB0814E16057F31889', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
