VALUES ('doc-09-mitre-attack-p0-52', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["C0026"], "created": "2023-05-15T19:17:48.880Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[C0026](https://attack.mitre.org/campaigns/C0026) was a campaign identified in September 2022 that included the selective distribution of [KOPILUWAK](https://attack.mitre.org/software/S1075) and [QUIETCANARY](https://attack.mitre.org/software/S1076) malware to previous [ANDROMEDA](https://attack.mitre.org/software/S1074) malware victims in Ukraine through re-registered [ANDROMEDA](https://attack.mitre.org/software/S1074) C2 domains. Several tools and tactics used during [C0026](https://attack.mitre.org/campaigns/C0026) were consistent with historic [Turla](https://attack.mitre.org/groups/G0010) operations.(Citation: Mandiant Suspected Turla Campaign February 2023)", "external_references": [{"external_id": "C0026", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0026"}, {"description": "Hawley, S. et al. (2023, February 2). Turla: A Galaxy of Opportunity. Retrieved May 15, 2023.", "source_name": "Mandiant Suspected Turla Campaign February 2023", "url": "https://www.mandiant.com/resources/blog/turla-galaxy-opportunity"}], "first_seen": "2022-08-01T05:00:00.000Z", "id": "campaign--c89fa3ff-4773-4daf-8aec-d8f43f10116e", "last_seen": "2022-09-01T04:00:00.000Z", "modified": "2026-07-31T18:47:32.005Z", "name": "C0026", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Yoshihiro Kori, NEC Corporation", "Manikantan Srinivasan, NEC Corporation India", "Pooja Natarajan, NEC Corporation India"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: Mandiant Suspected Turla Campaign February 2023)", "x_mitre_last_seen_citation": "(Citation: Mandiant Suspected Turla Campaign February 2023)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-52', 0, 148, '09-mitre-attack', 'retrieved', '4F7DCC0B4F7C531E4B89C510A9BA88A12C97810A74AE0B0E63ED980C2F3AED33', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
