VALUES ('doc-09-mitre-attack-p0-53', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["C0027"], "created": "2023-06-30T19:28:30.616Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[C0027](https://attack.mitre.org/campaigns/C0027) was a financially-motivated campaign linked to [Scattered Spider](https://attack.mitre.org/groups/G1015) that targeted telecommunications and business process outsourcing (BPO) companies from at least June through December of 2022. During [C0027](https://attack.mitre.org/campaigns/C0027) [Scattered Spider](https://attack.mitre.org/groups/G1015) used various forms of social engineering, performed SIM swapping, and attempted to leverage access from victim environments to mobile carrier networks.(Citation: Crowdstrike TELCO BPO Campaign December 2022)\n", "external_references": [{"external_id": "C0027", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0027"}, {"description": "Parisi, T. (2022, December 2). Not a SIMulation: CrowdStrike Investigations Reveal Intrusion Campaign Targeting Telco and BPO Companies. Retrieved June 30, 2023.", "source_name": "Crowdstrike TELCO BPO Campaign December 2022", "url": "https://www.crowdstrike.com/blog/analysis-of-intrusion-campaign-targeting-telecom-and-bpo-companies/"}], "first_seen": "2022-06-01T04:00:00.000Z", "id": "campaign--df74f7ad-b10d-431c-9f1d-a2bc18dadefa", "last_seen": "2022-12-01T05:00:00.000Z", "modified": "2026-07-31T18:47:32.962Z", "name": "C0027", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: Crowdstrike TELCO BPO Campaign December 2022)", "x_mitre_last_seen_citation": "(Citation: Crowdstrike TELCO BPO Campaign December 2022)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-53', 0, 147, '09-mitre-attack', 'retrieved', '22FED84B7E8526170820D1B0870204E447F326D3D6DAFE57D9C852502C985E6C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
