VALUES ('doc-09-mitre-attack-p0-54', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["2022 Ukraine Electric Power Attack"], "created": "2024-03-27T19:43:25.703Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The [2022 Ukraine Electric Power Attack](https://attack.mitre.org/campaigns/C0034) was a [Sandworm Team](https://attack.mitre.org/groups/G0034) campaign that used a combination of GOGETTER, Neo-REGEORG, [CaddyWiper](https://attack.mitre.org/software/S0693), and living of the land (LotL) techniques to gain access to a Ukrainian electric utility to send unauthorized commands from their SCADA system.(Citation: Mandiant-Sandworm-Ukraine-2022)(Citation: Dragos-Sandworm-Ukraine-2022) ", "external_references": [{"external_id": "C0034", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0034"}, {"description": "Dragos, Inc.. (2023, December 11). ELECTRUM Targeted Ukrainian Electric Entity Using Custom Tools and CaddyWiper Malware, October 2022. Retrieved March 28, 2024.", "source_name": "Dragos-Sandworm-Ukraine-2022", "url": "https://www.dragos.com/blog/new-details-electrum-ukraine-electric-sector-compromise-2022/"}, {"description": "Ken Proska, John Wolfram, Jared Wilson, Dan Black, Keith Lunden, Daniel Kapellmann Zafra, Nathan Brubaker, Tyler Mclellan, Chris Sistrunk. (2023, November 9). Sandworm Disrupts Power in Ukraine Using a Novel Attack Against Operational Technology. Retrieved March 28, 2024.", "source_name": "Mandiant-Sandworm-Ukraine-2022", "url": "https://www.mandiant.com/resources/blog/sandworm-disrupts-power-ukraine-operational-technology"}], "first_seen": "2022-06-01T04:00:00.000Z", "id": "campaign--df8eb785-70f8-4300-b444-277ba849083d", "last_seen": "2022-10-01T04:00:00.000Z", "modified": "2026-07-31T21:11:04.731Z", "name": "2022 Ukraine Electric Power Attack", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack", "ics-attack"], "x_mitre_first_seen_citation": "(Citation: Mandiant-Sandworm-Ukraine-2022)", "x_mitre_last_seen_citation": "(Citation: Mandiant-Sandworm-Ukraine-2022)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-54', 0, 172, '09-mitre-attack', 'retrieved', '02694B7D81EAE893323558552EB9EF613BB90D8604A3025BBD859E5291EF3821', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
