VALUES ('doc-09-mitre-attack-p0-56', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["FLORAHOX Activity"], "created": "2025-03-25T22:45:13.091Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FLORAHOX Activity](https://attack.mitre.org/campaigns/C0053) is conducted using a hybrid operational relay box (ORB) network, which combines two types of infrastructure: compromised devices and leased Virtual Private Servers (VPS). The compromised devices include end-of-life routers and IoT devices, while VPS space is commercially leased and managed by ORB network administrators. This hybrid ORB network allows adversaries to proxy and obscure malicious traffic, making the source of the traffic more difficult to trace.\n\nThe FLORAHOX ORB network has been leveraged by multiple cyber threat actors, including China-nexus actors like [ZIRCONIUM](https://attack.mitre.org/groups/G0128). These adversaries conduct espionage campaigns through [FLORAHOX Activity](https://attack.mitre.org/campaigns/C0053), relying on the ORB network''s ability to funnel traffic through [Tor](https://attack.mitre.org/software/S0183) nodes, provisioned VPS servers, and compromised routers to obfuscate malicious traffic.(Citation: ORB Mandiant)", "external_references": [{"external_id": "C0053", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0053"}, {"description": "Raggi, Michael. (2024, May 22). IOC Extinction? China-Nexus Cyber Espionage Actors Use ORB Networks to Raise Cost on Defenders. Retrieved July 8, 2024.", "source_name": "ORB Mandiant", "url": "https://cloud.google.com/blog/topics/threat-intelligence/china-nexus-espionage-orb-networks"}], "first_seen": "2019-01-01T05:00:00.000Z", "id": "campaign--f494272a-c110-4574-be90-42c4957f7ae7", "last_seen": "2024-05-01T04:00:00.000Z", "modified": "2026-07-31T18:47:33.465Z", "name": "FLORAHOX Activity", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: ORB Mandiant)", "x_mitre_last_seen_citation": "(Citation: ORB Mandiant)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-56', 0, 198, '09-mitre-attack', 'retrieved', '8A949FC2E2E5BFD5FDF17843CC451BDC0F150B4931218C6448DE2AC4EFDCC48A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
