VALUES ('doc-09-mitre-attack-p0-57', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["CostaRicto"], "created": "2022-09-15T17:25:38.020Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CostaRicto](https://attack.mitre.org/campaigns/C0004) was a suspected hacker-for-hire cyber espionage campaign that targeted multiple industries worldwide, with a large number being financial institutions. [CostaRicto](https://attack.mitre.org/campaigns/C0004) actors targeted organizations in Europe, the Americas, Asia, Australia, and Africa, with a large concentration in South Asia (especially India, Bangladesh, and Singapore), using custom malware, open source tools, and a complex network of proxies and SSH tunnels.(Citation: BlackBerry CostaRicto November 2020)", "external_references": [{"external_id": "C0004", "source_name": "mitre-attack", "url": "https://attack.mitre.org/campaigns/C0004"}, {"description": "The BlackBerry Research and Intelligence Team. (2020, November 12). The CostaRicto Campaign: Cyber-Espionage Outsourced. Retrieved May 24, 2021.", "source_name": "BlackBerry CostaRicto November 2020", "url": "https://blogs.blackberry.com/en/2020/11/the-costaricto-campaign-cyber-espionage-outsourced"}], "first_seen": "2019-10-01T04:00:00.000Z", "id": "campaign--f9cc545e-b0ef-4b92-8884-a3a4427609f6", "last_seen": "2020-11-01T04:00:00.000Z", "modified": "2026-07-31T18:47:33.745Z", "name": "CostaRicto", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "campaign", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_first_seen_citation": "(Citation: BlackBerry CostaRicto November 2020)", "x_mitre_last_seen_citation": "(Citation: BlackBerry CostaRicto November 2020)", "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-57', 0, 143, '09-mitre-attack', 'retrieved', '71FB8A1CAC8D624BD0AA2A8807FE4B3F7794738192F28DA1B27514F3CCD836F8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
