INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-58', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure only valid password filters are registered. Filter DLLs must be present in Windows installation directory ( C:\\Windows\\System32\\ by default) of a domain controller and/or local computer with a corresponding entry in HKEY_LOCAL_MACHINE\\SYSTEM\\CurrentControlSet\\Control\\Lsa\\Notification Packages . (Citation: Microsoft Install Password Filter n.d)", "external_references": [{"external_id": "T1174", "source_name": "mitre-attack", "url": "https://attack.mitre.org/mitigations/T1174"}, {"description": "Microsoft. (n.d.). Installing and Registering a Password Filter DLL. Retrieved November 21, 2017.", "source_name": "Microsoft Install Password Filter n.d", "url": "https://msdn.microsoft.com/library/windows/desktop/ms721766.aspx"}], "id": "course-of-action--00d7d21b-69d6-4797-88a2-c86f3fc97651", "modified": "2025-04-18T17:59:39.912Z", "name": "Password Filter DLL Mitigation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "course-of-action", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-58', 0, 100, '09-mitre-attack', 'retrieved', 'D7C9670C8AEC58AD692A09A2590A3CED037CD6A52C6C0F85F7C8FB2CB7C95AE1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
