VALUES ('doc-09-mitre-attack-p0-59', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Prevent files from having a trailing space after the extension.", "external_references": [{"external_id": "T1151", "source_name": "mitre-attack", "url": "https://attack.mitre.org/mitigations/T1151"}], "id": "course-of-action--02f0f92a-0a51-4c94-9bda-6437b9a93f22", "modified": "2025-04-18T17:59:40.127Z", "name": "Space after Filename Mitigation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "course-of-action", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-59', 0, 47, '09-mitre-attack', 'retrieved', '01EAE3AED6EEECB3FAE9D495428E5CE6943DF83870589A46581E30324274CD29', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
