VALUES ('doc-09-mitre-attack-p0-71', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Restrict user''s abilities to create Launch Agents with group policy.", "external_references": [{"external_id": "T1159", "source_name": "mitre-attack", "url": "https://attack.mitre.org/mitigations/T1159"}], "id": "course-of-action--121b2863-5b97-4538-acb3-f8aae070ec13", "modified": "2025-04-18T17:59:42.298Z", "name": "Launch Agent Mitigation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "course-of-action", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-71', 0, 46, '09-mitre-attack', 'retrieved', '7F533CF0EFFDFE7F959B7C6D3F03F0DAE2F4E25308672694716521ADBC786A5F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
