VALUES ('doc-09-mitre-attack-p0-72', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-10T20:46:02.263Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use intrusion detection signatures to block traffic at network boundaries.", "external_references": [{"external_id": "M1031", "source_name": "mitre-attack", "url": "https://attack.mitre.org/mitigations/M1031"}], "id": "course-of-action--12241367-a8b7-49b4-b86e-2236901ba50c", "modified": "2024-10-17T18:54:36.723Z", "name": "Network Intrusion Prevention", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "course-of-action", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-72', 0, 48, '09-mitre-attack', 'retrieved', 'BB0EA5E239D8C87ED1877138CE4451BA03EA696C040FF77FB8DF6D7AC8A711F9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
