VALUES ('doc-09-mitre-attack-p0-73', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Microsoft''s Enhanced Mitigation Experience Toolkit (EMET) Attack Surface Reduction (ASR) feature can be used to block regsvr32.exe from being used to bypass whitelisting. (Citation: Secure Host Baseline EMET)", "external_references": [{"external_id": "T1117", "source_name": "mitre-attack", "url": "https://attack.mitre.org/mitigations/T1117"}, {"description": "National Security Agency. (2016, May 4). Secure Host Baseline EMET. Retrieved June 22, 2016.", "source_name": "Secure Host Baseline EMET", "url": "https://github.com/iadgov/Secure-Host-Baseline/tree/master/EMET"}], "id": "course-of-action--12c13879-b7bd-4bc5-8def-aacec386d432", "modified": "2025-04-18T17:59:42.490Z", "name": "Regsvr32 Mitigation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "course-of-action", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-73', 0, 85, '09-mitre-attack', 'retrieved', '10095DE233E23144E295341FAF738F345BED6AF5828D7E1DAB66480F6557F7B1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
