INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-85', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Other tools should be used to supplement Gatekeeper''s functionality. Additionally, system settings can prevent applications from running that haven''t been downloaded through the Apple Store which can help mitigate some of these issues.", "external_references": [{"external_id": "T1144", "source_name": "mitre-attack", "url": "https://attack.mitre.org/mitigations/T1144"}], "id": "course-of-action--1a7f5bd3-f6ee-4bd7-b949-2f3632ad6158", "modified": "2025-04-18T17:59:44.547Z", "name": "Gatekeeper Bypass Mitigation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "course-of-action", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-85', 0, 69, '09-mitre-attack', 'retrieved', '7936515A212343546933A51C41BD34DCC9F68745ED5C296D0D25C0F4322396A8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
