INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-95', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-06T20:52:59.206Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Restricting web-based content involves enforcing policies and technologies that limit access to potentially malicious websites, unsafe downloads, and unauthorized browser behaviors. This can include URL filtering, download restrictions, script blocking, and extension control to protect against exploitation, phishing, and malware delivery. This mitigation can be implemented through the following measures:\n\nDeploy Web Proxy Filtering:\n\n- Use solutions to filter web traffic based on categories, reputation, and content types.\n- Enforce policies that block unsafe websites or file types at the gateway level.\n\nEnable DNS-Based Filtering:\n\n- Implement tools to restrict access to domains associated with malware or phishing campaigns.\n- Use public DNS filtering services to enhance protection.\n\nEnforce Content Security Policies (CSP):\n\n- Configure CSP headers on internal and external web applications to restrict script execution, iframe embedding, and cross-origin requests.\n\nControl Browser Features:\n\n- Disable unapproved browser features like automatic downloads, developer tools, or unsafe scripting.\n- Enforce policies through tools like Group Policy Management to control browser settings.\n\nMonitor and Alert on Web-Based Threats:\n\n- Use SIEM tools to collect and analyze web proxy logs for signs of anomalous or malicious activity.\n- Configure alerts for access attempts to blocked domains or repeated file download failures.", "external_references": [{"external_id": "M1021", "source_name": "mitre-attack", "url": "https://attack.mitre.org/mitigations/M1021"}], "id": "course-of-action--21da4fd4-27ad-4e9c-b93d-0b9b14d02c96", "modified": "2024-12-24T13:40:41.043Z", "name": "Restrict Web-Based Content", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "course-of-action", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-95', 0, 223, '09-mitre-attack', 'retrieved', '6B43C3508ECD610D0EDDB1CF37EBAAC95F5D831EEECD217A8694E4CE5A12D2E1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-96', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "HTTP Public Key Pinning (HPKP) is one method to mitigate potential man-in-the-middle situations where and adversary uses a mis-issued or fraudulent certificate to intercept encrypted communications by enforcing use of an expected certificate. (Citation: Wikipedia HPKP)\n\nWindows Group Policy can be used to manage root certificates and the Flags value of HKLM\\SOFTWARE\\Policies\\Microsoft\\SystemCertificates\\Root\\ProtectedRoots can be set to 1 to prevent non-administrator users from making further root installations into their own HKCU certificate store. (Citation: SpectorOps Code Signing Dec 2017)", "external_references": [{"external_id": "T1130", "source_name": "mitre-attack", "url": "https://attack.mitre.org/mitigations/T1130"}, {"description": "Wikipedia. (2017, February 28). HTTP Public Key Pinning. Retrieved March 31, 2017.", "source_name": "Wikipedia HPKP", "url": "https://en.wikipedia.org/wiki/HTTP_Public_Key_Pinning"}, {"description": "Graeber, M. (2017, December 22). Code Signing Certificate Cloning Attacks and Defenses. Retrieved April 3, 2018.", "source_name": "SpectorOps Code Signing Dec 2017", "url": "https://posts.specterops.io/code-signing-certificate-cloning-attacks-and-defenses-6f98657fc6ec"}], "id": "course-of-action--23061b40-a7b6-454f-8950-95d5ff80331c", "modified": "2025-04-18T17:59:45.811Z", "name": "Install Root Certificate Mitigation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "course-of-action", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-96', 0, 157, '09-mitre-attack', 'retrieved', '1B918C77E696CBCC49DFF30C6F074BE2A9D49EB97C73E63D7F26420541602AB6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-97', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-11T16:26:52.202Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Prevent users or groups from installing unauthorized or unapproved software to reduce the risk of introducing malicious or vulnerable applications. This can be achieved through allowlists, software restriction policies, endpoint management tools, and least privilege access principles. This mitigation can be implemented through the following measures:\n\nApplication Whitelisting\n\n- Implement Microsoft AppLocker or Windows Defender Application Control (WDAC) to create and enforce allowlists for approved software.\n- Whitelist applications based on file hash, path, or digital signatures.\n\nRestrict User Permissions\n\n- Remove local administrator rights for all non-IT users.\n- Use Role-Based Access Control (RBAC) to restrict installation permissions to privileged accounts only.\n\nSoftware Restriction Policies (SRP)\n\n- Use GPO to configure SRP to deny execution of binaries from directories such as `%AppData%`, `%Temp%`, and external drives.\n- Restrict specific file types (`.exe`, `.bat`, `.msi`, `.js`, `.vbs`) to trusted directories only.\n\nEndpoint Management Solutions\n\n- Deploy tools like Microsoft Intune, SCCM, or Jamf for centralized software management.\n- Maintain a list of approved software, versions, and updates across the enterprise.\n\nMonitor Software Installation Events\n\n- Enable logging of software installation events and monitor Windows Event ID 4688 and Event ID 11707 for software installs.\n- Use SIEM or EDR tools to alert on attempts to install unapproved software.\n\nImplement Software Inventory Management\n\n- Use tools like OSQuery or Wazuh to scan for unauthorized software on endpoints and servers.\n- Conduct regular audits to detect and remove unapproved software.\n\n*Tools for Implementation*\n\nApplication Whitelisting:\n\n- Microsoft AppLocker\n- Windows Defender Application Control (WDAC)\n\nEndpoint Management:\n\n- Microsoft Intune\n- SCCM (System Center Configuration Manager)\n- Jamf Pro (macOS)\n- Puppet or Ansible for automation\n\nSoftware Restriction Policies:\n\n- Group Policy Object (GPO)\n- Microsoft Software Restriction Policies (SRP)\n\nMonitoring and Logging:\n\n- Splunk\n- OSQuery\n- Wazuh (open-source SIEM and XDR)\n- EDRs\n\nInventory Management and Auditing:\n\n- OSQuery\n- Wazuh", "external_references": [{"external_id": "M1033", "source_name": "mitre-attack", "url": "https://attack.mitre.org/mitigations/M1033"}], "id": "course-of-action--23843cff-f7b9-4659-a7b7-713ef347f547", "modified": "2024-12-18T16:17:46.153Z", "name": "Limit Software Installation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "course-of-action", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-97', 0, 310, '09-mitre-attack', 'retrieved', '1B5657ED4D98348232FED2649DF4A8D14E4BC275B02B9D568C01245C4D89F1F0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
