INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-100', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-04-24T17:03:39.689Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Identify critical business and system processes that may be targeted by adversaries and work to secure communications related to those processes against tampering. Encrypt all important data flows to reduce the impact of tailored modifications on data in transit.", "external_references": [{"external_id": "T1493", "source_name": "mitre-attack", "url": "https://attack.mitre.org/mitigations/T1493"}], "id": "course-of-action--245075bc-f992-4d89-af8c-834c53d403f4", "modified": "2025-04-18T17:59:46.349Z", "name": "Transmitted Data Manipulation Mitigation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "course-of-action", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-100', 0, 76, '09-mitre-attack', 'retrieved', '90F58B81E7E1459F4C837157F90547DA348F267F61D26962190AB199EB89D580', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
