VALUES ('doc-09-mitre-attack-p0-111', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Prevent adversary access to privileged accounts necessary to install a hypervisor.", "external_references": [{"external_id": "T1062", "source_name": "mitre-attack", "url": "https://attack.mitre.org/mitigations/T1062"}], "id": "course-of-action--2c3ce852-06a2-40ee-8fe6-086f6402a739", "modified": "2025-04-18T17:59:47.647Z", "name": "Hypervisor Mitigation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "course-of-action", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-111', 0, 46, '09-mitre-attack', 'retrieved', '9A615023B6E9402E4B392CBE32D7EEA25C95F8BDD8E4B3510AFE1130D273A572', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
