VALUES ('doc-09-mitre-attack-p0-112', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Prevent plist files from being modified by users by making them read-only.", "external_references": [{"external_id": "T1150", "source_name": "mitre-attack", "url": "https://attack.mitre.org/mitigations/T1150"}], "id": "course-of-action--2d704e56-e689-4011-b989-bf4e025a8727", "modified": "2025-04-18T17:59:47.826Z", "name": "Plist Modification Mitigation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "course-of-action", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-112', 0, 48, '09-mitre-attack', 'retrieved', '2D23E473F6B002D1078C25A2F1CB8BEB4CEF5F63ECC3FBD5AD897A0E664F5918', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
