INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-122', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure proper process, registry, and file permissions are in place to prevent adversaries from disabling or interfering with security services.", "external_references": [{"external_id": "T1089", "source_name": "mitre-attack", "url": "https://attack.mitre.org/mitigations/T1089"}], "id": "course-of-action--388606d3-f38f-45bf-885d-a9dc9df3c8a8", "modified": "2025-04-18T17:59:50.085Z", "name": "Disabling Security Tools Mitigation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "course-of-action", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-122', 0, 57, '09-mitre-attack', 'retrieved', 'DFFAC8617530D62B200F16E66EE4F5E60C4379E7151E6766397D234A4E1A7E80', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
