INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-144', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Mitigating discovery of password policies is not advised since the information is required to be known by systems and users of a network. Ensure password policies are such that they mitigate brute force attacks yet will not give an adversary an information advantage because the policies are too light. Active Directory is a common way to set and enforce password policies throughout an enterprise network. (Citation: Microsoft Password Complexity)", "external_references": [{"external_id": "T1201", "source_name": "mitre-attack", "url": "https://attack.mitre.org/mitigations/T1201"}, {"description": "Hall, J., Lich, B. (2017, September 9). Password must meet complexity requirements. Retrieved April 5, 2018.", "source_name": "Microsoft Password Complexity", "url": "https://docs.microsoft.com/en-us/windows/security/threat-protection/security-policy-settings/password-must-meet-complexity-requirements"}], "id": "course-of-action--49961e75-b493-423a-9ec7-ac2d6f55384a", "modified": "2025-04-18T17:59:53.715Z", "name": "Password Policy Discovery Mitigation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "course-of-action", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-144', 0, 129, '09-mitre-attack', 'retrieved', '0D95BEF9273B70D9CDB5D19E322639DBEF05278198E948550B3B954697A7B6E1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-145', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-11T16:47:12.859Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Credential Access Protection focuses on implementing measures to prevent adversaries from obtaining credentials, such as passwords, hashes, tokens, or keys, that could be used for unauthorized access. This involves restricting access to credential storage mechanisms, hardening configurations to block credential dumping methods, and using monitoring tools to detect suspicious credential-related activity. This mitigation can be implemented through the following measures:\n\nRestrict Access to Credential Storage:\n\n- Use Case: Prevent adversaries from accessing the SAM (Security Account Manager) database on Windows systems.\n- Implementation: Enforce least privilege principles and restrict administrative access to credential stores such as `C:\\Windows\\System32\\config\\SAM`.\n\nUse Credential Guard:\n\n- Use Case: Isolate LSASS (Local Security Authority Subsystem Service) memory to prevent credential dumping.\n- Implementation: Enable Windows Defender Credential Guard on enterprise endpoints to isolate secrets and protect them from unauthorized access.\n\nMonitor for Credential Dumping Tools:\n\n- Use Case: Detect and block known tools like Mimikatz or Windows Credential Editor.\n- Implementation: Flag suspicious process behavior related to credential dumping.\n\nDisable Cached Credentials:\n\n- Use Case: Prevent adversaries from exploiting cached credentials on endpoints.\n- Implementation: Configure group policy to reduce or eliminate the use of cached credentials (e.g., set Interactive logon: Number of previous logons to cache to 0).\n\nEnable Secure Boot and Memory Protections:\n\n- Use Case: Prevent memory-based attacks used to extract credentials.\n- Implementation: Configure Secure Boot and enforce hardware-based security features like DEP (Data Execution Prevention) and ASLR (Address Space Layout Randomization).", "external_references": [{"external_id": "M1043", "source_name": "mitre-attack", "url": "https://attack.mitre.org/mitigations/M1043"}], "id": "course-of-action--49c06d54-9002-491d-9147-8efb537fbd26", "modified": "2024-12-10T18:55:27.646Z", "name": "Credential Access Protection", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "course-of-action", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-145', 0, 263, '09-mitre-attack', 'retrieved', '105EDA8B7F62ECCCAEACED763DA96A602CF2BFF6636BD38520BE7DD5D9E22842', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
