INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-148', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Making these files immutable and only changeable by certain administrators will limit the ability for adversaries to easily create user level persistence.", "external_references": [{"external_id": "T1156", "source_name": "mitre-attack", "url": "https://attack.mitre.org/mitigations/T1156"}], "id": "course-of-action--4f170666-7edb-4489-85c2-9affa28a72e0", "modified": "2025-04-18T17:59:54.257Z", "name": ".bash_profile and .bashrc Mitigation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "course-of-action", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-148', 0, 59, '09-mitre-attack', 'retrieved', '19233279099972326B9EF8296FEC9D551BE91A096DA2B90812B3837CAADB3D01', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
