INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-163', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-04-08T17:51:41.510Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Implementing best practices for websites such as defending against [Exploit Public-Facing Application](https://attack.mitre.org/techniques/T1190) (Citation: OWASP Top 10 2017). Consider implementing IT disaster recovery plans that contain procedures for taking regular data backups that can be used to restore organizational data. (Ready.gov IT DRP) Ensure backups are stored off system and is protected from common methods adversaries may use to gain access and destroy the backups to prevent recovery.", "external_references": [{"external_id": "T1491", "source_name": "mitre-attack", "url": "https://attack.mitre.org/mitigations/T1491"}, {"description": "OWASP. (2017, April 16). OWASP Top 10 2017 - The Ten Most Critical Web Application Security Risks. Retrieved February 12, 2019.", "source_name": "OWASP Top 10 2017", "url": "https://owasp.org/www-project-top-ten/OWASP_Top_Ten_2017/"}], "id": "course-of-action--5d8507c4-603e-4fe1-8a4a-b8241f58734b", "modified": "2025-04-18T17:59:56.773Z", "name": "Defacement Mitigation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "course-of-action", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-163', 0, 131, '09-mitre-attack', 'retrieved', '3B71407589D5E195B958FA84A75B1E37F33EAF4B74E58B2E8AEF1EC0C6C49465', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
