INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-164', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-11T16:40:14.543Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Restrict the modification of environment variables to authorized users and processes by enforcing strict permissions and policies. This ensures the integrity of environment variables, preventing adversaries from abusing or altering them for malicious purposes. This mitigation can be implemented through the following measures:\n\nRestrict Write Access:\n\n- Use Case: Set file system-level permissions to restrict access to environment variable configuration files (e.g., `.bashrc`, `.bash_profile`, `.zshrc`, `systemd` service files).\n- Implementation: Configure `/etc/environment` or `/etc/profile` on Linux systems to only allow root or administrators to modify the file.\n\nSecure Access Controls:\n\n- Use Case: Limit access to environment variable settings in application deployment tools or CI/CD pipelines to authorized personnel.\n- Implementation: Use role-based access control (RBAC) in tools like Jenkins or GitLab to ensure only specific users can modify environment variables.\n\nRestrict Process Scope:\n\n- Use Case: Configure policies to ensure environment variables are only accessible to the processes they are explicitly intended for.\n- Implementation: Use containerized environments like Docker to isolate environment variables to specific containers and ensure they are not inherited by other processes.\n\nAudit Environment Variable Changes:\n\n- Use Case: Enable logging for changes to critical environment variables.\n- Implementation: Use `auditd` on Linux to monitor changes to files like `/etc/environment` or application-specific environment files.", "external_references": [{"external_id": "M1039", "source_name": "mitre-attack", "url": "https://attack.mitre.org/mitigations/M1039"}], "id": "course-of-action--609191bf-7d06-40e4-b1f8-9e11eb3ff8a6", "modified": "2024-12-11T17:54:05.697Z", "name": "Environment Variable Permissions", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "course-of-action", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-164', 0, 235, '09-mitre-attack', 'retrieved', '76EC9EF589F03E240E2DACEEF04FFBD5F07A5399B8D613156FB8F2061AFCD971', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
