INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-167', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "If it is possible to inspect HTTPS traffic, the captures can be analyzed for connections that appear to be Domain Fronting.\n\nIn order to use domain fronting, attackers will likely need to deploy additional tools to compromised systems. (Citation: FireEye APT29 Domain Fronting With TOR March 2017) (Citation: Mandiant No Easy Breach) It may be possible to detect or prevent the installation of these tools with Host-based solutions.", "external_references": [{"external_id": "T1172", "source_name": "mitre-attack", "url": "https://attack.mitre.org/mitigations/T1172"}, {"description": "Matthew Dunwoody. (2017, March 27). APT29 Domain Fronting With TOR. Retrieved November 20, 2017.", "source_name": "FireEye APT29 Domain Fronting With TOR March 2017", "url": "https://www.fireeye.com/blog/threat-research/2017/03/apt29_domain_frontin.html"}, {"description": "Dunwoody, M. and Carr, N.. (2016, September 27). No Easy Breach DerbyCon 2016. Retrieved October 4, 2016.", "source_name": "Mandiant No Easy Breach", "url": "http://www.slideshare.net/MatthewDunwoody1/no-easy-breach-derby-con-2016"}], "id": "course-of-action--62ae52c9-7197-4f5b-be1d-10d2e1df2c96", "modified": "2025-04-18T17:59:57.301Z", "name": "Domain Fronting Mitigation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "course-of-action", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-167', 0, 154, '09-mitre-attack', 'retrieved', 'E9F0D7DD8B4C7B8DAD6BF85C81832A106D8D87575AA8831CFD2D8E6C45E4ADBA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
