VALUES ('doc-09-mitre-attack-p0-175', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Block SMB traffic from exiting an enterprise network with egress filtering or by blocking TCP ports 139, 445 and UDP port 137. Filter or block WebDAV protocol traffic from exiting the network. If access to external resources over SMB and WebDAV is necessary, then traffic should be tightly limited with whitelisting. (Citation: US-CERT SMB Security) (Citation: US-CERT APT Energy Oct 2017)\n\nFor internal traffic, monitor the workstation-to-workstation unusual (vs. baseline) SMB traffic. For many networks there should not be any, but it depends on how systems on the network are configured and where resources are located.\n\nUse strong passwords to increase the difficulty of credential hashes from being cracked if they are obtained.", "external_references": [{"external_id": "T1187", "source_name": "mitre-attack", "url": "https://attack.mitre.org/mitigations/T1187"}, {"description": "US-CERT. (2017, March 16). SMB Security Best Practices. Retrieved December 21, 2017.", "source_name": "US-CERT SMB Security", "url": "https://www.us-cert.gov/ncas/current-activity/2017/01/16/SMB-Security-Best-Practices"}, {"description": "US-CERT. (2017, October 20). Alert (TA17-293A): Advanced Persistent Threat Activity Targeting Energy and Other Critical Infrastructure Sectors. Retrieved November 2, 2017.", "source_name": "US-CERT APT Energy Oct 2017", "url": "https://www.us-cert.gov/ncas/alerts/TA17-293A"}], "id": "course-of-action--7009ba4d-83d4-4851-9fbb-e09e28497765", "modified": "2025-04-18T17:59:58.570Z", "name": "Forced Authentication Mitigation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "course-of-action", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-175', 0, 196, '09-mitre-attack', 'retrieved', 'A874CA9D04CF81A20BA6685021B53820A48153F1853CF23CEE88CD7045375408', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
