INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-176', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-04-26T19:30:33.607Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Prevent adversary access to privileged accounts or access necessary to perform this technique. Check the integrity of the existing BIOS and device firmware to determine if it is vulnerable to modification. Patch the BIOS and other firmware as necessary to prevent successful use of known vulnerabilities. ", "external_references": [{"external_id": "T1495", "source_name": "mitre-attack", "url": "https://attack.mitre.org/mitigations/T1495"}], "id": "course-of-action--70886857-0f19-4caa-b081-548354a8a994", "modified": "2025-04-18T17:59:58.741Z", "name": "Firmware Corruption Mitigation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "course-of-action", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-176', 0, 83, '09-mitre-attack', 'retrieved', '948CA142A5DA749D8DBF01B3CBEED142BBDD8EA05371858AD1BA39758B002072', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
