INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-193', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Due to potential legitimate uses of trap commands, it''s may be difficult to mitigate use of this technique.", "external_references": [{"external_id": "T1154", "source_name": "mitre-attack", "url": "https://attack.mitre.org/mitigations/T1154"}], "id": "course-of-action--809b79cd-be78-4597-88d1-5496d1d9993a", "modified": "2025-04-18T18:00:00.923Z", "name": "Trap Mitigation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "course-of-action", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-193', 0, 53, '09-mitre-attack', 'retrieved', '7A3358F5ED25F0937F024F4B1A7BA8656D428284AB488DAEAADA34DAAA27B9A8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
