VALUES ('doc-09-mitre-attack-p0-203', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "This technique exploits users'' tendencies to always supply credentials when prompted, which makes it very difficult to mitigate. Use user training as a way to bring awareness and raise suspicion for potentially malicious events (ex: Office documents prompting for credentials).", "external_references": [{"external_id": "T1141", "source_name": "mitre-attack", "url": "https://attack.mitre.org/mitigations/T1141"}], "id": "course-of-action--8a61f6b9-6b7a-4cf2-8e08-f1e26434f6df", "modified": "2025-04-18T18:00:02.276Z", "name": "Input Prompt Mitigation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "course-of-action", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-203', 0, 76, '09-mitre-attack', 'retrieved', '0E4D556293329A71EFE9F8338820AABB0403B009C186095064B89C32F9DCC501', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
