INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-231', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Block .scr files from being executed from non-standard locations. Set Group Policy to force users to have a dedicated screensaver where local changes should not override the settings to prevent changes. Use Group Policy to disable screensavers if they are unnecessary. (Citation: TechNet Screensaver GP)", "external_references": [{"external_id": "T1180", "source_name": "mitre-attack", "url": "https://attack.mitre.org/mitigations/T1180"}, {"description": "Microsoft. (n.d.). Customizing the Desktop. Retrieved December 5, 2017.", "source_name": "TechNet Screensaver GP", "url": "https://technet.microsoft.com/library/cc938799.aspx"}], "id": "course-of-action--9da16278-c6c5-4410-8a6b-9c16ce8005b3", "modified": "2025-04-18T18:00:06.522Z", "name": "Screensaver Mitigation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "course-of-action", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-231', 0, 96, '09-mitre-attack', 'retrieved', '3FA9AF15E0E1D9CE18B5936B81CF7C5C818B53E108E0FEBFD939E990E3183F38', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
