INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-275', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "This type of attack technique cannot be easily mitigated with preventive controls since it is based on the abuse of operating system design features. For example, disabling all BITS functionality will likely have unintended side effects, such as preventing legitimate software patching and updating. Efforts should be focused on preventing adversary tools from running earlier in the chain of activity and on identification of subsequent malicious behavior. (Citation: Mondok Windows PiggyBack BITS May 2007)\n\nModify network and/or host firewall rules, as well as other network controls, to only allow legitimate BITS traffic.\n\nConsider limiting access to the BITS interface to specific users or groups. (Citation: Symantec BITS May 2007)\n\nConsider reducing the default BITS job lifetime in Group Policy or by editing the JobInactivityTimeout and MaxDownloadTime Registry values in HKEY_LOCAL_MACHINE\\Software\\Policies\\Microsoft\\Windows\\BITS . (Citation: Microsoft BITS)", "external_references": [{"external_id": "T1197", "source_name": "mitre-attack", "url": "https://attack.mitre.org/mitigations/T1197"}, {"description": "Mondok, M. (2007, May 11). Malware piggybacks on Windows’ Background Intelligent Transfer Service. Retrieved January 12, 2018.", "source_name": "Mondok Windows PiggyBack BITS May 2007", "url": "https://arstechnica.com/information-technology/2007/05/malware-piggybacks-on-windows-background-intelligent-transfer-service/"}, {"description": "Florio, E. (2007, May 9). Malware Update with Windows Update. Retrieved January 12, 2018.", "source_name": "Symantec BITS May 2007", "url": "https://www.symantec.com/connect/blogs/malware-update-windows-update"}, {"description": "Microsoft. (n.d.). Background Intelligent Transfer Service. Retrieved January 12, 2018.", "source_name": "Microsoft BITS", "url": "https://msdn.microsoft.com/library/windows/desktop/bb968799.aspx"}], "id": "course-of-action--cb825b86-3f3b-4686-ba99-44878f5d3173", "modified": "2025-04-18T18:00:14.361Z", "name": "BITS Jobs Mitigation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "course-of-action", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-275', 0, 232, '09-mitre-attack', 'retrieved', 'F6C6AD4A5F88338794A7D1952C21DB7D656E3DC253096EB0652D96C66BC09C37', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
