VALUES ('doc-09-mitre-attack-p0-318', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Mitigation of some variants of this technique could be achieved through the use of stateful firewalls, depending upon how it is implemented.", "external_references": [{"external_id": "T1205", "source_name": "mitre-attack", "url": "https://attack.mitre.org/mitigations/T1205"}], "id": "course-of-action--f6b7c116-0821-4eb7-9b24-62bd09b3e575", "modified": "2025-04-18T18:00:21.170Z", "name": "Port Knocking Mitigation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "course-of-action", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-318', 0, 58, '09-mitre-attack', 'retrieved', '0E81CDE356CEA35140AB81E38675C1F96CD4E34143261E0ACC3567890F077271', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
