VALUES ('doc-09-mitre-attack-p0-321', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Whitelist programs that are allowed to have this plist tag. All other programs should be considered suspicious.", "external_references": [{"external_id": "T1143", "source_name": "mitre-attack", "url": "https://attack.mitre.org/mitigations/T1143"}], "id": "course-of-action--fae44eea-caa7-42b7-a2e2-0c815ba81b9a", "modified": "2025-04-18T18:00:21.544Z", "name": "Hidden Window Mitigation", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "course-of-action", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-321', 0, 53, '09-mitre-attack', 'retrieved', '01D88E257E9E03DCBC784BA025ABFBA422B0F5C26F5EB33D1AD66343B7E698A3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
