VALUES ('doc-09-mitre-attack-p0-333', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["APT17", "Deputy Dog"], "created": "2017-05-31T21:31:57.307Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT17](https://attack.mitre.org/groups/G0025) is a China-based threat group that has conducted network intrusions against U.S. government entities, the defense industry, law firms, information technology companies, mining companies, and non-government organizations. (Citation: FireEye APT17)", "external_references": [{"external_id": "G0025", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0025"}, {"description": "(Citation: FireEye APT17)", "source_name": "APT17"}, {"description": "(Citation: FireEye APT17)", "source_name": "Deputy Dog"}, {"description": "FireEye Labs/FireEye Threat Intelligence. (2015, May 14). Hiding in Plain Sight: FireEye and Microsoft Expose Obfuscation Tactic. Retrieved November 17, 2024.", "source_name": "FireEye APT17", "url": "https://web.archive.org/web/20240119213200/https://www2.fireeye.com/rs/fireye/images/APT17_Report.pdf"}], "id": "intrusion-set--090242d7-73fc-4738-af68-20162f7a5aae", "modified": "2026-07-31T18:47:36.723Z", "name": "APT17", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-333', 0, 111, '09-mitre-attack', 'retrieved', 'A3C56C18E65B73166B98717936DF933003AE4B9CC713AB15F3497DAED18E18CB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
