VALUES ('doc-09-mitre-attack-p0-334', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["APT3", "Gothic Panda", "Pirpi", "UPS Team", "Buckeye", "Threat Group-0110", "TG-0110"], "created": "2017-05-31T21:31:55.853Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT3](https://attack.mitre.org/groups/G0022) is a China-based threat group that researchers have attributed to China''s Ministry of State Security.(Citation: FireEye Clandestine Wolf)(Citation: Recorded Future APT3 May 2017) This group is responsible for the campaigns known as Operation Clandestine Fox, Operation Clandestine Wolf, and Operation Double Tap.(Citation: FireEye Clandestine Wolf)(Citation: FireEye Operation Double Tap) As of June 2015, the group appears to have shifted from targeting primarily US victims to primarily political organizations in Hong Kong.(Citation: Symantec Buckeye)", "external_references": [{"external_id": "G0022", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0022"}, {"description": "(Citation: FireEye Clandestine Wolf) (Citation: Recorded Future APT3 May 2017) (Citation: Symantec Buckeye)", "source_name": "APT3"}, {"description": "(Citation: FireEye Clandestine Wolf) (Citation: Recorded Future APT3 May 2017) (Citation: Symantec Buckeye)", "source_name": "UPS Team"}, {"description": "(Citation: PWC Pirpi Scanbox)", "source_name": "Pirpi"}, {"description": "(Citation: PWC Pirpi Scanbox) (Citation: Recorded Future APT3 May 2017) (Citation: Symantec Buckeye)", "source_name": "Gothic Panda"}, {"description": "(Citation: Recorded Future APT3 May 2017) (Citation: Symantec Buckeye)", "source_name": "Threat Group-0110"}, {"description": "(Citation: Recorded Future APT3 May 2017) (Citation: Symantec Buckeye)", "source_name": "TG-0110"}, {"description": "(Citation: Symantec Buckeye)", "source_name": "Buckeye"}, {"description": "Eng, E., Caselden, D.. (2015, June 23). Operation Clandestine Wolf – Adobe Flash Zero-Day in APT3 Phishing Campaign. Retrieved January 14, 2016.", "source_name": "FireEye Clandestine Wolf", "url": "https://www.fireeye.com/blog/threat-research/2015/06/operation-clandestine-wolf-adobe-flash-zero-day.html"}, {"description": "Insikt Group (Recorded Future). (2017, May 17). Recorded Future Research Concludes Chinese Ministry of State Security Behind APT3. Retrieved September 16, 2024.", "source_name": "Recorded Future APT3 May 2017", "url": "https://www.recordedfuture.com/research/chinese-mss-behind-apt3"}, {"description": "Lancaster, T. (2015, July 25). A tale of Pirpi, Scanbox & CVE-2015-3113. Retrieved March 30, 2016.", "source_name": "PWC Pirpi Scanbox", "url": "http://pwc.blogs.com/cyber_security_updates/2015/07/pirpi-scanbox.html"}, {"description": "Moran, N., et al. (2014, November 21). Operation Double Tap. Retrieved January 14, 2016.", "source_name": "FireEye Operation Double Tap", "url": "https://www.fireeye.com/blog/threat-research/2014/11/operation_doubletap.html"}, {"description": "Symantec Security Response. (2016, September 6). Buckeye cyberespionage group shifts gaze from US to Hong Kong. Retrieved September 26, 2016.", "source_name": "Symantec Buckeye", "url": "https://web.archive.org/web/20160910124439/http://www.symantec.com/connect/blogs/buckeye-cyberespionage-group-shifts-gaze-us-hong-kong"}], "id": "intrusion-set--0bbdf25b-30ff-4894-a1cd-49260d0dd2d9", "modified": "2026-07-31T18:47:36.902Z", "name": "APT3", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Patrick Sungbahadoor"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.4"}', 'kb-doc-09-mitre-attack-p0-334', 0, 343, '09-mitre-attack', 'retrieved', '8045AD9C2B1C07961F1E99D0157F384801FD917FF42BC91B86243EF1583542CE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
