VALUES ('doc-09-mitre-attack-p0-335', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Mustard Tempest", "DEV-0206", "TA569", "GOLD PRELUDE", "UNC1543"], "created": "2023-12-06T19:00:11.581Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mustard Tempest](https://attack.mitre.org/groups/G1020) is an initial access broker that has operated the [SocGholish](https://attack.mitre.org/software/S1124) distribution network since at least 2017. [Mustard Tempest](https://attack.mitre.org/groups/G1020) has partnered with [Indrik Spider](https://attack.mitre.org/groups/G0119) to provide access for the download of additional malware including LockBit, [WastedLocker](https://attack.mitre.org/software/S0612), and remote access tools.(Citation: Microsoft Ransomware as a Service)(Citation: Microsoft Threat Actor Naming July 2023)(Citation: Secureworks Gold Prelude Profile)(Citation: SocGholish-update)", "external_references": [{"external_id": "G1020", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G1020"}, {"description": "(Citation: Microsoft Threat Actor Naming July 2023)", "source_name": "DEV-0206"}, {"description": "(Citation: Secureworks Gold Prelude Profile)", "source_name": "TA569"}, {"description": "(Citation: Secureworks Gold Prelude Profile)", "source_name": "GOLD PRELUDE"}, {"description": "(Citation: Secureworks Gold Prelude Profile)", "source_name": "UNC1543"}, {"description": "Andrew Northern. (2022, November 22). SocGholish, a very real threat from a very fake update. Retrieved February 13, 2024.", "source_name": "SocGholish-update", "url": "https://www.proofpoint.com/us/blog/threat-insight/part-1-socgholish-very-real-threat-very-fake-update"}, {"description": "Microsoft . (2023, July 12). How Microsoft names threat actors. Retrieved November 17, 2023.", "source_name": "Microsoft Threat Actor Naming July 2023", "url": "https://learn.microsoft.com/en-us/microsoft-365/security/intelligence/microsoft-threat-actor-naming?view=o365-worldwide"}, {"description": "Microsoft. (2022, May 9). Ransomware as a service: Understanding the cybercrime gig economy and how to protect yourself. Retrieved March 10, 2023.", "source_name": "Microsoft Ransomware as a Service", "url": "https://www.microsoft.com/en-us/security/blog/2022/05/09/ransomware-as-a-service-understanding-the-cybercrime-gig-economy-and-how-to-protect-yourself/"}, {"description": "Secureworks. (n.d.). GOLD PRELUDE . Retrieved March 22, 2024.", "source_name": "Secureworks Gold Prelude Profile", "url": "https://www.secureworks.com/research/threat-profiles/gold-prelude"}], "id": "intrusion-set--0d4ac089-ced4-4cc4-a989-174d08e6d030", "modified": "2026-07-31T18:47:37.053Z", "name": "Mustard Tempest", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-335', 0, 233, '09-mitre-attack', 'retrieved', '5ECECC448B56263DA8FDA15CBDCAFDC99B8826B91E20E54BE00F74BCAB02E20B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
