VALUES ('doc-09-mitre-attack-p0-336', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["GCMAN"], "created": "2017-05-31T21:32:05.611Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[GCMAN](https://attack.mitre.org/groups/G0036) is a threat group that focuses on targeting banks for the purpose of transferring money to e-currency services. (Citation: Securelist GCMAN)", "external_references": [{"external_id": "G0036", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0036"}, {"description": "(Citation: Securelist GCMAN)", "source_name": "GCMAN"}, {"description": "Kaspersky Lab''s Global Research & Analysis Team. (2016, February 8). APT-style bank robberies increase with Metel, GCMAN and Carbanak 2.0 attacks. Retrieved April 20, 2016.", "source_name": "Securelist GCMAN", "url": "https://securelist.com/apt-style-bank-robberies-increase-with-metel-gcman-and-carbanak-2-0-attacks/73638/"}], "id": "intrusion-set--0ea72cd5-ca30-46ba-bc04-378f701c658f", "modified": "2026-07-31T18:47:37.385Z", "name": "GCMAN", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-336', 0, 97, '09-mitre-attack', 'retrieved', 'A7BD392F73A72FDF436A51376231C56AA340C85B954B4FE4D5B34E736193631D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
