VALUES ('doc-09-mitre-attack-p0-338', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["EXOTIC LILY"], "created": "2022-08-18T15:25:59.689Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[EXOTIC LILY](https://attack.mitre.org/groups/G1011) is a financially motivated group that has been closely linked with [Wizard Spider](https://attack.mitre.org/groups/G0102) and the deployment of ransomware including [Conti](https://attack.mitre.org/software/S0575) and [Diavol](https://attack.mitre.org/software/S0659). [EXOTIC LILY](https://attack.mitre.org/groups/G1011) may be acting as an initial access broker for other malicious actors, and has targeted a wide range of industries including IT, cybersecurity, and healthcare since at least September 2021.(Citation: Google EXOTIC LILY March 2022)", "external_references": [{"external_id": "G1011", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G1011"}, {"description": "Stolyarov, V. (2022, March 17). Exposing initial access broker with ties to Conti. Retrieved August 18, 2022.", "source_name": "Google EXOTIC LILY March 2022", "url": "https://blog.google/threat-analysis-group/exposing-initial-access-broker-ties-conti/"}], "id": "intrusion-set--129f2f77-1ab2-4c35-bd5e-21260cee92af", "modified": "2026-07-31T18:47:37.990Z", "name": "EXOTIC LILY", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Phill Taylor, BT Security"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-338', 0, 132, '09-mitre-attack', 'retrieved', 'BAD6AEEC3C2AC15173F2EE97DBD1E5B75B96FC3FC588CF4BACBFA3F08525C89E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
