VALUES ('doc-09-mitre-attack-p0-339', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["TA577"], "created": "2024-09-17T16:05:53.084Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TA577](https://attack.mitre.org/groups/G1037) is an initial access broker (IAB) that has distributed [QakBot](https://attack.mitre.org/software/S0650) and [Pikabot](https://attack.mitre.org/software/S1145), and was among the first observed groups distributing [Latrodectus](https://attack.mitre.org/software/S1160) in 2023.(Citation: Latrodectus APR 2024)", "external_references": [{"external_id": "G1037", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G1037"}, {"description": "Proofpoint Threat Research and Team Cymru S2 Threat Research. (2024, April 4). Latrodectus: This Spider Bytes Like Ice . Retrieved May 31, 2024.", "source_name": "Latrodectus APR 2024", "url": "https://www.proofpoint.com/us/blog/threat-insight/latrodectus-spider-bytes-ice"}], "id": "intrusion-set--13ef3485-70d2-4567-b934-0e83c1eafcf1", "modified": "2026-07-31T18:47:37.994Z", "name": "TA577", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-339', 0, 95, '09-mitre-attack', 'retrieved', '659C29E43F3483919741053C83C28CF92440A082BDC2816E2D94DEBAD2168E55', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
