VALUES ('doc-09-mitre-attack-p0-341', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["admin@338"], "created": "2017-05-31T21:31:53.579Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[admin@338](https://attack.mitre.org/groups/G0018) is a China-based cyber threat group. It has previously used newsworthy events as lures to deliver malware and has primarily targeted organizations involved in financial, economic, and trade policy, typically using publicly available RATs such as [PoisonIvy](https://attack.mitre.org/software/S0012), as well as some non-public backdoors. (Citation: FireEye admin@338)", "external_references": [{"external_id": "G0018", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0018"}, {"description": "(Citation: FireEye admin@338)", "source_name": "admin@338"}, {"description": "FireEye Threat Intelligence. (2015, December 1). China-based Cyber Threat Group Uses Dropbox for Malware Communications and Targets Hong Kong Media Outlets. Retrieved December 4, 2015.", "source_name": "FireEye admin@338", "url": "https://www.fireeye.com/blog/threat-research/2015/11/china-based-threat.html"}], "id": "intrusion-set--16ade1aa-0ea1-4bb7-88cc-9079df2ae756", "modified": "2026-07-31T18:47:38.827Z", "name": "admin@338", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Tatsuya Daitoku, Cyber Defense Institute, Inc."], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-341', 0, 129, '09-mitre-attack', 'retrieved', 'A7A4DED6C60D40F90B29EDB7967842224D9773FCA384C347337D8CA43DCD3D82', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
