VALUES ('doc-09-mitre-attack-p0-345', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Salt Typhoon"], "created": "2025-02-24T20:45:14.093Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Salt Typhoon](https://attack.mitre.org/groups/G1045) is a People''s Republic of China (PRC) state-backed actor that has been active since at least 2019 and responsible for numerous compromises of network infrastructure at major U.S. telecommunication and internet service providers (ISP).(Citation: US Dept. of Treasury Salt Typhoon JAN 2025)(Citation: Cisco Salt Typhoon FEB 2025)\n", "external_references": [{"external_id": "G1045", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G1045"}, {"description": "Cisco Talos. (2025, February 20). Weathering the storm: In the midst of a Typhoon. Retrieved February 24, 2025.", "source_name": "Cisco Salt Typhoon FEB 2025", "url": "https://blog.talosintelligence.com/salt-typhoon-analysis/"}, {"description": "US Department of Treasury. (2025, January 17). Treasury Sanctions Company Associated with Salt Typhoon and Hacker Associated with Treasury Compromise. Retrieved February 24, 2025.", "source_name": "US Dept. of Treasury Salt Typhoon JAN 2025", "url": "https://home.treasury.gov/news/press-releases/jy2792"}], "id": "intrusion-set--1c3dcf91-b859-4aae-a09c-ae26dc8b6390", "modified": "2026-07-31T18:47:41.313Z", "name": "Salt Typhoon", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-345', 0, 152, '09-mitre-attack', 'retrieved', '2ACE20AB3644418FCD8190F5D50CFC10A315B1EFA57F546B2C3A0BE059935399', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
