VALUES ('doc-09-mitre-attack-p0-347', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Evilnum"], "created": "2021-01-22T16:46:17.790Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Evilnum](https://attack.mitre.org/groups/G0120) is a financially motivated threat group that has been active since at least 2018.(Citation: ESET EvilNum July 2020)", "external_references": [{"external_id": "G0120", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0120"}, {"description": "(Citation: ESET EvilNum July 2020)", "source_name": "Evilnum"}, {"description": "Porolli, M. (2020, July 9). More evil: A deep look at Evilnum and its toolset. Retrieved January 22, 2021.", "source_name": "ESET EvilNum July 2020", "url": "https://www.welivesecurity.com/2020/07/09/more-evil-deep-look-evilnum-toolset/"}], "id": "intrusion-set--1f0f9a14-11aa-49aa-9174-bcd0eaa979de", "modified": "2026-07-31T18:47:41.686Z", "name": "Evilnum", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-347', 0, 92, '09-mitre-attack', 'retrieved', 'DB83903CB43D718228D9488D16414006EAF8C2474500CDE2B90BE9881BD77094', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
