VALUES ('doc-09-mitre-attack-p0-348', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Gorgon Group"], "created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Gorgon Group](https://attack.mitre.org/groups/G0078) is a threat group consisting of members who are suspected to be Pakistan-based or have other connections to Pakistan. The group has performed a mix of criminal and targeted attacks, including campaigns against government organizations in the United Kingdom, Spain, Russia, and the United States. (Citation: Unit 42 Gorgon Group Aug 2018)", "external_references": [{"external_id": "G0078", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0078"}, {"description": "(Citation: Unit 42 Gorgon Group Aug 2018)", "source_name": "Gorgon Group"}, {"description": "Falcone, R., et al. (2018, August 02). The Gorgon Group: Slithering Between Nation State and Cybercrime. Retrieved August 7, 2018.", "source_name": "Unit 42 Gorgon Group Aug 2018", "url": "https://researchcenter.paloaltonetworks.com/2018/08/unit42-gorgon-group-slithering-nation-state-cybercrime/"}], "id": "intrusion-set--1f21da59-6a13-455b-afd0-d58d0a5a7d27", "modified": "2026-07-31T18:47:42.035Z", "name": "Gorgon Group", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.5"}', 'kb-doc-09-mitre-attack-p0-348', 0, 135, '09-mitre-attack', 'retrieved', '3637CDCEF901C366A3429708F73EBA205B57D8499039E024866F535F278A78F3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
