VALUES ('doc-09-mitre-attack-p0-350', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Night Dragon"], "created": "2017-05-31T21:31:51.643Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Night Dragon](https://attack.mitre.org/groups/G0014) is a campaign name for activity involving a threat group that has conducted activity originating primarily in China. (Citation: McAfee Night Dragon)", "external_references": [{"external_id": "G0014", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0014"}, {"description": "(Citation: McAfee Night Dragon)", "source_name": "Night Dragon"}, {"description": "McAfee® Foundstone® Professional Services and McAfee Labs™. (2011, February 10). Global Energy Cyberattacks: “Night Dragon”. Retrieved February 19, 2018.", "source_name": "McAfee Night Dragon", "url": "https://scadahacker.com/library/Documents/Cyber_Events/McAfee%20-%20Night%20Dragon%20-%20Global%20Energy%20Cyberattacks.pdf"}], "id": "intrusion-set--23b6a0f5-fa95-46f9-a6f3-4549c5e45ec8", "modified": "2026-07-31T18:48:41.283Z", "name": "Night Dragon", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.4"}', 'kb-doc-09-mitre-attack-p0-350', 0, 98, '09-mitre-attack', 'retrieved', 'BB8E743E8D0A6C78D716B6F96F6EA12D38585C9475A46130162416016AA756DA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
