INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-353', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["MuddyWater", "Earth Vetala", "MERCURY", "Static Kitten", "Seedworm", "TEMP.Zagros", "Mango Sandstorm", "TA450", "MuddyKrill"], "created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MuddyWater](https://attack.mitre.org/groups/G0069) is a cyber espionage group assessed to be a subordinate element within Iran''s Ministry of Intelligence and Security (MOIS).(Citation: CYBERCOM Iranian Intel Cyber January 2022) Since at least 2017, [MuddyWater](https://attack.mitre.org/groups/G0069) has targeted a range of government and private organizations across sectors, including telecommunications, local government, finance, defense, and oil and natural gas organizations, in the Middle East (specifically the UAE and Saudi Arabia), Asia, Africa, Europe, and North America. [MuddyWater](https://attack.mitre.org/groups/G0069) has reused domains dating back to October 2025, and has a preference for NameCheap and Hosterdaddy Private Limited (AS136557). In late 2025 and early 2026, [MuddyWater](https://attack.mitre.org/groups/G0069) used commercial satellite internet (i.e., Starlink) for command and control (C2) communication. (Citation: FalconFeeds_Iran_Mar2026)(Citation: Huntio_IranInfra_Mar2026)(Citation: Unit 42 MuddyWater Nov 2017)(Citation: Symantec MuddyWater Dec 2018)(Citation: ClearSky MuddyWater Nov 2018)(Citation: ClearSky MuddyWater June 2019)(Citation: Reaqta MuddyWater November 2017)(Citation: DHS CISA AA22-055A MuddyWater February 2022)(Citation: Talos MuddyWater Jan 2022)(Citation: NaumaanProofpoint_GlobalClickFix_April2025)(Citation: ESET_MuddyWater_Dec2025)(Citation: SymantecCarbonBlack_Seedworm_Mar2026) ", "external_references": [{"external_id": "G0069", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0069"}, {"description": " Cloudflare. (2026, March 3). Introducing the 2026 Cloudflare Threat Report. Retrieved April 18, 2026.", "source_name": "Cloudflare 2026 Threat Report New Threat Actors March 2026", "url": "https://blog.cloudflare.com/2026-threat-report/"}, {"description": "(Citation: Anomali Static Kitten February 2021)", "source_name": "MERCURY"}, {"description": "(Citation: Anomali Static Kitten February 2021)(Citation: Trend Micro Muddy Water March 2021)", "source_name": "Static Kitten"}, {"description": "(Citation: Cloudflare 2026 Threat Report New Threat Actors March 2026)", "source_name": "MuddyKrill"}, {"description": "(Citation: FireEye MuddyWater Mar 2018)(Citation: Anomali Static Kitten February 2021)(Citation: Trend Micro Muddy Water March 2021)", "source_name": "TEMP.Zagros"}, {"description": "(Citation: Microsoft Threat Actor Naming July 2023)", "source_name": "Mango Sandstorm"}, {"description": "(Citation: Proofpoint TA450 Phishing March 2024)", "source_name": "TA450"}, {"description": "(Citation: Symantec MuddyWater Dec 2018)(Citation: Anomali Static Kitten February 2021)(Citation: Trend Micro Muddy Water March 2021)", "source_name": "Seedworm"}, {"description": "(Citation: Trend Micro Muddy Water March 2021)", "source_name": "Earth Vetala"}, {"description": "(Citation: Unit 42 MuddyWater Nov 2017)(Citation: Symantec MuddyWater Dec 2018)", "source_name": "MuddyWater"}, {"description": "ClearSky Cyber Security. (2018, November). MuddyWater Operations in Lebanon and Oman: Using an Israeli compromised domain for a two-stage campaign. Retrieved November 29, 2018.", "source_name": "ClearSky MuddyWater Nov 2018", "url": "https://www.clearskysec.com/wp-content/uploads/2018/11/MuddyWater-Operations-in-Lebanon-and-Oman.pdf"}, {"description": "ClearSky. (2019, June). Iranian APT group ‘MuddyWater’ Adds Exploits to Their Arsenal. Retrieved May 14, 2020.", "source_name": "ClearSky MuddyWater June 2019", "url": "https://www.clearskysec.com/wp-content/uploads/2019/06/Clearsky-Iranian-APT-group-%E2%80%98MuddyWater%E2%80%99-Adds-Exploits-to-Their-Arsenal.pdf"}, {"description": "Cyber National Mission Force. (2022, January 12). Iranian intel cyber suite of malware uses open source tools. Retrieved September 30, 2022.", "source_name": "CYBERCOM Iranian Intel Cyber January 2022", "url": "https://www.cybercom.mil/Media/News/Article/2897570/iranian-intel-cyber-suite-of-malware-uses-open-source-tools/"}, {"description": "ESET Research. (2025, December 2). MuddyWater: Snakes by the riverbank. Retrieved February 17, 2026.", "source_name": "ESET_MuddyWater_Dec2025", "url": "https://www.welivesecurity.com/en/eset-research/muddywater-snakes-riverbank/"}, {"description": "FalconFeeds.io. (2026, March 5). The Digital Redoubt: Iran’s National Information Network and the Asymmetry of Modern Cyber Conflict. Retrieved March 9, 2026.", "source_name": "FalconFeeds_Iran_Mar2026", "url": "https://falconfeeds.io/blogs/the-digital-redoubt-irans-national-information-network-cyber-conflict"}, {"description": "FBI, CISA, CNMF, NCSC-UK. (2022, February 24). Iranian Government-Sponsored Actors Conduct Cyber Operations Against Global Government and Commercial Networks. Retrieved September 27, 2022.", "source_name": "DHS CISA AA22-055A MuddyWater February 2022", "url": "https://www.cisa.gov/uscert/ncas/alerts/aa22-055a"}, {"description": "Hunt.io. (2026, March 4). Iranian APT Infrastructure in Focus: Mapping State-Aligned Clusters During Geopolitical Escalation. Retrieved April 16, 2026.", "source_name": "Huntio_IranInfra_Mar2026", "url": "https://hunt.io/blog/iranian-apt-infrastructure-state-aligned-clusters"}, {"description": "Lancaster, T.. (2017, November 14). Muddying the Water: Targeted Attacks in the Middle East. Retrieved March 15, 2018.", "source_name": "Unit 42 MuddyWater Nov 2017", "url": "https://researchcenter.paloaltonetworks.com/2017/11/unit42-muddying-the-water-targeted-attacks-in-the-middle-east/"}, {"description": "Malhortra, A and Ventura, V. (2022, January 31). Iranian APT MuddyWater targets Turkish users via malicious PDFs, executables. Retrieved June 22, 2022.", "source_name": "Talos MuddyWater Jan 2022", "url": "https://blog.talosintelligence.com/2022/01/iranian-apt-muddywater-targets-turkey.html"}, {"description": "Mele, G. et al. (2021, February 10). Probable Iranian Cyber Actors, Static Kitten, Conducting Cyberespionage Campaign Targeting UAE and Kuwait Government Agencies. Retrieved March 17, 2021.", "source_name": "Anomali Static Kitten February 2021", "url": "https://www.anomali.com/blog/probable-iranian-cyber-actors-static-kitten-conducting-cyberespionage-campaign-targeting-uae-and-kuwait-government-agencies"}, {"description": "Microsoft . (2023, July 12). How Microsoft names threat actors. Retrieved November 17, 2023.", "source_name": "Microsoft Threat Actor Naming July 2023", "url": "https://learn.microsoft.com/en-us/microsoft-365/security/intelligence/microsoft-threat-actor-naming?view=o365-worldwide"}, {"description": "Miller, J. et al. (2024, March 21). Security Brief: TA450 Uses Embedded Links in PDF Attachments in Latest Campaign. Retrieved March 27, 2024.", "source_name": "Proofpoint TA450 Phishing March 2024", "url": "https://www.proofpoint.com/us/blog/threat-insight/security-brief-ta450-uses-embedded-links-pdf-attachments-latest-campaign"}, {"description": "Naumaan, S., et al. (2025, April 17). Around the World in 90 Days: State-Sponsored Actors Try ClickFix . Retrieved January 21, 2026.", "source_name": "NaumaanProofpoint_GlobalClickFix_April2025", "url": "https://www.proofpoint.com/us/blog/threat-insight/around-world-90-days-state-sponsored-actors-try-clickfix"}, {"description": "Peretz, A. and Theck, E. (2021, March 5). Earth Vetala – MuddyWater Continues to Target Organizations in the Middle East. Retrieved March 18, 2021.", "source_name": "Trend Micro Muddy Water March 2021", "url": "https://www.trendmicro.com/en_us/research/21/c/earth-vetala---muddywater-continues-to-target-organizations-in-t.html"}, {"description": "Reaqta. (2017, November 22). A dive into MuddyWater APT targeting Middle-East. Retrieved May 18, 2020.", "source_name": "Reaqta MuddyWater November 2017", "url": "https://reaqta.com/2017/11/muddywater-apt-targeting-middle-east/"}, {"description": "Singh, S. et al.. (2018, March 13). Iranian Threat Group Updates Tactics, Techniques and Procedures in Spear Phishing Campaign. Retrieved April 11, 2018.", "source_name": "FireEye MuddyWater Mar 2018", "url": "https://www.fireeye.com/blog/threat-research/2018/03/iranian-threat-group-updates-ttps-in-spear-phishing-campaign.html"}, {"description": "Symantec DeepSight Adversary Intelligence Team. (2018, December 10). Seedworm: Group Compromises Government Agencies, Oil & Gas, NGOs, Telecoms, and IT Firms. Retrieved December 14, 2018.", "source_name": "Symantec MuddyWater Dec 2018", "url": "https://www.symantec.com/blogs/threat-intelligence/seedworm-espionage-group"}, {"description": "Threat Hunter Team. (2026, March 5). Seedworm: Iranian APT on Networks of U.S. Bank, Airport, Software Company. Retrieved March 5, 2026.", "source_name": "SymantecCarbonBlack_Seedworm_Mar2026", "url": "https://www.security.com/threat-intelligence/iran-cyber-threat-activity-us"}], "id": "intrusion-set--269e8108-68c6-4f99-b911-14b2e765dec2", "modified": "2026-07-31T20:48:29.347Z", "name": "MuddyWater", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Daniyal Naeem, BT Security", "Marco Pedrinazzi, @pedrinazziM", "Ozer Sarilar, @ozersarilar, STM", "Dragos Threat Intelligence"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack", "mobile-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "7.0"}', 'kb-doc-09-mitre-attack-p0-353', 0, 872, '09-mitre-attack', 'retrieved', '1921F87D42F3E446E13D47C9061D228E6E325D480F19AD310BB61A26C67E0B41', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
