VALUES ('doc-09-mitre-attack-p0-362', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Storm-1811"], "created": "2025-03-14T12:48:44.771Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Storm-1811](https://attack.mitre.org/groups/G1046) is a financially-motivated entity linked to [Black Basta](https://attack.mitre.org/software/S1070) ransomware deployment. [Storm-1811](https://attack.mitre.org/groups/G1046) is notable for unique phishing and social engineering mechanisms for initial access, such as overloading victim email inboxes with non-malicious spam to prompt a fake \"help desk\" interaction leading to the deployment of adversary tools and capabilities.(Citation: Microsoft Storm-1811 2024)(Citation: rapid7-email-bombing)(Citation: RedCanary Storm-1811 2024)(Citation: RedCanary June Insights 2024)", "external_references": [{"external_id": "G1046", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G1046"}, {"description": "Microsoft Threat Intelligence. (2024, May 15). Threat actors misusing Quick Assist in social engineering attacks leading to ransomware. Retrieved March 14, 2025.", "source_name": "Microsoft Storm-1811 2024", "url": "https://www.microsoft.com/en-us/security/blog/2024/05/15/threat-actors-misusing-quick-assist-in-social-engineering-attacks-leading-to-ransomware/"}, {"description": "Red Canary Intelligence. (2024, December 2). Storm-1811 exploits RMM tools to drop Black Basta ransomware. Retrieved March 14, 2025.", "source_name": "RedCanary Storm-1811 2024", "url": "https://redcanary.com/blog/threat-intelligence/storm-1811-black-basta/"}, {"description": "The Red Canary Team. (2024, June 20). Intelligence Insights: June 2024. Retrieved March 14, 2025.", "source_name": "RedCanary June Insights 2024", "url": "https://redcanary.com/blog/threat-intelligence/intelligence-insights-june-2024/"}, {"description": "Tyler McGraw, Thomas Elkins, and Evan McCann. (2024, May 10). Ongoing Social Engineering Campaign Linked to Black Basta Ransomware Operators. Retrieved January 31, 2025.", "source_name": "rapid7-email-bombing", "url": "https://www.rapid7.com/blog/post/2024/05/10/ongoing-social-engineering-campaign-linked-to-black-basta-ransomware-operators"}], "id": "intrusion-set--319fd652-edde-46b2-9987-3519493989f5", "modified": "2026-07-31T18:47:47.257Z", "name": "Storm-1811", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Liran Ravich, CardinalOps", "Joe Gumke, U.S. Bank"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-362', 0, 213, '09-mitre-attack', 'retrieved', '8ED26F46274FC5DAB5A00230B267ECE777FE3E188DD0DD0076D0608C2BAB6E5F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
