VALUES ('doc-09-mitre-attack-p0-368', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["APT18", "TG-0416", "Dynamite Panda", "Threat Group-0416"], "created": "2017-05-31T21:31:57.733Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT18](https://attack.mitre.org/groups/G0026) is a threat group that has operated since at least 2009 and has targeted a range of industries, including technology, manufacturing, human rights groups, government, and medical. (Citation: Dell Lateral Movement)", "external_references": [{"external_id": "G0026", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0026"}, {"description": "(Citation: ThreatStream Evasion Analysis)", "source_name": "Threat Group-0416"}, {"description": "(Citation: ThreatStream Evasion Analysis)(Citation: Anomali Evasive Maneuvers July 2015)", "source_name": "APT18"}, {"description": "(Citation: ThreatStream Evasion Analysis)(Citation: Anomali Evasive Maneuvers July 2015)", "source_name": "TG-0416"}, {"description": "(Citation: ThreatStream Evasion Analysis)(Citation: Anomali Evasive Maneuvers July 2015)", "source_name": "Dynamite Panda"}, {"description": "Carvey, H.. (2014, September 2). Where you AT?: Indicators of lateral movement using at.exe on Windows 7 systems. Retrieved January 25, 2016.", "source_name": "Dell Lateral Movement", "url": "http://www.secureworks.com/resources/blog/where-you-at-indicators-of-lateral-movement-using-at-exe-on-windows-7-systems/"}, {"description": "Shelmire, A. (2015, July 06). Evasive Maneuvers by the Wekby group with custom ROP-packing and DNS covert channels. Retrieved November 15, 2018.", "source_name": "Anomali Evasive Maneuvers July 2015", "url": "https://www.anomali.com/blog/evasive-maneuvers-the-wekby-group-attempts-to-evade-analysis-via-custom-rop"}, {"description": "Shelmire, A.. (2015, July 6). Evasive Maneuvers. Retrieved January 22, 2016.", "source_name": "ThreatStream Evasion Analysis", "url": "https://www.threatstream.com/blog/evasive-maneuvers-the-wekby-group-attempts-to-evade-analysis-via-custom-rop"}], "id": "intrusion-set--38fd6a28-3353-4f2b-bb2b-459fecd5c648", "modified": "2026-07-31T18:47:50.082Z", "name": "APT18", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.2"}', 'kb-doc-09-mitre-attack-p0-368', 0, 198, '09-mitre-attack', 'retrieved', '003531057F03B0287F261B39F66186C620C13352393F36EB0BE6DA5F66884FAE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
