INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-369', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Andariel", "Silent Chollima", "PLUTONIUM", "Onyx Sleet"], "created": "2021-09-29T15:10:19.236Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Andariel](https://attack.mitre.org/groups/G0138) is a North Korean state-sponsored threat group that has been active since at least 2009. [Andariel](https://attack.mitre.org/groups/G0138) has primarily focused its operations--which have included destructive attacks--against South Korean government agencies, military organizations, and a variety of domestic companies; they have also conducted cyber financial operations against ATMs, banks, and cryptocurrency exchanges. [Andariel](https://attack.mitre.org/groups/G0138)''s notable activity includes Operation Black Mine, Operation GoldenAxe, and Campaign Rifle.(Citation: FSI Andariel Campaign Rifle July 2017)(Citation: IssueMakersLab Andariel GoldenAxe May 2017)(Citation: AhnLab Andariel Subgroup of Lazarus June 2018)(Citation: TrendMicro New Andariel Tactics July 2018)(Citation: CrowdStrike Silent Chollima Adversary September 2021)\n\n[Andariel](https://attack.mitre.org/groups/G0138) is considered a sub-set of [Lazarus Group](https://attack.mitre.org/groups/G0032), and has been attributed to North Korea''s Reconnaissance General Bureau.(Citation: Treasury North Korean Cyber Groups September 2019)\n\nNorth Korean group definitions are known to have significant overlap, and some security researchers report all North Korean state-sponsored cyber activity under the name [Lazarus Group](https://attack.mitre.org/groups/G0032) instead of tracking clusters or subgroups.", "external_references": [{"external_id": "G0138", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0138"}, {"description": "(Citation: CrowdStrike Silent Chollima Adversary September 2021)", "source_name": "Silent Chollima"}, {"description": "(Citation: FSI Andariel Campaign Rifle July 2017)", "source_name": "Andariel"}, {"description": "(Citation: Microsoft Threat Actor Naming July 2023)", "source_name": "PLUTONIUM"}, {"description": "(Citation: Microsoft Threat Actor Naming July 2023)", "source_name": "Onyx Sleet"}, {"description": "AhnLab. (2018, June 23). Targeted attacks by Andariel Threat Group, a subgroup of the Lazarus. Retrieved September 29, 2021.", "source_name": "AhnLab Andariel Subgroup of Lazarus June 2018", "url": "https://web.archive.org/web/20230213154832/http://download.ahnlab.com/global/brochure/%5BAnalysis%5DAndariel_Group.pdf"}, {"description": "Chen, Joseph. (2018, July 16). New Andariel Reconnaissance Tactics Uncovered. Retrieved September 29, 2021.", "source_name": "TrendMicro New Andariel Tactics July 2018", "url": "https://www.trendmicro.com/en_us/research/18/g/new-andariel-reconnaissance-tactics-hint-at-next-targets.html"}, {"description": "CrowdStrike. (2021, September 29). Silent Chollima Adversary Profile. Retrieved September 29, 2021.", "source_name": "CrowdStrike Silent Chollima Adversary September 2021", "url": "https://adversary.crowdstrike.com/en-US/adversary/silent-chollima/"}, {"description": "FSI. (2017, July 27). Campaign Rifle - Andariel, the Maiden of Anguish. Retrieved September 12, 2024.", "source_name": "FSI Andariel Campaign Rifle July 2017", "url": "https://fsiceat.tistory.com/2"}, {"description": "IssueMakersLab. (2017, May 1). Operation GoldenAxe. Retrieved September 12, 2024.", "source_name": "IssueMakersLab Andariel GoldenAxe May 2017", "url": "http://www.issuemakerslab.com/research3/"}, {"description": "Microsoft . (2023, July 12). How Microsoft names threat actors. Retrieved November 17, 2023.", "source_name": "Microsoft Threat Actor Naming July 2023", "url": "https://learn.microsoft.com/en-us/microsoft-365/security/intelligence/microsoft-threat-actor-naming?view=o365-worldwide"}, {"description": "US Treasury . (2019, September 13). Treasury Sanctions North Korean State-Sponsored Malicious Cyber Groups. Retrieved September 29, 2021.", "source_name": "Treasury North Korean Cyber Groups September 2019", "url": "https://home.treasury.gov/news/press-releases/sm774"}], "id": "intrusion-set--39d6890e-7f23-4474-b8ef-e7b0343c5fc8", "modified": "2026-07-31T18:47:50.220Z", "name": "Andariel", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Kyoung-ju Kwak (S2W)"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-369', 0, 411, '09-mitre-attack', 'retrieved', '6219F3CD5ACE0A220D32B8517A2A9EEF0851559539D367E667D91872847CE9DA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
