VALUES ('doc-09-mitre-attack-p0-373', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["ZIRCONIUM", "APT31", "Violet Typhoon"], "created": "2021-03-24T15:48:17.731Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ZIRCONIUM](https://attack.mitre.org/groups/G0128) is a threat group operating out of China, active since at least 2017, that has targeted individuals associated with the 2020 US presidential election and prominent leaders in the international affairs community.(Citation: Microsoft Targeting Elections September 2020)(Citation: Check Point APT31 February 2021)", "external_references": [{"external_id": "G0128", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0128"}, {"description": "(Citation: Check Point APT31 February 2021)", "source_name": "APT31"}, {"description": "(Citation: Microsoft Threat Actor Naming July 2023)", "source_name": "Violet Typhoon"}, {"description": "Burt, T. (2020, September 10). New cyberattacks targeting U.S. elections. Retrieved March 24, 2021.", "source_name": "Microsoft Targeting Elections September 2020", "url": "https://blogs.microsoft.com/on-the-issues/2020/09/10/cyberattacks-us-elections-trump-biden/"}, {"description": "Itkin, E. and Cohen, I. (2021, February 22). The Story of Jian – How APT31 Stole and Used an Unknown Equation Group 0-Day. Retrieved March 24, 2021.", "source_name": "Check Point APT31 February 2021", "url": "https://research.checkpoint.com/2021/the-story-of-jian/"}, {"description": "Microsoft . (2023, July 12). How Microsoft names threat actors. Retrieved November 17, 2023.", "source_name": "Microsoft Threat Actor Naming July 2023", "url": "https://learn.microsoft.com/en-us/microsoft-365/security/intelligence/microsoft-threat-actor-naming?view=o365-worldwide"}], "id": "intrusion-set--4283ae19-69c7-4347-a35e-b56f08eb660b", "modified": "2026-07-31T18:47:51.321Z", "name": "ZIRCONIUM", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.3"}', 'kb-doc-09-mitre-attack-p0-373', 0, 187, '09-mitre-attack', 'retrieved', '896C34CEE880E0EBFA0AC3654764909C97121404E1F493E8863DE38EF71801A7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
