VALUES ('doc-09-mitre-attack-p0-384', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Windigo"], "created": "2021-02-10T19:57:38.042Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The [Windigo](https://attack.mitre.org/groups/G0124) group has been operating since at least 2011, compromising thousands of Linux and Unix servers using the [Ebury](https://attack.mitre.org/software/S0377) SSH backdoor to create a spam botnet. Despite law enforcement intervention against the creators, [Windigo](https://attack.mitre.org/groups/G0124) operators continued updating [Ebury](https://attack.mitre.org/software/S0377) through 2019.(Citation: ESET Windigo Mar 2014)(Citation: CERN Windigo June 2019)", "external_references": [{"external_id": "G0124", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0124"}, {"description": "Bilodeau, O., Bureau, M., Calvet, J., Dorais-Joncas, A., Léveillé, M., Vanheuverzwijn, B. (2014, March 18). Operation Windigo – the vivisection of a large Linux server‑side credential‑stealing malware campaign. Retrieved February 10, 2021.", "source_name": "ESET Windigo Mar 2014", "url": "https://www.welivesecurity.com/2014/03/18/operation-windigo-the-vivisection-of-a-large-linux-server-side-credential-stealing-malware-campaign/"}, {"description": "CERN. (2019, June 4). 2019/06/04 Advisory: Windigo attacks. Retrieved February 10, 2021.", "source_name": "CERN Windigo June 2019", "url": "https://security.web.cern.ch/advisories/windigo/windigo.shtml"}], "id": "intrusion-set--4e868dad-682d-4897-b8df-2dc98f46c68a", "modified": "2026-07-31T18:47:55.695Z", "name": "Windigo", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-384', 0, 147, '09-mitre-attack', 'retrieved', 'A535008E201623F9F5E9F42F5CD2CBE3CF4F1D5C9321A753FC9B68A6918E3C9A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
