VALUES ('doc-09-mitre-attack-p0-387', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Tropic Trooper", "Pirate Panda", "KeyBoy"], "created": "2019-01-29T20:17:48.717Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Tropic Trooper](https://attack.mitre.org/groups/G0081) is an unaffiliated threat group that has led targeted campaigns against targets in Taiwan, the Philippines, and Hong Kong. [Tropic Trooper](https://attack.mitre.org/groups/G0081) focuses on targeting government, healthcare, transportation, and high-tech industries and has been active since 2011.(Citation: TrendMicro Tropic Trooper Mar 2018)(Citation: Unit 42 Tropic Trooper Nov 2016)(Citation: TrendMicro Tropic Trooper May 2020)", "external_references": [{"external_id": "G0081", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0081"}, {"description": "(Citation: Crowdstrike Pirate Panda April 2020)", "source_name": "Pirate Panda"}, {"description": "(Citation: TrendMicro Tropic Trooper Mar 2018)(Citation: Unit 42 Tropic Trooper Nov 2016)", "source_name": "Tropic Trooper"}, {"description": "(Citation: Unit 42 Tropic Trooper Nov 2016)(Citation: TrendMicro Tropic Trooper Mar 2018)", "source_name": "KeyBoy"}, {"description": "Busselen, M. (2020, April 7). On-demand Webcast: CrowdStrike Experts on COVID-19 Cybersecurity Challenges and Recommendations. Retrieved May 20, 2020.", "source_name": "Crowdstrike Pirate Panda April 2020", "url": "https://www.crowdstrike.com/blog/on-demand-webcast-crowdstrike-experts-on-covid-19-cybersecurity-challenges-and-recommendations/"}, {"description": "Chen, J.. (2020, May 12). Tropic Trooper’s Back: USBferry Attack Targets Air gapped Environments. Retrieved May 20, 2020.", "source_name": "TrendMicro Tropic Trooper May 2020", "url": "https://documents.trendmicro.com/assets/Tech-Brief-Tropic-Trooper-s-Back-USBferry-Attack-Targets-Air-gapped-Environments.pdf"}, {"description": "Horejsi, J., et al. (2018, March 14). Tropic Trooper’s New Strategy. Retrieved November 9, 2018.", "source_name": "TrendMicro Tropic Trooper Mar 2018", "url": "https://blog.trendmicro.com/trendlabs-security-intelligence/tropic-trooper-new-strategy/"}, {"description": "Ray, V. (2016, November 22). Tropic Trooper Targets Taiwanese Government and Fossil Fuel Provider With Poison Ivy. Retrieved November 9, 2018.", "source_name": "Unit 42 Tropic Trooper Nov 2016", "url": "https://researchcenter.paloaltonetworks.com/2016/11/unit42-tropic-trooper-targets-taiwanese-government-and-fossil-fuel-provider-with-poison-ivy/"}], "id": "intrusion-set--56319646-eb6e-41fc-ae53-aadfa7adb924", "modified": "2026-07-31T18:47:56.506Z", "name": "Tropic Trooper", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Edward Millington"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.6"}', 'kb-doc-09-mitre-attack-p0-387', 0, 251, '09-mitre-attack', 'retrieved', '871D4F5D57CA0CC0A93E223776650B4223EFE79E7B61A2B03042C11F74BBE9E7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
