VALUES ('doc-09-mitre-attack-p0-390', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Taidoor"], "created": "2017-05-31T21:31:52.018Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Taidoor](https://attack.mitre.org/groups/G0015) has been deprecated, as the only technique it was linked to was deprecated in ATT&CK v7.", "external_references": [{"external_id": "G0015", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0015"}], "id": "intrusion-set--59140a2e-d117-4206-9b2c-2a8662bd9d46", "modified": "2026-07-31T18:48:41.286Z", "name": "Taidoor", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-390', 0, 53, '09-mitre-attack', 'retrieved', '0F1ED0E71DCC4AC64B20EBA6CCB66F7413013FD3BD42673B7FEF8C4E93BB9B4F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
