VALUES ('doc-09-mitre-attack-p0-391', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Suckfly"], "created": "2017-05-31T21:32:06.777Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Suckfly](https://attack.mitre.org/groups/G0039) is a China-based threat group that has been active since at least 2014. (Citation: Symantec Suckfly March 2016)", "external_references": [{"external_id": "G0039", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0039"}, {"description": "(Citation: Symantec Suckfly March 2016) (Citation: Symantec Suckfly May 2016)", "source_name": "Suckfly"}, {"description": "DiMaggio, J. (2016, March 15). Suckfly: Revealing the secret life of your code signing certificates. Retrieved August 3, 2016.", "source_name": "Symantec Suckfly March 2016", "url": "http://www.symantec.com/connect/blogs/suckfly-revealing-secret-life-your-code-signing-certificates"}, {"description": "DiMaggio, J. (2016, May 17). Indian organizations targeted in Suckfly attacks. Retrieved August 3, 2016.", "source_name": "Symantec Suckfly May 2016", "url": "http://www.symantec.com/connect/blogs/indian-organizations-targeted-suckfly-attacks"}], "id": "intrusion-set--5cbe0d3b-6fb1-471f-b591-4b192915116d", "modified": "2026-07-31T18:47:57.501Z", "name": "Suckfly", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-391', 0, 120, '09-mitre-attack', 'retrieved', '8C1F7E377B3D374881537B2A7BDF5956FD26F01361A372F16A689E4A3FE606A6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
