VALUES ('doc-09-mitre-attack-p0-395', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["TA459"], "created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TA459](https://attack.mitre.org/groups/G0062) is a threat group believed to operate out of China that has targeted countries including Russia, Belarus, Mongolia, and others. (Citation: Proofpoint TA459 April 2017)", "external_references": [{"external_id": "G0062", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0062"}, {"description": "(Citation: Proofpoint TA459 April 2017)", "source_name": "TA459"}, {"description": "Axel F. (2017, April 27). APT Targets Financial Analysts with CVE-2017-0199. Retrieved February 15, 2018.", "source_name": "Proofpoint TA459 April 2017", "url": "https://www.proofpoint.com/us/threat-insight/post/apt-targets-financial-analysts"}], "id": "intrusion-set--62a64fd3-aaf7-4d09-a375-d6f8bb118481", "modified": "2026-07-31T18:47:58.066Z", "name": "TA459", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Valerii Marchuk, Cybersecurity Help s.r.o."], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-395', 0, 101, '09-mitre-attack', 'retrieved', '216DA52023E2906E8B9D2772ACF880FCEB1C7918D1723AD5A82134ADF923DE9E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
