VALUES ('doc-09-mitre-attack-p0-396', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Aquatic Panda"], "created": "2022-01-18T14:49:29.505Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Aquatic Panda](https://attack.mitre.org/groups/G0143) is a suspected China-based threat group with a dual mission of intelligence collection and industrial espionage. Active since at least May 2020, [Aquatic Panda](https://attack.mitre.org/groups/G0143) has primarily targeted entities in the telecommunications, technology, and government sectors.(Citation: CrowdStrike AQUATIC PANDA December 2021)", "external_references": [{"external_id": "G0143", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0143"}, {"description": "Wiley, B. et al. (2021, December 29). OverWatch Exposes AQUATIC PANDA in Possession of Log4Shell Exploit Tools During Hands-on Intrusion Attempt. Retrieved January 18, 2022.", "source_name": "CrowdStrike AQUATIC PANDA December 2021", "url": "https://www.crowdstrike.com/blog/overwatch-exposes-aquatic-panda-in-possession-of-log-4-shell-exploit-tools/"}], "id": "intrusion-set--64b52e7d-b2c4-4a02-9372-08a463f5dc11", "modified": "2026-07-31T18:47:58.464Z", "name": "Aquatic Panda", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["NST Assure Research Team, NetSentries Technologies", "Pooja Natarajan, NEC Corporation India", "Hiroki Nagahama, NEC Corporation", "Manikantan Srinivasan, NEC Corporation India", "Jai Minton, CrowdStrike", "Jennifer Kim Roman, CrowdStrike"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-396', 0, 144, '09-mitre-attack', 'retrieved', '04AD78E9B8E2960D5E5A669BEB50A0ED80F919A7518EFA8A4D2FBBEE645F1378', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
