VALUES ('doc-09-mitre-attack-p0-398', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Ferocious Kitten"], "created": "2021-09-28T17:41:12.950Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Ferocious Kitten](https://attack.mitre.org/groups/G0137) is a threat group that has primarily targeted Persian-speaking individuals in Iran since at least 2015.(Citation: Kaspersky Ferocious Kitten Jun 2021)", "external_references": [{"external_id": "G0137", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0137"}, {"description": "GReAT. (2021, June 16). Ferocious Kitten: 6 Years of Covert Surveillance in Iran. Retrieved September 22, 2021.", "source_name": "Kaspersky Ferocious Kitten Jun 2021", "url": "https://securelist.com/ferocious-kitten-6-years-of-covert-surveillance-in-iran/102806/"}], "id": "intrusion-set--6566aac9-dad8-4332-ae73-20c23bad7f02", "modified": "2026-07-31T18:47:58.927Z", "name": "Ferocious Kitten", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Pooja Natarajan, NEC Corporation India", "Manikantan Srinivasan, NEC Corporation India", "Hiroki Nagahama, NEC Corporation"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-398', 0, 104, '09-mitre-attack', 'retrieved', 'FCBCF99B58464EA0DDA68CA4E14F09F74A18CB3855C893A66B5FD94E40A2D359', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
