VALUES ('doc-09-mitre-attack-p0-399', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["The White Company"], "created": "2019-05-02T00:08:18.314Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[The White Company](https://attack.mitre.org/groups/G0089) is a likely state-sponsored threat actor with advanced capabilities. From 2017 through 2018, the group led an espionage campaign called Operation Shaheen targeting government and military organizations in Pakistan.(Citation: Cylance Shaheen Nov 2018)", "external_references": [{"external_id": "G0089", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0089"}, {"description": "Livelli, K, et al. (2018, November 12). Operation Shaheen. Retrieved May 1, 2019.", "source_name": "Cylance Shaheen Nov 2018", "url": "https://www.cylance.com/content/dam/cylance-web/en-us/resources/knowledge-center/resource-library/reports/WhiteCompanyOperationShaheenReport.pdf?_ga=2.161661948.1943296560.1555683782-1066572390.1555511517"}], "id": "intrusion-set--6688d679-ccdb-4f12-abf6-c7545dd767a4", "modified": "2026-07-31T18:47:59.296Z", "name": "The White Company", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-399', 0, 99, '09-mitre-attack', 'retrieved', 'C673AD825A2DD48C2A301D6BD8235A8C1600C8CA31313365F7F65E50FF3D2A23', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
