VALUES ('doc-09-mitre-attack-p0-403', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["APT1", "Comment Crew", "Comment Group", "Comment Panda"], "created": "2017-05-31T21:31:47.955Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT1](https://attack.mitre.org/groups/G0006) is a Chinese threat group that has been attributed to the 2nd Bureau of the People’s Liberation Army (PLA) General Staff Department’s (GSD) 3rd Department, commonly known by its Military Unit Cover Designator (MUCD) as Unit 61398. (Citation: Mandiant APT1)", "external_references": [{"external_id": "G0006", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0006"}, {"description": "(Citation: Mandiant APT1)", "source_name": "APT1"}, {"description": "(Citation: Mandiant APT1)", "source_name": "Comment Crew"}, {"description": "(Citation: Mandiant APT1)", "source_name": "Comment Group"}, {"description": "(Citation: CrowdStrike Putter Panda)", "source_name": "Comment Panda"}, {"description": "Mandiant. (n.d.). APT1 Exposing One of China’s Cyber Espionage Units. Retrieved July 18, 2016.", "source_name": "Mandiant APT1", "url": "https://www.fireeye.com/content/dam/fireeye-www/services/pdfs/mandiant-apt1-report.pdf"}, {"description": "Crowdstrike Global Intelligence Team. (2014, June 9). CrowdStrike Intelligence Report: Putter Panda. Retrieved January 22, 2016.", "source_name": "CrowdStrike Putter Panda", "url": "http://cdn0.vox-cdn.com/assets/4589853/crowdstrike-intelligence-report-putter-panda.original.pdf"}], "id": "intrusion-set--6a2e693f-24e5-451a-9f88-b36a108e5662", "modified": "2026-07-31T18:47:59.697Z", "name": "APT1", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.4"}', 'kb-doc-09-mitre-attack-p0-403', 0, 156, '09-mitre-attack', 'retrieved', '0686140B95C6E5021524F5CD1EB6AE9C4B5FA19DE6C579A76608B444FC2526F6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
