VALUES ('doc-09-mitre-attack-p0-404', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Frankenstein"], "created": "2020-05-11T15:21:09.438Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Frankenstein](https://attack.mitre.org/groups/G0101) is a campaign carried out between January and April 2019 by unknown threat actors. The campaign name comes from the actors'' ability to piece together several unrelated components.(Citation: Talos Frankenstein June 2019) ", "external_references": [{"external_id": "G0101", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0101"}, {"description": "Adamitis, D. et al. (2019, June 4). It''s alive: Threat actors cobble together open-source pieces into monstrous Frankenstein campaign. Retrieved May 11, 2020.", "source_name": "Talos Frankenstein June 2019", "url": "https://blog.talosintelligence.com/2019/06/frankenstein-campaign.html"}], "id": "intrusion-set--6b1b551c-d770-4f95-8cfc-3cd253c4c04e", "modified": "2026-07-31T18:48:41.289Z", "name": "Frankenstein", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": true, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-404', 0, 103, '09-mitre-attack', 'retrieved', 'D8AE92139E58B3FB69F054111A40FEBD3DF5ADCAEA763EEA485B93234412EDFA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
