VALUES ('doc-09-mitre-attack-p0-405', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["DarkHydrus"], "created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DarkHydrus](https://attack.mitre.org/groups/G0079) is a threat group that has targeted government agencies and educational institutions in the Middle East since at least 2016. The group heavily leverages open-source tools and custom payloads for carrying out attacks. (Citation: Unit 42 DarkHydrus July 2018) (Citation: Unit 42 Playbook Dec 2017)", "external_references": [{"external_id": "G0079", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0079"}, {"description": "(Citation: Unit 42 DarkHydrus July 2018)", "source_name": "DarkHydrus"}, {"description": "Falcone, R., et al. (2018, July 27). New Threat Actor Group DarkHydrus Targets Middle East Government. Retrieved August 2, 2018.", "source_name": "Unit 42 DarkHydrus July 2018", "url": "https://researchcenter.paloaltonetworks.com/2018/07/unit42-new-threat-actor-group-darkhydrus-targets-middle-east-government/"}, {"description": "Unit 42. (2017, December 15). Unit 42 Playbook Viewer. Retrieved December 20, 2017.", "source_name": "Unit 42 Playbook Dec 2017", "url": "https://pan-unit42.github.io/playbook_viewer/"}], "id": "intrusion-set--6b9ebeb5-20bf-48b0-afb7-988d769a2f01", "modified": "2026-07-31T20:48:36.928Z", "name": "DarkHydrus", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Oleg Skulkin, Group-IB"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-405', 0, 148, '09-mitre-attack', 'retrieved', '31168FB6BC7067EEE02C391BF3F17CA4DE523D9736B3506CA4C8714F0BB6B1B6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
