VALUES ('doc-09-mitre-attack-p0-409', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["MoustachedBouncer"], "created": "2023-09-25T18:11:05.672Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MoustachedBouncer](https://attack.mitre.org/groups/G1019) is a cyberespionage group that has been active since at least 2014 targeting foreign embassies in Belarus.(Citation: MoustachedBouncer ESET August 2023)", "external_references": [{"external_id": "G1019", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G1019"}, {"description": "Faou, M. (2023, August 10). MoustachedBouncer: Espionage against foreign diplomats in Belarus. Retrieved September 25, 2023.", "source_name": "MoustachedBouncer ESET August 2023", "url": "https://www.welivesecurity.com/en/eset-research/moustachedbouncer-espionage-against-foreign-diplomats-in-belarus/"}], "id": "intrusion-set--7251b44b-6072-476c-b8d9-a6e32c355b28", "modified": "2026-07-31T20:48:38.550Z", "name": "MoustachedBouncer", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack", "mobile-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-409', 0, 85, '09-mitre-attack', 'retrieved', 'A4B430744D59FE5331B35EA6D1E2D13AEE6459B17C1B15F78F86BAD5B9400712', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
