VALUES ('doc-09-mitre-attack-p0-411', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Blue Mockingbird"], "created": "2020-05-26T20:09:39.139Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Blue Mockingbird](https://attack.mitre.org/groups/G0108) is a cluster of observed activity involving Monero cryptocurrency-mining payloads in dynamic-link library (DLL) form on Windows systems. The earliest observed Blue Mockingbird tools were created in December 2019.(Citation: RedCanary Mockingbird May 2020)", "external_references": [{"external_id": "G0108", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0108"}, {"description": "Lambert, T. (2020, May 7). Introducing Blue Mockingbird. Retrieved May 26, 2020.", "source_name": "RedCanary Mockingbird May 2020", "url": "https://redcanary.com/blog/blue-mockingbird-cryptominer/"}], "id": "intrusion-set--73a80fab-2aa3-48e0-a4d0-3a4828200aee", "modified": "2026-07-31T18:48:01.934Z", "name": "Blue Mockingbird", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Tony Lambert, Red Canary"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-411', 0, 100, '09-mitre-attack', 'retrieved', '3E64A91E0F32E28816AE9CEA2892D673C4E74FD322FEB048B89170AE059FE13D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
