VALUES ('doc-09-mitre-attack-p0-412', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Winter Vivern", "TA473", "UAC-0114"], "created": "2024-07-29T22:23:03.779Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Winter Vivern is a group linked to Russian and Belorussian interests active since at least 2020 targeting various European government and NGO entities, along with sporadic targeting of Indian and US victims. The group leverages a combination of document-based phishing activity and server-side exploitation for initial access, leveraging adversary-controlled and -created infrastructure for follow-on command and control.(Citation: DomainTools WinterVivern 2021)(Citation: SentinelOne WinterVivern 2023)(Citation: CERT-UA WinterVivern 2023)(Citation: ESET WinterVivern 2023)(Citation: Proofpoint WinterVivern 2023)", "external_references": [{"external_id": "G1035", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G1035"}, {"description": "(Citation: CERT-UA WinterVivern 2023)", "source_name": "UAC-0114"}, {"description": "(Citation: Proofpoint WinterVivern 2023)", "source_name": "TA473"}, {"description": "CERT-UA. (2023, February 1). UAC-0114 aka Winter Vivern to target Ukrainian and Polish GOV entities (CERT-UA#5909). Retrieved July 29, 2024.", "source_name": "CERT-UA WinterVivern 2023", "url": "https://cert.gov.ua/article/3761104"}, {"description": "Chad Anderson. (2021, April 27). Winter Vivern: A Look At Re-Crafted Government MalDocs Targeting Multiple Languages. Retrieved July 29, 2024.", "source_name": "DomainTools WinterVivern 2021", "url": "https://www.domaintools.com/resources/blog/winter-vivern-a-look-at-re-crafted-government-maldocs/"}, {"description": "Matthieu Faou. (2023, October 25). Winter Vivern exploits zero-day vulnerability in Roundcube Webmail servers. Retrieved July 29, 2024.", "source_name": "ESET WinterVivern 2023", "url": "https://www.welivesecurity.com/en/eset-research/winter-vivern-exploits-zero-day-vulnerability-roundcube-webmail-servers/"}, {"description": "Michael Raggi & The Proofpoint Threat Research Team. (2023, March 30). Exploitation is a Dish Best Served Cold: Winter Vivern Uses Known Zimbra Vulnerability to Target Webmail Portals of NATO-Aligned Governments in Europe. Retrieved July 29, 2024.", "source_name": "Proofpoint WinterVivern 2023", "url": "https://www.proofpoint.com/us/blog/threat-insight/exploitation-dish-best-served-cold-winter-vivern-uses-known-zimbra-vulnerability"}, {"description": "Tom Hegel. (2023, March 16). Winter Vivern | Uncovering a Wave of Global Espionage. Retrieved July 29, 2024.", "source_name": "SentinelOne WinterVivern 2023", "url": "https://www.sentinelone.com/labs/winter-vivern-uncovering-a-wave-of-global-espionage/"}], "id": "intrusion-set--75a07184-a7e5-4222-95a1-a04dbc96a29c", "modified": "2026-07-31T18:48:02.493Z", "name": "Winter Vivern", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Onur Atali"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-412', 0, 279, '09-mitre-attack', 'retrieved', '1CA7C086848615DD34AE7420D6AB21D90D0FC5C8D54FFF59452726FC8AFDD62A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
