VALUES ('doc-09-mitre-attack-p0-418', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Poseidon Group"], "created": "2017-05-31T21:32:04.179Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Poseidon Group](https://attack.mitre.org/groups/G0033) is a Portuguese-speaking threat group that has been active since at least 2005. The group has a history of using information exfiltrated from victims to blackmail victim companies into contracting the [Poseidon Group](https://attack.mitre.org/groups/G0033) as a security firm. (Citation: Kaspersky Poseidon Group)", "external_references": [{"external_id": "G0033", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0033"}, {"description": "(Citation: Kaspersky Poseidon Group)", "source_name": "Poseidon Group"}, {"description": "Kaspersky Lab''s Global Research and Analysis Team. (2016, February 9). Poseidon Group: a Targeted Attack Boutique specializing in global cyber-espionage. Retrieved March 16, 2016.", "source_name": "Kaspersky Poseidon Group", "url": "https://securelist.com/poseidon-group-a-targeted-attack-boutique-specializing-in-global-cyber-espionage/73673/"}], "id": "intrusion-set--7ecc3b4f-5cdb-457e-b55a-df376b359446", "modified": "2026-07-31T18:48:04.495Z", "name": "Poseidon Group", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-418', 0, 122, '09-mitre-attack', 'retrieved', '78C3224F8CB1ECF10D9C76E46AE480965CA04121756EC16890CC669768626908', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
