VALUES ('doc-09-mitre-attack-p0-420', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["BITTER", "T-APT-17"], "created": "2022-06-01T20:26:53.880Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BITTER](https://attack.mitre.org/groups/G1002) is a suspected South Asian cyber espionage threat group that has been active since at least 2013. [BITTER](https://attack.mitre.org/groups/G1002) has targeted government, energy, and engineering organizations in Pakistan, China, Bangladesh, and Saudi Arabia.(Citation: Cisco Talos Bitter Bangladesh May 2022)(Citation: Forcepoint BITTER Pakistan Oct 2016)", "external_references": [{"external_id": "G1002", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G1002"}, {"description": "(Citation: Cisco Talos Bitter Bangladesh May 2022)", "source_name": "T-APT-17"}, {"description": "Dela Paz, R. (2016, October 21). BITTER: a targeted attack against Pakistan. Retrieved June 1, 2022.", "source_name": "Forcepoint BITTER Pakistan Oct 2016", "url": "https://www.forcepoint.com/blog/x-labs/bitter-targeted-attack-against-pakistan"}, {"description": "Raghuprasad, C . (2022, May 11). Bitter APT adds Bangladesh to their targets. Retrieved June 1, 2022.", "source_name": "Cisco Talos Bitter Bangladesh May 2022", "url": "https://blog.talosintelligence.com/2022/05/bitter-apt-adds-bangladesh-to-their.html"}], "id": "intrusion-set--7f848c02-4d1e-4808-a4ae-4670681370a9", "modified": "2026-07-31T20:48:39.235Z", "name": "BITTER", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack", "mobile-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-420', 0, 146, '09-mitre-attack', 'retrieved', '1841852998A6CB7C8C5D40F9C58740F35CD456CED5D7C750F541FA5FFD6269AC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
