VALUES ('doc-09-mitre-attack-p0-421', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["DarkVishnya"], "created": "2020-05-15T13:07:26.651Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DarkVishnya](https://attack.mitre.org/groups/G0105) is a financially motivated threat actor targeting financial institutions in Eastern Europe. In 2017-2018 the group attacked at least 8 banks in this region.(Citation: Securelist DarkVishnya Dec 2018)", "external_references": [{"external_id": "G0105", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0105"}, {"description": "(Citation: Securelist DarkVishnya Dec 2018)", "source_name": "DarkVishnya"}, {"description": "Golovanov, S. (2018, December 6). DarkVishnya: Banks attacked through direct connection to local network. Retrieved May 15, 2020.", "source_name": "Securelist DarkVishnya Dec 2018", "url": "https://securelist.com/darkvishnya/89169/"}], "id": "intrusion-set--813636db-3939-4a45-bea9-6113e970c029", "modified": "2026-07-31T18:48:04.496Z", "name": "DarkVishnya", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-421', 0, 101, '09-mitre-attack', 'retrieved', '82137D8995EB1A292FB6B10F88FF11572D26FAE224DA7979978B0259652B0C89', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
