VALUES ('doc-09-mitre-attack-p0-422', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["RedCurl"], "created": "2024-09-23T21:32:19.337Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RedCurl](https://attack.mitre.org/groups/G1039) is a threat actor active since 2018 notable for corporate espionage targeting a variety of locations, including Ukraine, Canada and the United Kingdom, and a variety of industries, including but not limited to travel agencies, insurance companies, and banks.(Citation: group-ib_redcurl1) [RedCurl](https://attack.mitre.org/groups/G1039) is allegedly a Russian-speaking threat actor.(Citation: group-ib_redcurl1)(Citation: group-ib_redcurl2) The group’s operations typically start with spearphishing emails to gain initial access, then the group executes discovery and collection commands and scripts to find corporate data. The group concludes operations by exfiltrating files to the C2 servers. ", "external_references": [{"external_id": "G1039", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G1039"}, {"description": "Group-IB. (2020, August). RedCurl: The Pentest You Didn’t Know About. Retrieved August 9, 2024.", "source_name": "group-ib_redcurl1", "url": "https://www.group-ib.com/resources/research-hub/red-curl/"}, {"description": "Group-IB. (2021, November). RedCurl: The Awakening. Retrieved August 14, 2024.", "source_name": "group-ib_redcurl2", "url": "https://www.group-ib.com/resources/research-hub/red-curl-2/"}], "id": "intrusion-set--82323c70-4186-4b61-94f5-b227c3b28e89", "modified": "2026-07-31T18:48:05.317Z", "name": "RedCurl", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Joe Gumke, U.S. Bank"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-422', 0, 165, '09-mitre-attack', 'retrieved', '23A86F270759454461BE4E007ABFC6A3021CF0E3E1B5CF8A031601C01CF410C3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
