VALUES ('doc-09-mitre-attack-p0-423', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["APT-C-23", "Mantis", "Arid Viper", "Desert Falcon", "TAG-63", "Grey Karkadann", "Big Bang APT", "Two-tailed Scorpion"], "created": "2024-03-26T18:38:00.759Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT-C-23](https://attack.mitre.org/groups/G1028) is a threat group that has been active since at least 2014.(Citation: symantec_mantis) [APT-C-23](https://attack.mitre.org/groups/G1028) has primarily focused its operations on the Middle East, including Israeli military assets. [APT-C-23](https://attack.mitre.org/groups/G1028) has developed mobile spyware targeting Android and iOS devices since 2017.(Citation: welivesecurity_apt-c-23)", "external_references": [{"external_id": "G1028", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G1028"}, {"description": "(Citation: checkpoint_interactive_map_apt-c-23) ", "source_name": "Big Bang APT"}, {"description": "(Citation: sentinelone_israel_hamas_war)", "source_name": "Grey Karkadann"}, {"description": "(Citation: symantec_mantis)(Citation: sentinelone_israel_hamas_war)", "source_name": "Mantis"}, {"description": "(Citation: welivesecurity_apt-c-23)", "source_name": "Two-tailed Scorpion"}, {"description": "(Citation: welivesecurity_apt-c-23)(Citation: sentinelone_israel_hamas_war)(Citation: fb_arid_viper)", "source_name": "Arid Viper"}, {"description": "(Citation: welivesecurity_apt-c-23)(Citation: sentinelone_israel_hamas_war)(Citation: fb_arid_viper)", "source_name": "Desert Falcon"}, {"description": "Flossman, M., Scott, M. (2021, April). Technical Paper // Taking Action Against Arid Viper. Retrieved November 17, 2024.", "source_name": "fb_arid_viper", "url": "https://web.archive.org/web/20231126111812/https:/about.fb.com/wp-content/uploads/2021/04/Technical-threat-report-Arid-Viper-April-2021.pdf"}, {"description": "Hegel, T., Milenkoski, A. (2023, October 24). The Israel-Hamas War | Cyber Domain State-Sponsored Activity of Interest. Retrieved March 4, 2024.", "source_name": "sentinelone_israel_hamas_war", "url": "https://web.archive.org/web/20240208234008/www.sentinelone.com/labs/the-israel-hamas-war-cyber-domain-state-sponsored-activity-of-interest/"}, {"description": "Kayal, A. (2018, August 26). Interactive Mapping of APT-C-23. Retrieved March 4, 2024.", "source_name": "checkpoint_interactive_map_apt-c-23", "url": "https://web.archive.org/web/20230604112435/https://research.checkpoint.com/2018/interactive-mapping-of-apt-c-23/"}, {"description": "Stefanko, L. (2020, September 30). APT‑C‑23 group evolves its Android spyware. Retrieved March 4, 2024.", "source_name": "welivesecurity_apt-c-23", "url": "https://web.archive.org/web/20201123042131/www.welivesecurity.com/2020/09/30/aptc23-group-evolves-its-android-spyware/"}, {"description": "Symantec Threat Hunter Team. (2023, April 4). Mantis: New Tooling Used in Attacks Against Palestinian Targets. Retrieved March 4, 2024.", "source_name": "symantec_mantis", "url": "https://web.archive.org/web/20231227054130/https://symantec-enterprise-blogs.security.com/blogs/threat-intelligence/mantis-palestinian-attacks"}], "id": "intrusion-set--8332952e-b86b-486b-acc3-1c2a85d39394", "modified": "2026-07-31T20:48:39.666Z", "name": "APT-C-23", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Sittikorn Sangrattanapitak"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack", "mobile-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-423', 0, 250, '09-mitre-attack', 'retrieved', '47CEE1C3E93D71CE85CD86C836265E18265697462A0D94D101127EF570523DBD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
