VALUES ('doc-09-mitre-attack-p0-425', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Mofang"], "created": "2020-05-12T21:23:59.021Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mofang](https://attack.mitre.org/groups/G0103) is a likely China-based cyber espionage group, named for its frequent practice of imitating a victim''s infrastructure. This adversary has been observed since at least May 2012 conducting focused attacks against government and critical infrastructure in Myanmar, as well as several other countries and sectors including military, automobile, and weapons industries.(Citation: FOX-IT May 2016 Mofang)", "external_references": [{"external_id": "G0103", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0103"}, {"description": "Yonathan Klijnsma. (2016, May 17). Mofang: A politically motivated information stealing adversary. Retrieved May 12, 2020.", "source_name": "FOX-IT May 2016 Mofang", "url": "https://foxitsecurity.files.wordpress.com/2016/06/fox-it_mofang_threatreport_tlp-white.pdf"}], "id": "intrusion-set--88489675-d216-4884-a98f-49a89fcc1643", "modified": "2026-07-31T18:48:06.005Z", "name": "Mofang", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-425', 0, 118, '09-mitre-attack', 'retrieved', 'A1EAFB4421009B97CF0465C7D214D034A7AEB785F60476A2FB99E99456183CC2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
