VALUES ('doc-09-mitre-attack-p0-427', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Stealth Falcon"], "created": "2017-05-31T21:32:06.390Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Stealth Falcon](https://attack.mitre.org/groups/G0038) is a threat group that has conducted targeted spyware attacks against Emirati journalists, activists, and dissidents since at least 2012. Circumstantial evidence suggests there could be a link between this group and the United Arab Emirates (UAE) government, but that has not been confirmed. (Citation: Citizen Lab Stealth Falcon May 2016)", "external_references": [{"external_id": "G0038", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0038"}, {"description": "(Citation: Citizen Lab Stealth Falcon May 2016)", "source_name": "Stealth Falcon"}, {"description": "Marczak, B. and Scott-Railton, J.. (2016, May 29). Keep Calm and (Don’t) Enable Macros: A New Threat Actor Targets UAE Dissidents. Retrieved June 8, 2016.", "source_name": "Citizen Lab Stealth Falcon May 2016", "url": "https://citizenlab.org/2016/05/stealth-falcon/"}], "id": "intrusion-set--894aab42-3371-47b1-8859-a4a074c804c8", "modified": "2026-07-31T18:48:06.436Z", "name": "Stealth Falcon", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-427', 0, 139, '09-mitre-attack', 'retrieved', '8A9273181756285E4DA6AE82D20B68E8B4399559BE659582025BD04AD350CE43', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
