VALUES ('doc-09-mitre-attack-p0-429', 'doc-09-mitre-attack', 'STIX object', NULL, '{"aliases": ["Dark Caracal"], "created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Dark Caracal](https://attack.mitre.org/groups/G0070) is threat group that has been attributed to the Lebanese General Directorate of General Security (GDGS) and has operated since at least 2012. (Citation: Lookout Dark Caracal Jan 2018)", "external_references": [{"external_id": "G0070", "source_name": "mitre-attack", "url": "https://attack.mitre.org/groups/G0070"}, {"description": "(Citation: Lookout Dark Caracal Jan 2018)", "source_name": "Dark Caracal"}, {"description": "Blaich, A., et al. (2018, January 18). Dark Caracal: Cyber-espionage at a Global Scale. Retrieved April 11, 2018.", "source_name": "Lookout Dark Caracal Jan 2018", "url": "https://info.lookout.com/rs/051-ESQ-475/images/Lookout_Dark-Caracal_srr_20180118_us_v.1.0.pdf"}], "id": "intrusion-set--8a831aaa-f3e0-47a3-bed8-a9ced744dd12", "modified": "2026-07-31T20:48:40.500Z", "name": "Dark Caracal", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "intrusion-set", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack", "mobile-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "1.4"}', 'kb-doc-09-mitre-attack-p0-429', 0, 109, '09-mitre-attack', 'retrieved', 'BED14B922330AC556C64B18EF57ECEB26BFB826B96A9D45FC2623C14D2FE6EFD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
